VOWELS = frozenset("aeiou")


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in text, case-insensitively."""
    if not isinstance(text, str):
        raise TypeError("count_vowels() expects a string")
    total = 0
    for char in text.lower():
        if char in VOWELS:
            total += 1
    return total


def count_consonants(text):
    """Return the number of alphabetic characters in text that are not vowels."""
    total = 0
    for char in text.lower():
        if char.isalpha() and char not in VOWELS:
            total += 1
    return total


def vowel_free_words(text):
    """Return the words of text that contain no vowel at all."""
    found = []
    for word in text.split():
        if all(char not in VOWELS for char in word.lower()):
            found.append(word)
    return found


def vowel_breakdown(text):
    """Map each vowel to how often it occurs in text."""
    counts = {}
    for char in text.lower():
        if char in VOWELS:
            counts[char] = counts.get(char, 0) + 1
    return counts


def missing_vowels(text):
    """Return the vowels, in alphabetical order, that never appear in text."""
    present = vowel_breakdown(text)
    return [vowel for vowel in sorted(VOWELS) if vowel not in present]


def unique_samples(samples):
    """Return the samples in their original order, without blanks or repeats."""
    ordered = []
    for sample in samples:
        if sample.strip() and sample not in ordered:
            ordered.append(sample)
    return ordered


def cached_count(sample, cache):
    """Return the vowel count of sample, computing it at most once per sample."""
    if sample not in cache:
        cache[sample] = count_vowels(sample)
    return cache[sample]


def format_report(text, cache):
    """Build a human-readable multi-line report about the vowels in text."""
    lines = ["Text: {!r}".format(text)]
    lines.append("Vowels: {}".format(cached_count(text, cache)))
    lines.append("Consonants: {}".format(count_consonants(text)))

    breakdown = vowel_breakdown(text)
    if breakdown:
        pieces = ["{}={}".format(v, breakdown[v]) for v in sorted(breakdown)]
        lines.append("Breakdown: " + ", ".join(pieces))
    else:
        lines.append("Breakdown: none")

    absent = missing_vowels(text)
    if absent:
        lines.append("Unused vowels: " + " ".join(absent))
    silent = vowel_free_words(text)
    if silent:
        lines.append("Vowel-free words: " + " ".join(silent))
    return "\n".join(lines)


def most_vowel_rich(samples, cache):
    """Return the sample with the most vowels; samples must not be empty."""
    return max(samples, key=lambda sample: cached_count(sample, cache))


def main():
    cache = {}
    samples = unique_samples(["Hello World", "Python", "   ", "Sequoia", "Python", "rhythm"])
    for sample in samples:
        print(format_report(sample, cache))
        print("-" * 32)
    winner = most_vowel_rich(samples, cache)
    print("Most vowel-rich sample: {!r} ({} vowels)".format(winner, cached_count(winner, cache)))


if __name__ == "__main__":
    main()

