_FACTORIAL_CACHE = {0: 1, 1: 1}

_DIGITS = "0123456789"

_SEPARATORS = " \t\n,;"


def calculate_factorial(n):
    """Return n! for a non-negative integer n, extending a shared memo cache."""
    if not isinstance(n, int):
        raise TypeError("factorial is only defined for integers, got %r" % (n,))
    if n < 0:
        raise ValueError("factorial is not defined for negative numbers")
    if n not in _FACTORIAL_CACHE:
        known = max(k for k in _FACTORIAL_CACHE if k <= n)
        value = _FACTORIAL_CACHE[known]
        for step in range(known + 1, n + 1):
            value *= step
            _FACTORIAL_CACHE[step] = value
    return _FACTORIAL_CACHE[n]


def tokenize(text):
    """Split a request on commas, semicolons or whitespace."""
    tokens = []
    current = ""
    for char in text:
        if char not in _SEPARATORS:
            current += char
        elif current:
            tokens.append(current)
            current = ""
    if current:
        tokens.append(current)
    return tokens


def parse_request(text):
    """Turn a separated string of signed integers into a list of ints."""
    numbers = []
    for token in tokenize(text):
        sign = -1 if token.startswith("-") else 1
        body = token.lstrip("+-")
        if not body:
            raise ValueError("not an integer: %r" % (token,))
        for char in body:
            if char not in _DIGITS:
                raise ValueError("not an integer: %r" % (token,))
        numbers.append(sign * int(body))
    return numbers


def unique_numbers(numbers):
    """Drop repeated requests so each factorial is reported only once."""
    ordered = []
    for n in numbers:
        if n not in ordered:
            ordered.append(n)
    return ordered


def format_row(n, value, width=30):
    digits = str(value)
    if len(digits) > width:
        digits = digits[: width - 3] + "..."
    return "%3d! = %s" % (n, digits)


def describe(n, value):
    """Render one result, noting the real size when the digits were cut."""
    line = format_row(n, value)
    if "..." not in line:
        return line
    return line + "  (%d digits)" % len(str(value))


def factorial_table(numbers):
    """Compute factorials for many inputs, collecting failures separately."""
    results = []
    errors = []
    for n in numbers:
        try:
            results.append((n, calculate_factorial(n)))
        except (TypeError, ValueError) as exc:
            errors.append((n, str(exc)))
    return results, errors


def trailing_zero_count(n):
    """Count the trailing zeros of n! without inspecting the whole number."""
    zeros = 0
    power = 5
    while power <= n:
        zeros += n // power
        power *= 5
    return zeros


def main():
    request = "0, 1, 5, 5, 10, 20; -3 25"
    numbers = unique_numbers(parse_request(request))
    results, errors = factorial_table(numbers)

    print("Requested:", request)
    for n, value in results:
        print(describe(n, value))
        zeros = trailing_zero_count(n)
        if zeros:
            print("    ends in %d zero(s)" % zeros)

    for n, message in errors:
        print("skipped %r: %s" % (n, message))


if __name__ == "__main__":
    main()

