        body = token
    if not body:
        raise ValueError("token %r has a sign but no digits" % token)
    for char in body:
        if char not in DIGITS:
            raise ValueError("token %r contains a non-digit %r" % (token, char))
    return int(token)


def split_tokens(text):
    """Split text on commas, semicolons, spaces and tabs."""
    tokens = []
    current = ""
    for char in text:
        if char not in SEPARATORS:
            current += char
        elif current:
            tokens.append(current)
            current = ""
    if current:
        tokens.append(current)
    return tokens


def parse_line(line):
    """Parse a possibly labelled line of separated integers."""
    name, values = split_label(line)
    tokens = split_tokens(values)
    if not tokens:
        raise ValueError("line %r holds no numbers" % line)
    return name, [parse_int(token) for token in tokens]


