    """Return the largest number in a non-empty list of integers."""
    for value in numbers:
        if not isinstance(value, int):
            raise TypeError("expected int, got %r" % (value,))
    largest = numbers[0]
    for value in numbers[1:]:
        if value > largest:
            largest = value
    return largest


