import re
import sys

WORD_RE = re.compile(r"[a-z0-9']+")
STOP_WORDS = frozenset({'the', 'a', 'an', 'and', 'or', 'of', 'to', 'in'})


def tokenize(text):
    """Split text into lowercase words, dropping punctuation."""
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    words = []
    for raw in WORD_RE.findall(text.lower()):
        word = raw.strip("'")
        if word:
            words.append(word)
    return words


def word_frequency(text):
    """Return a mapping of lowercase word -> number of occurrences."""
    counts = {}
    for word in tokenize(text):
        if word not in counts:
            counts[word] = 0
        counts[word] += 1
    return counts


def content_frequency(counts):
    """Copy of a frequency table with very common function words removed."""
    return {word: n for word, n in counts.items()
            if word not in STOP_WORDS}


def merge_frequencies(tables):
    """Combine several frequency dictionaries into one."""
    total = {}
    for table in tables:
        for word, n in table.items():
            if word not in total:
                total[word] = 0
            total[word] += n
    return total


def shared_words(tables):
    """Words that appear in every frequency table, alphabetically."""
    if not tables:
        return []
    shared = set(tables[0])
    for table in tables[1:]:
        absent = {word for word in shared if word not in table}
        shared -= absent
    return sorted(shared)


def read_sources(argv):
    """Map each input name to its text: named files, else standard input."""
    if len(argv) > 1:
        sources = {}
        for path in argv[1:]:
            if path not in sources:
                with open(path, encoding='utf-8') as handle:
                    sources[path] = handle.read()
        return sources
    return {'<stdin>': sys.stdin.read()}


def ranked(counts, limit=None):
    """Words sorted by descending frequency, then alphabetically."""
    order = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    if limit is None:
        return order
    return order[:limit]


def format_report(counts, limit=None):
    """Render a frequency table as aligned 'word count' lines."""
    rows = ranked(counts, limit)
    if not rows:
        return '(no words found)'
    width = max(len(word) for word, _ in rows)
    return '\n'.join('{0:<{1}}  {2}'.format(word, width, n) for word, n in rows)


def main(argv):
    sources = read_sources(argv)
    tables = [word_frequency(text) for text in sources.values()]
    total = merge_frequencies(tables)
    print(format_report(total, limit=10))
    trimmed = content_frequency(total)
    dropped = [word for word in total if word not in trimmed]
    if dropped:
        print('\nignored function words: ' + ', '.join(sorted(dropped)))
    if len(tables) > 1:
        print('\nin every source: ' + ', '.join(shared_words(tables)))
    print('\ntotal distinct words: {0}'.format(len(total)))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

