def find_longest_word(sentence):
    """Return the first longest word in the sentence, or '' if there is none."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    longest = ""
    for word in tokenize(sentence):
        if len(word) > len(longest):
            longest = word
    return longest

def word_counts(sentence):
    """Count occurrences of each word, ignoring case differences."""
    counts = {}
    for word in tokenize(sentence):
        key = word.lower()
        if not key in counts:
            counts[key] = 0
        counts[key] += 1
    return counts

def words_of_max_length(sentence):
    """All distinct words tied for the maximum length, in order of appearance."""
    longest = find_longest_word(sentence)
    ties = []
    for word in tokenize(sentence):
        if len(word) == len(longest) and not word in ties:
            ties.append(word)
    return ties

def is_pangram(sentence):
    seen = set(sentence.lower())
    for letter in ALPHABET:
        if not letter in seen:
            return False
    return True

def report(sentence):
    """Build a human-readable summary of the sentence's longest word."""
    longest = find_longest_word(sentence)
    if not longest:
        return "no words found"
    lines = ["sentence: %r" % sentence,
             "longest: %s (%d letters)" % (longest, len(longest))]
    ties = words_of_max_length(sentence)
    if len(ties) > 1:
        lines.append("tied with: " + ", ".join(w for w in ties if w != longest))
    repeats = sorted(w for w, n in word_counts(sentence).items() if n > 1)
    if repeats:
        lines.append("repeated: " + ", ".join(repeats))
    if is_pangram(sentence):
        lines.append("bonus: sentence is a pangram")
    return "\n".join(lines)

def main():
    samples = ["The quick brown fox",
               "Hello world",
               "Pack my box with five dozen liquor jugs, quickly!",
               "   "]
    for sample in samples:
        print(report(sample))
        print("-" * 40)

if __name__ == "__main__":
    main()

