def list_intersection(list1, list2):
    """Return the elements of list1 that also occur in list2, without duplicates.

    Membership is tested with ``in``, so the lists may hold unhashable values
    such as other lists or dictionaries.
    """
    result = []
    for item in list1:
        if item not in list2:
            continue
        if item not in result:
            result.append(item)
    return result


def list_difference(list1, list2):
    """Return the elements of list1 that are absent from list2, without duplicates."""
    result = []
    for item in list1:
        if item not in list2:
            if item not in result:
                result.append(item)
    return result


def list_union(list1, list2):
    """Return every value of both lists, in first-seen order and without duplicates."""
    result = []
    for item in list(list1) + list(list2):
        if item not in result:
            result.append(item)
    return result


def list_symmetric_difference(list1, list2):
    """Return the values that belong to exactly one of the two lists."""
    common = list_intersection(list1, list2)
    result = []
    for item in list_union(list1, list2):
        if item not in common:
            result.append(item)
    return result


def describe(list1, list2):
    """Build a short human-readable comparison of two lists."""
    common = list_intersection(list1, list2)
    lines = ["%r vs %r" % (list1, list2)]
    lines.append("  common:        %r" % (common,) if common else "  common:        none")
    lines.append("  only in first: %r" % (list_difference(list1, list2),))
    lines.append("  only in second:%r" % (list_difference(list2, list1),))
    lines.append("  exactly one:   %r" % (list_symmetric_difference(list1, list2),))
    lines.append("  all values:    %r" % (list_union(list1, list2),))
    return "\n".join(lines)


