_CACHE = {0: [], 1: [0], 2: [0, 1]}

_DIGITS = "0123456789"

_STYLES = {
    "csv": ", ".join,
    "lines": "\n".join,
    "spaced": " ".join,
}


def parse_count(text):
    """Turn a command line argument into a non-negative sequence length."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("empty count")
    for ch in cleaned:
        if ch not in _DIGITS:
            raise ValueError("not a non-negative integer: " + repr(text))
    return int(cleaned)


def fibonacci_sequence(n):
    """Return the first n Fibonacci numbers, starting 0, 1, 1, 2, 3, ..."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n not in _CACHE:
        best = max(k for k in _CACHE if k <= n)
        values = list(_CACHE[best])
        while len(values) < n:
            if len(values) < 2:
                values.append(len(values))
            else:
                values.append(values[-1] + values[-2])
        _CACHE[n] = values
    return list(_CACHE[n])


def unique_fibonacci(n):
    """The first n Fibonacci numbers with the duplicated 1 removed."""
    result = []
    for value in fibonacci_sequence(n):
        if value not in result:
            result.append(value)
    return result


def fibonacci_index(value, limit):
    """Position of value among the first limit terms, or -1 if absent."""
    sequence = fibonacci_sequence(limit)
    if value not in sequence:
        return -1
    return sequence.index(value)


def format_sequence(numbers, style="csv"):
    """Render the numbers using one of the known output styles."""
    if style not in _STYLES:
        raise ValueError("unknown style: " + repr(style))
    return _STYLES[style](str(value) for value in numbers)


def main(argv):
    args = [a for a in argv[1:] if not a.startswith("--")]
    style = "lines" if "--lines" in argv else "csv"
    try:
        count = parse_count(args[0]) if args else 10
        probe = parse_count(args[1]) if len(args) > 1 else None
    except ValueError as exc:
        print("bad argument: {0}".format(exc))
        return 1
    print(format_sequence(fibonacci_sequence(count), style))
    if "--unique" in argv:
        print("unique: " + format_sequence(unique_fibonacci(count)))
    if probe is not None:
        position = fibonacci_index(probe, count)
        if position < 0:
            print("{0} is not among the first {1} terms".format(probe, count))
        else:
            print("{0} appears at index {1}".format(probe, position))
    return 0


