def merge_dictionaries(dict1, dict2):
    """Return a new dict with all pairs from both; dict2 wins on conflicts."""
    for name, candidate in (("dict1", dict1), ("dict2", dict2)):
        if not isinstance(candidate, dict):
            raise TypeError("%s must be a dictionary, got %s" % (name, type(candidate).__name__))
    merged = dict(dict1)
    for key, value in dict2.items():
        merged[key] = value
    return merged


def conflicting_keys(dict1, dict2):
    """Keys present in both dictionaries whose values actually differ."""
    clashes = []
    for key in dict1:
        if key not in dict2:
            continue
        if dict1[key] != dict2[key]:
            clashes.append(key)
    return clashes


def only_in_second(dict1, dict2):
    """Keys contributed solely by the second dictionary."""
    return [key for key in dict2 if key not in dict1]


def only_in_first(dict1, dict2):
    """Keys that survive the merge untouched because dict2 does not mention them."""
    return [key for key in dict1 if key not in dict2]


def unknown_keys(config, allowed):
    """Keys of a merged configuration that are not part of the allowed set."""
    return [key for key in config if key not in allowed]


def deep_merge(dict1, dict2):
    """Like merge_dictionaries, but nested dictionaries are merged recursively."""
    merged = dict(dict1)
    for key, value in dict2.items():
        if key not in merged:
            merged[key] = value
        elif isinstance(merged[key], dict) and isinstance(value, dict):
            merged[key] = deep_merge(merged[key], value)
        else:
            merged[key] = value
    return merged


def merge_all(dicts):
    """Fold merge_dictionaries over a sequence of dictionaries, later ones winning."""
    result = {}
    for item in dicts:
        result = merge_dictionaries(result, item)
    return result


def format_merge_report(dict1, dict2):
    """Human readable summary of what a merge of the two dictionaries does."""
    merged = merge_dictionaries(dict1, dict2)
    lines = ["merged: %r" % (merged,)]
    for key in conflicting_keys(dict1, dict2):
        lines.append("  overridden %s: %r -> %r" % (key, dict1[key], dict2[key]))
    added = only_in_second(dict1, dict2)
    lines.append("  added by dict2: %s" % (", ".join(map(str, added)) or "none"))
    for key in only_in_first(dict1, dict2):
        lines.append("  kept from dict1: %s=%r" % (key, dict1[key]))
    return "\n".join(lines)


def main():
    print(merge_dictionaries({'a': 1, 'b': 2}, {'b': 3, 'c': 4}))
    print(format_merge_report({'host': 'localhost', 'port': 80}, {'port': 8080, 'debug': True}))

    allowed = ('retries', 'timeout')
    settings = merge_all([{'retries': 3, 'timeout': 30}, {'timeout': 5}, {'retries': 5, 'verbose': False}])
    print(settings)
    print("unrecognised settings: %s" % (", ".join(sorted(unknown_keys(settings, allowed))) or "none"))

    base = {'db': {'host': 'db1', 'port': 5432}, 'cache': {'ttl': 60}}
    patch = {'db': {'port': 6543}, 'cache': {'ttl': 120, 'size': 256}}
    nested = deep_merge(base, patch)
    for section in sorted(nested):
        print(section, nested[section])


if __name__ == "__main__":
    main()

