INT_TYPES = (int,)
REQUIRED_FIELDS = ("name", "birth")
BANDS = (("child", 13), ("teen", 20), ("adult", 65), ("senior", None))
GROUP_ORDER = tuple(label for label, _ in BANDS)


def calculate_age(birth_year, current_year):
    """Return the age of a person born in `birth_year` as of `current_year`."""
    for label, value in (("birth_year", birth_year), ("current_year", current_year)):
        if type(value) not in INT_TYPES:
            raise TypeError("%s must be an int, got %r" % (label, value))
    if current_year < birth_year:
        raise ValueError("current_year %d precedes birth_year %d" % (current_year, birth_year))
    return current_year - birth_year


def parse_record(line):
    """Parse a 'name=Ada;birth=1990' style line into a dictionary."""
    record = {}
    for chunk in line.split(";"):
        chunk = chunk.strip()
        if not chunk:
            continue
        if "=" not in chunk:
            raise ValueError("malformed field %r" % chunk)
        key, raw = chunk.split("=", 1)
        key = key.strip()
        if key not in REQUIRED_FIELDS:
            raise ValueError("unknown field %r" % key)
        record[key] = raw.strip()
    for field in REQUIRED_FIELDS:
        if field not in record:
            raise ValueError("missing field %r in %r" % (field, line))
    record["birth"] = int(record["birth"])
    return record


def age_group(age):
    for label, upper in BANDS:
        if upper is None or age < upper:
            return label
    raise ValueError("no band matches age %d" % age)


def load_people(lines):
    """Parse lines, skipping comments and repeated names."""
    people = []
    seen = set()
    for line in lines:
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        record = parse_record(text)
        if record["name"] not in seen:
            seen.add(record["name"])
            people.append(record)
    return people


def summarize(people, current_year):
    counts = {}
    for record in people:
        group = age_group(calculate_age(record["birth"], current_year))
        if group not in counts:
            counts[group] = 0
        counts[group] += 1
    return counts


def format_report(people, current_year):
    lines = []
    for record in people:
        age = calculate_age(record["birth"], current_year)
        lines.append("%-8s %3d  %s" % (record["name"], age, age_group(age)))
    counts = summarize(people, current_year)
    lines.append("-" * 24)
    for group in GROUP_ORDER:
        if group not in counts:
            continue
        lines.append("%-8s %3d" % (group, counts[group]))
    return "\n".join(lines)


def main():
    data = [
        "# name;birth",
        "name=Ada;birth=1990",
        "name=Ada;birth=1991",
        "name=Linus;birth=2000",
        "name=Grace;birth=1906",
        "name=Kid;birth=2018",
    ]
    current_year = 2023
    print(format_report(load_people(data), current_year))
    print("check:", calculate_age(1990, 2023), calculate_age(2000, 2000))


if __name__ == "__main__":
    main()

