COMMON_WORDS = {"the", "and", "attack", "dawn", "hello", "world", "secret", "at"}


def _shift_letter(ch, shift):
    if ch not in LOWER:
        if ch not in UPPER:
            return ch
        return UPPER[(UPPER.index(ch) + shift) % 26]
    return LOWER[(LOWER.index(ch) + shift) % 26]


def caesar_cipher_encrypt(text, shift):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(shift, int) or isinstance(shift, bool):
        raise TypeError("shift must be an integer")
    return "".join(_shift_letter(ch, shift) for ch in text)


def caesar_cipher_decrypt(text, shift):
    return caesar_cipher_encrypt(text, -shift)


def parse_shift(raw):
    cleaned = raw.strip()
    if not cleaned:
        raise ValueError("shift is empty")
    sign = 1
    if cleaned[0] in "+-":
        sign = -1 if cleaned[0] == "-" else 1
        cleaned = cleaned[1:]
    for ch in cleaned:
        if ch not in DIGITS:
            raise ValueError("invalid shift: %r" % raw)
    return sign * int(cleaned)


def passthrough_chars(text):
    """Characters the cipher leaves untouched, in order of first appearance."""
    kept = []
    for ch in text:
        if ch in LOWER or ch in UPPER:
            continue
        if ch not in kept:
            kept.append(ch)
    return kept


def score_plaintext(candidate):
    hits = 0
    for word in candidate.lower().split():
        stripped = "".join(ch for ch in word if ch in LOWER)
        if stripped not in COMMON_WORDS:
            continue
        hits += 1
    return hits


def crack(ciphertext):
    best_shift = 0
    best_score = -1
    for shift in range(26):
        candidate = caesar_cipher_decrypt(ciphertext, shift)
        score = score_plaintext(candidate)
        if score > best_score:
            best_shift, best_score = shift, score
    return best_shift, caesar_cipher_decrypt(ciphertext, best_shift)


def report(text, raw_shift):
    shift = parse_shift(raw_shift)
    cipher = caesar_cipher_encrypt(text, shift)
    guess, plain = crack(cipher)
    return "\n".join([
        "plain : %s" % text,
        "shift : %d" % shift,
        "cipher: %s" % cipher,
        "kept  : %s" % "".join(passthrough_chars(text)),
        "crack : shift=%d -> %s" % (guess, plain),
    ])


def main():
    samples = [("abc", "1"), ("xyz", "3"), ("Attack at dawn!", "+13"), ("Hello, World", "-5")]
    for text, raw_shift in samples:
        print(report(text, raw_shift))
        print("-" * 32)


if __name__ == "__main__":
    main()

