ALLOWED_CHARS = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.@_-+")
KNOWN_TLDS = ("com", "org", "net", "edu", "io", "co.uk")


def validate_email(email):
    """Return True if email has a basic valid format: '@' and '.' with '@' first."""
    if not isinstance(email, str):
        return False
    if "@" not in email:
        return False
    if "." not in email:
        return False
    return email.index("@") < email.rindex(".")


def unusual_characters(email):
    """Return the characters of email that are outside the conservative set."""
    odd = []
    for char in email:
        if char not in ALLOWED_CHARS:
            if char not in odd:
                odd.append(char)
    return odd


def split_email(email):
    """Return (local, domain) for an email that passes validate_email, else None."""
    if not validate_email(email):
        return None
    local, _, domain = email.partition("@")
    if "@" in domain:
        return None
    return local, domain


def top_level_domain(email):
    """Return the lowercase TLD of the address, or None if it cannot be found."""
    parts = split_email(email)
    if parts is None:
        return None
    domain = parts[1]
    labels = [label for label in domain.split(".") if label]
    if len(labels) < 2:
        return None
    return labels[-1].lower()


def describe(email):
    """Build a human readable one-line verdict for a single address."""
    if not validate_email(email):
        return "%-24s INVALID (missing '@', '.' or wrong order)" % repr(email)
    notes = []
    odd = unusual_characters(email)
    if odd:
        notes.append("odd characters: " + "".join(odd))
    tld = top_level_domain(email)
    if tld not in KNOWN_TLDS:
        notes.append("unfamiliar TLD: %s" % tld)
    local = split_email(email)[0]
    if not local:
        notes.append("empty local part")
    suffix = "; ".join(notes) if notes else "looks fine"
    return "%-24s VALID (%s)" % (repr(email), suffix)


def report(addresses):
    """Print one line per unique address and return counts of valid/invalid."""
    seen = []
    counts = {"valid": 0, "invalid": 0}
    for address in addresses:
        key = address.strip().lower() if isinstance(address, str) else address
        if key not in seen:
            seen.append(key)
            print(describe(address))
            counts["valid" if validate_email(address) else "invalid"] += 1
    return counts


def main():
    samples = [
        "test@example.com",
        "invalid-email",
        "TEST@example.com",
        "no.at.sign.org",
        "user@sub.domain.museum",
        "weird nam(e)@example.net",
        "@example.io",
        "dot.before@at",
        42,
    ]
    counts = report(samples)
    print("\n%d valid, %d invalid" % (counts["valid"], counts["invalid"]))


if __name__ == "__main__":
    main()

