import math
import sys

UNITS = {
    "m": ("metres", 1.0),
    "cm": ("centimetres", 0.01),
    "mm": ("millimetres", 0.001),
}
ALLOWED_CHARS = "0123456789.+-eE"
DEFAULT_UNIT = "m"


def circle_area(radius):
    if not isinstance(radius, (int, float)) or isinstance(radius, bool):
        raise TypeError("radius must be a real number")
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * float(radius) ** 2


def parse_radius(text):
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("empty input")
    for char in cleaned:
        if char not in ALLOWED_CHARS:
            raise ValueError("unexpected character %r" % (char,))
    return float(cleaned)


def area_in_square_metres(area, unit):
    if unit not in UNITS:
        raise ValueError("unknown unit %r" % (unit,))
    return area * UNITS[unit][1] ** 2


def format_area(radius, area, unit):
    return "r = {0:g} {1} -> area = {2:.6f} {1}^2".format(radius, unit, area)


def area_table(radii, unit):
    lines = []
    seen = []
    for value in radii:
        if value not in seen:
            seen.append(value)
            lines.append(format_area(value, circle_area(value), unit))
    return lines


def report(raw_values, unit):
    radii = []
    problems = []
    for raw in raw_values:
        try:
            radius = parse_radius(raw)
        except ValueError as exc:
            message = "%r rejected: %s" % (raw, exc)
            if message not in problems:
                problems.append(message)
            continue
        if radius < 0:
            problems.append("%r rejected: negative radius" % (raw,))
        else:
            radii.append(radius)
    lines = area_table(radii, unit)
    total = sum(area_in_square_metres(circle_area(r), unit) for r in radii)
    lines.append("total area = {0:.6f} m^2".format(total))
    lines.extend(problems)
    return lines


def split_arguments(args):
    unit = DEFAULT_UNIT
    values = []
    for arg in args:
        if arg not in UNITS:
            values.append(arg)
        else:
            unit = arg
    return unit, values


def main():
    unit, values = split_arguments(sys.argv[1:])
    if not values:
        values = ["1", "0", " 2.5 ", "1", "-3", "4x", ""]
    print("radii given in", UNITS[unit][0])
    for line in report(values, unit):
        print(line)


if __name__ == "__main__":
    main()

