text_nat:
MONTH_LENGTHS = {
    1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
    7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31,
}

MONTH_ALIASES = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}


def is_leap_year(year):
    if year % 4 != 0:
        return False
    if year % 100 != 0:
        return True
    return year % 400 == 0


def days_in_month(year, month):
    if month not in MONTH_LENGTHS:
        raise ValueError(f"month out of range: {month}")
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month]


def format_date(year, month, day):
    for name, value in (("year", year), ("month", month), ("day", day)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{name} must be an int, got {value!r}")
    if month not in MONTH_LENGTHS:
        raise ValueError(f"month must be between 1 and 12, got {month}")
    limit = days_in_month(year, month)
    if day not in range(1, limit + 1):
        raise ValueError(f"day must be between 1 and {limit}, got {day}")
    return f"{year:04d}-{month:02d}-{day:02d}"


def parse_month(token):
    token = token.strip().lower()
    if token.isdigit():
        return int(token)
    key = token[:3]
    if key not in MONTH_ALIASES:
        raise ValueError(f"unrecognised month name: {token!r}")
    return MONTH_ALIASES[key]


def format_loose_date(text):
    parts = [p for p in text.replace(",", " ").split() if p]
    if len(parts) != 3:
        raise ValueError(f"expected 'month day year', got {text!r}")
    month = parse_month(parts[0])
    day_token = parts[1].rstrip("stndrh")
    if not day_token.isdigit():
        raise ValueError(f"bad day component: {parts[1]!r}")
    year_token = parts[2]
    if not year_token.isdigit():
        raise ValueError(f"bad year component: {year_token!r}")
    return format_date(int(year_token), month, int(day_token))


def report(entries):
    lines = []
    seen = set()
    for entry in entries:
        try:
            if isinstance(entry, str):
                stamp = format_loose_date(entry)
            else:
                stamp = format_date(*entry)
        except (TypeError, ValueError) as exc:
            lines.append(f"{entry!r}: ERROR ({exc})")
            continue
        if stamp not in seen:
            seen.add(stamp)
            lines.append(f"{entry!r}: {stamp}")
        else:
            lines.append(f"{entry!r}: {stamp} (duplicate)")
    return "\n".join(lines)


