RESPONSES = ('Too high', 'Too low', 'Correct!')
QUIT_WORDS = ('quit', 'exit', 'stop')


def guess_number(secret_number, guess):
    """Compare a guess against the secret number and describe the result."""
    if guess > secret_number:
        return 'Too high'
    if guess < secret_number:
        return 'Too low'
    return 'Correct!'


def parse_guess(text, low=1, high=100):
    """Turn raw user input into an int, or raise ValueError with a reason."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError('please type a number')
    digits = cleaned.lstrip('+-')
    if not digits:
        raise ValueError('%r is not a whole number' % cleaned)
    for ch in digits:
        if ch not in '0123456789':
            raise ValueError('%r is not a whole number' % cleaned)
    value = int(cleaned)
    if value not in range(low, high + 1):
        raise ValueError('%d is outside %d-%d' % (value, low, high))
    return value


def play_round(secret_number, text, history, low=1, high=100):
    """Handle one turn; returns (response, message) where response may be None."""
    word = text.strip().lower()
    if word not in QUIT_WORDS:
        try:
            guess = parse_guess(text, low, high)
        except ValueError as err:
            return None, 'Invalid input: %s' % err
        if guess not in history:
            history.append(guess)
            response = guess_number(secret_number, guess)
            return response, '%d -> %s' % (guess, response)
        return None, 'You already tried %d.' % guess
    return None, 'Giving up? The number was %d.' % secret_number


def narrow_range(low, high, guess, response):
    """Shrink the plausible interval using the feedback for one guess."""
    if response not in RESPONSES:
        raise ValueError('unknown response %r' % response)
    if response == 'Too high':
        return low, min(high, guess - 1)
    if response == 'Too low':
        return max(low, guess + 1), high
    return guess, guess


def summarise(history, secret_number):
    """Build the end-of-game report."""
    lines = ['Guesses made: %d' % len(history)]
    if secret_number not in history:
        lines.append('The secret number %d was never found.' % secret_number)
    else:
        lines.append('Found %d after %d tries.' % (secret_number, history.index(secret_number) + 1))
    return '\n'.join(lines)


def main():
    secret_number = 42
    low, high = 1, 100
    history = []
    scripted = ['50', 'fifty', '25', '25', '150', '43', '42', '7']
    for text in scripted:
        response, message = play_round(secret_number, text, history, low, high)
        print(message)
        if response is None:
            if text.strip().lower() in QUIT_WORDS:
                break
            continue
        low, high = narrow_range(low, high, history[-1], response)
        print('  remaining range: %d-%d' % (low, high))
        if response == 'Correct!':
            break
    print(summarise(history, secret_number))


if __name__ == '__main__':
    main()

