COMMENT_PREFIXES = ("#", ";")
OPERATIONS_WITH_ITEM = ("enqueue",)
OPERATIONS_WITHOUT_ITEM = ("dequeue", "clear")
VALID_OPERATIONS = OPERATIONS_WITH_ITEM + OPERATIONS_WITHOUT_ITEM


def validate_operation(operation):
    """Check a single (name, payload) tuple and return it normalised."""
    if not isinstance(operation, tuple) or len(operation) != 2:
        raise ValueError("each operation must be a (name, item) tuple: %r" % (operation,))
    name, item = operation
    if name not in VALID_OPERATIONS:
        raise ValueError("unknown operation %r" % (name,))
    if name not in OPERATIONS_WITH_ITEM and item is not None:
        raise ValueError("%s takes no item, got %r" % (name, item))
    return name, item


def parse_operations(text):
    """Turn a textual script ("enqueue 1", "dequeue", ...) into operation tuples."""
    operations = []
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if line and line[0] not in COMMENT_PREFIXES:
            parts = line.split(None, 1)
            name = parts[0].lower()
            if name not in VALID_OPERATIONS:
                raise ValueError("line %d: unknown operation %r" % (lineno, name))
            if name not in OPERATIONS_WITH_ITEM:
                operations.append((name, None))
            elif len(parts) < 2:
                raise ValueError("line %d: %s needs an item" % (lineno, name))
            else:
                token = parts[1].strip()
                operations.append((name, int(token) if token.lstrip("-").isdigit() else token))
    return operations


def simulate_queue(operations):
    """Simulate a FIFO queue with a list and return its final contents."""
    queue = []
    for operation in operations:
        name, item = validate_operation(operation)
        if name == "enqueue":
            queue.append(item)
        elif name == "clear":
            del queue[:]
        elif queue:
            queue.pop(0)
    return queue


def summarise(operations, final_queue):
    """Describe what happened: served items, leftovers and ignored dequeues."""
    enqueued = [item for name, item in operations if name == "enqueue"]
    served = [item for item in enqueued if item not in final_queue]
    underflows = 0
    depth = 0
    for name, _ in operations:
        if name == "enqueue":
            depth += 1
        elif name == "clear":
            depth = 0
        elif depth == 0:
            underflows += 1
        else:
            depth -= 1
