        elif name == "clear":
            depth = 0
        elif depth == 0:
            underflows += 1
        else:
            depth -= 1
    lines = ["remaining: %r" % (final_queue,)]
    if served:
        lines.append("served: %s" % ", ".join(repr(item) for item in served))
