import math

VALID_TYPES = (int, float)


def _check_number(name, value):
    if type(value) not in VALID_TYPES:
        raise TypeError("%s must be an int or float, got %r" % (name, value))
    if isinstance(value, float) and value != value:
        raise ValueError("%s must not be NaN" % name)
    return float(value)


def distance_2d(x1, y1, x2, y2):
    ax = _check_number("x1", x1)
    ay = _check_number("y1", y1)
    bx = _check_number("x2", x2)
    by = _check_number("y2", y2)
    dx = bx - ax
    dy = by - ay
    return math.sqrt(dx * dx + dy * dy)


def parse_point(text):
    cleaned = text.strip()
    for bracket in "()[]":
        cleaned = cleaned.replace(bracket, " ")
    if "," not in cleaned:
        parts = cleaned.split()
    else:
        parts = cleaned.split(",")
    if len(parts) != 2:
        raise ValueError("expected two coordinates in %r" % text)
    coords = []
    for part in parts:
        token = part.strip()
        if not token:
            raise ValueError("empty coordinate in %r" % text)
        coords.append(float(token))
    return coords[0], coords[1]


def unique_points(points):
    result = []
    for point in points:
        if point not in result:
            result.append(point)
    return result


def nearest_neighbor(target, candidates, visited=()):
    tx, ty = target
    best = None
    best_distance = None
    for point in candidates:
        if point != target and point not in visited:
            d = distance_2d(tx, ty, point[0], point[1])
            if best_distance is None or d < best_distance:
                best = point
                best_distance = d
    return best, best_distance


def nearest_neighbor_tour(points):
    tour = list(points[:1])
    while len(tour) < len(points):
        tour.append(nearest_neighbor(tour[-1], points, tour)[0])
    return tour


def path_length(points):
    total = 0.0
    for (x1, y1), (x2, y2) in zip(points, points[1:]):
        total += distance_2d(x1, y1, x2, y2)
    return total


def format_distance(value, precision=3):
    if precision not in range(0, 13):
        raise ValueError("precision out of supported range: %r" % precision)
    return ("%." + str(precision) + "f") % value


def main():
    raw = ["(0, 0)", "3,4", "[3 4]", "0 8", "1 1"]
    points = unique_points([parse_point(item) for item in raw])
    tour = nearest_neighbor_tour(points)
    for a, b in zip(tour, tour[1:]):
        leg = distance_2d(a[0], a[1], b[0], b[1])
        print("leg %s -> %s: %s" % (a, b, format_distance(leg, 2)))
    print("visited %d points, total %s" % (len(tour), format_distance(path_length(tour))))


if __name__ == "__main__":
    main()

