GRADE_BANDS = (("A", 90), ("B", 80), ("C", 70), ("D", 60))
VALID_GRADES = ("A", "B", "C", "D", "F")


def calculate_grade(score):
    """Return the letter grade for a numeric score between 0 and 100."""
    if type(score) not in (int, float):
        raise TypeError("score must be a number, got %r" % (score,))
    if score < 0 or score > 100:
        raise ValueError("score must be between 0 and 100, got %r" % (score,))
    for letter, floor in GRADE_BANDS:
        if score >= floor:
            return letter
    return "F"


def parse_record(line):
    """Turn 'name,score' into a (name, score) pair."""
    if "," not in line:
        raise ValueError("record must contain a comma: %r" % (line,))
    name, raw_score = (part.strip() for part in line.split(",", 1))
    if not name:
        raise ValueError("record is missing a name: %r" % (line,))
    try:
        score = float(raw_score)
    except ValueError:
        raise ValueError("score is not numeric: %r" % (raw_score,))
    if score.is_integer():
        score = int(score)
    return name, score


def grade_records(lines):
    """Grade every record, skipping duplicate names and malformed lines."""
    results = []
    seen = set()
    for line in lines:
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        try:
            name, score = parse_record(text)
        except ValueError as exc:
            results.append((text, None, str(exc)))
            continue
        if name not in seen:
            seen.add(name)
            results.append((name, score, calculate_grade(score)))
    return results


def tally(results):
    """Count how many students earned each letter grade."""
    counts = dict.fromkeys(VALID_GRADES, 0)
    for _, _, grade in results:
        if grade not in counts:
            continue
        counts[grade] += 1
    return counts


def format_report(results):
    lines = []
    for name, score, grade in results:
        if grade not in VALID_GRADES:
            lines.append("%-10s   skipped (%s)" % (name, grade))
        else:
            lines.append("%-10s %5s   %s" % (name, score, grade))
    counts = tally(results)
    summary = "  ".join("%s=%d" % (g, counts[g]) for g in VALID_GRADES)
    lines.append("-" * 26)
    lines.append(summary)
    return "\n".join(lines)


def main():
    data = [
        "Ada, 95",
        "Grace, 89.5",
        "Alan, 72",
        "Linus, 60",
        "Ada, 100",
        "Edsger, 41",
        "broken line",
    ]
    print(format_report(grade_records(data)))


if __name__ == "__main__":
    main()

