IGNORED = " \t\n\r"
ALPHABET = "abcdefghijklmnopqrstuvwxyz"


def normalize(text):
    """Lower-case the text and drop whitespace characters."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    cleaned = []
    for ch in text.lower():
        if ch not in IGNORED:
            cleaned.append(ch)
    return "".join(cleaned)


def char_counts(text):
    """Return (counts, order): occurrence counts and first-appearance order."""
    counts = {}
    order = []
    for ch in normalize(text):
        if ch not in counts:
            counts[ch] = 0
            order.append(ch)
        counts[ch] += 1
    return counts, order


def group_by_count(text):
    """Map each occurrence count to the characters reaching it, in first-seen order."""
    counts, order = char_counts(text)
    buckets = {}
    for ch in order:
        total = counts[ch]
        if total not in buckets:
            buckets[total] = []
        buckets[total].append(ch)
    return buckets


def non_letter_chars(text):
    """Counted characters that are not plain letters, in first-appearance order."""
    _counts, order = char_counts(text)
    return [ch for ch in order if ch not in ALPHABET]


def missing_letters(text):
    """Letters of the alphabet that never occur in the text."""
    counts, _order = char_counts(text)
    return [letter for letter in ALPHABET if letter not in counts]


def most_frequent_char(text):
    """Most frequent character, ignoring case and spaces; ties go to the first seen."""
    buckets = group_by_count(text)
    if not buckets:
        return None
    return buckets[max(buckets)][0]


def tied_chars(text):
    """All characters sharing the winning count, in first-appearance order."""
    buckets = group_by_count(text)
    if not buckets:
        return []
    return buckets[max(buckets)]


def describe(text):
    """Build a one-line human-readable report for a sample string."""
    winner = most_frequent_char(text)
    if winner is None:
        return "%r -> no countable characters" % text
    counts, _order = char_counts(text)
    line = "%r -> %r (%d times)" % (text, winner, counts[winner])
    others = [ch for ch in tied_chars(text) if ch != winner]
    if others:
        line += ", tied with " + ", ".join(repr(ch) for ch in others)
    symbols = non_letter_chars(text)
    if symbols:
        line += ", non-letters counted: " + "".join(symbols)
    return line


def main():
    for sample in ["hello world", "aabbc", "Mississippi River", "a-b-c!", "   "]:
        print(describe(sample))
    print("letters absent from 'hello world':",
          "".join(missing_letters("hello world")))


