_CACHE = {}

STYLES = {"grid": "  ", "csv": ","}


def _parse_count(text):
    """Turn a command line argument into a non-negative table size."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("table size must not be empty")
    for ch in cleaned:
        if ch not in "0123456789":
            raise ValueError("table size must be a decimal number: %r" % text)
    return int(cleaned)


def format_table(table, style="grid"):
    """Render the table as a list of printable lines."""
    if style not in STYLES:
        raise ValueError("unknown style: %r" % style)
    separator = STYLES[style]
    if not table:
        return []
    width = max(len(str(value)) for row in table for value in row)
    lines = []
    for row in table:
        if style == "csv":
            lines.append(separator.join(str(value) for value in row))
        else:
            lines.append(separator.join(str(value).rjust(width) for value in row))
    return lines


def build_table(n):
    """Return the cached n x n product grid."""
    if not isinstance(n, int):
        raise TypeError("n must be an int, got %s" % type(n).__name__)
    if n < 0:
        raise ValueError("n must be non-negative")
    if n not in _CACHE:
        _CACHE[n] = [[row * col for col in range(1, n + 1)]
                     for row in range(1, n + 1)]
    return [row[:] for row in _CACHE[n]]


def multiplication_table(n):
    """Print the n x n multiplication table and return it as a list of lists."""
    table = build_table(n)
    for line in format_table(table):
        print(line)
    return table


def distinct_products(table):
    """Every value that actually appears somewhere in the table."""
    return {value for row in table for value in row}


def report(table):
    """Describe which products the table covers and which it skips."""
    n = len(table)
    products = distinct_products(table)
    missing = [value for value in range(1, n * n + 1) if value not in products]
    lines = ["distinct products: %d" % len(products)]
    lines.append("diagonal: %s" % [table[i][i] for i in range(n)])
    if missing:
        lines.append("never produced: %s" % missing)
    return lines


def main(argv):
    flags = ("--csv", "--no-report")
    positional = [arg for arg in argv[1:] if arg not in flags]
    n = _parse_count(positional[0]) if positional else 5
    if "--csv" in argv[1:]:
        table = build_table(n)
        for line in format_table(table, "csv"):
            print(line)
    else:
        table = multiplication_table(n)
    if "--no-report" not in argv[1:]:
        for line in report(table):
            print(line)
    return 0


if __name__ == "__main__":
    import sys
    raise SystemExit(main(sys.argv))

