VALID_CHOICES = ('rock', 'paper', 'scissors')
BEATS = {'rock': 'scissors', 'paper': 'rock', 'scissors': 'paper'}
ALIASES = {'r': 'rock', 'p': 'paper', 's': 'scissors'}
RESULTS = ('Player 1 wins!', 'Player 2 wins!', "It's a tie!")

def normalize_choice(choice):
    """Turn user input into a canonical choice name, or raise ValueError."""
    if not isinstance(choice, str):
        raise ValueError('choice must be a string, got %r' % (choice,))
    cleaned = choice.strip().lower()
    if cleaned not in VALID_CHOICES:
        cleaned = ALIASES.get(cleaned, cleaned)
    if cleaned not in VALID_CHOICES:
        raise ValueError('unknown choice: %r' % (choice,))
    return cleaned

def parse_round_line(line):
    """Read one 'rock,scissors' line into a pair of canonical choices."""
    if ',' not in line:
        raise ValueError('expected two comma separated choices: %r' % line)
    left, right = line.split(',', 1)
    return normalize_choice(left), normalize_choice(right)

def parse_rounds(text):
    """Parse a multi-line log of rounds, ignoring blanks and comments."""
    rounds = []
    for line in text.splitlines():
        stripped = line.strip()
        if stripped and not stripped.startswith('#'):
            rounds.append(parse_round_line(stripped))
    return rounds

def unused_choices(rounds):
    played = {choice for pair in rounds for choice in pair}
    return [choice for choice in VALID_CHOICES if choice not in played]

def describe_series(tally):
    lines = []
    for label in RESULTS:
        if label not in tally:
            raise ValueError('tally is missing the entry %r' % label)
        lines.append('%-16s %d' % (label, tally[label]))
    p1, p2 = tally['Player 1 wins!'], tally['Player 2 wins!']
    if p1 == p2:
        lines.append('Series drawn.')
    else:
        lines.append('Series winner: Player %d' % (1 if p1 > p2 else 2))
    return '\n'.join(lines)

def rock_paper_scissors(player1_choice, player2_choice):
    """Play one round and report the outcome as a sentence."""
    first = normalize_choice(player1_choice)
    second = normalize_choice(player2_choice)
    if first == second:
        return "It's a tie!"
    if BEATS[first] == second:
        return 'Player 1 wins!'
    return 'Player 2 wins!'

def play_series(rounds):
    tally = dict.fromkeys(RESULTS, 0)
    for first, second in rounds:
        tally[rock_paper_scissors(first, second)] += 1
    return tally

def main():
    log = ('# player1,player2\nrock,scissors\npaper,rock\n'
           ' SCISSORS ,rock\np,scissors\nrock,r\n')
    rounds = parse_rounds(log)
    for first, second in rounds:
        print('%s vs %s -> %s' % (first, second,
                                  rock_paper_scissors(first, second)))
    print(describe_series(play_series(rounds)))
    missing = unused_choices(rounds)
    if missing:
        print('never played:', ', '.join(missing))

if __name__ == '__main__':
    main()

