    minutes, secs = divmod(rest, 60)
    return "%02d:%02d:%02d" % (hours, minutes, secs)


def normalize_seconds(value):
    """Coerce a duration into a whole, non-negative number of seconds."""
    if not type(value) in (int, float, str):
        raise TypeError("duration must be an int, float or str")
    if isinstance(value, str):
        text = value.strip()
        if not text:
            raise ValueError("duration string is empty")
        if not ":" in text:
            value = parse_duration(text)
        else:
            value = hms_to_seconds(text)
    if isinstance(value, float):
        if value != int(value):
            raise ValueError("fractional seconds are not supported")
        value = int(value)
    if value < 0:
        raise ValueError("duration must not be negative")
    return value


def parse_duration(text):
    """Turn '1h 30m 10s' or a bare '3661' into a count of seconds."""
    total = 0
    number = ""
    for char in text.replace(" ", "").lower():
        if char in DIGITS:
            number += char
            continue
        if not char in UNIT_SECONDS:
            raise ValueError("unknown duration unit: %r" % char)
        if not number:
            raise ValueError("unit %r has no amount in front of it" % char)
        total += int(number) * UNIT_SECONDS[char]
        number = ""
    if number:
        total += int(number)
    return total


def hms_to_seconds(clock):
    """Inverse of seconds_to_hms for 'MM:SS' or 'HH:MM:SS' strings."""
    parts = clock.split(":")
    if not len(parts) in (2, 3):
        raise ValueError("expected 'MM:SS' or 'HH:MM:SS', got %r" % clock)
    total = 0
    for index, part in enumerate(parts):
        for char in part:
            if not char in DIGITS:
                raise ValueError("non-digit %r in %r" % (char, clock))
        chunk = int(part)
        if index and chunk > 59:
            raise ValueError("field %r is out of range" % part)
        total = total * 60 + chunk
    return total


def report(durations):
    """Build aligned 'input -> HH:MM:SS' lines, skipping duplicates."""
    lines = []
    seen = set()
    for item in durations:
        formatted = seconds_to_hms(item)
        if not formatted in seen:
            seen.add(formatted)
            lines.append("%12s -> %s" % (item, formatted))
    return lines


def main():
    for line in report([3661, 90, "1h 30m 10s", 90.0, "45s", "23:59:59", 0]):
        print(line)


if __name__ == "__main__":
    main()

