import sys

ATOMIC_TYPES = (int, float, complex, bool, str, bytes, type(None))


def flatten_list(list_of_lists):
    """Flatten one level of nesting, returning a single list."""
    flat = []
    for index, group in enumerate(list_of_lists):
        if type(group) not in (list, tuple):
            raise TypeError("element %d is not a list or tuple: %r" % (index, group))
        flat.extend(group)
    return flat


def deep_flatten(nested):
    """Flatten arbitrarily deep nesting of lists and tuples."""
    flat = []
    for item in nested:
        if isinstance(item, ATOMIC_TYPES):
            flat.append(item)
        elif type(item) not in (list, tuple):
            raise TypeError("cannot flatten value of type %s" % type(item).__name__)
        else:
            flat.extend(deep_flatten(item))
    return flat


def unique_flatten(list_of_lists):
    """Flatten one level and drop later duplicates, preserving order."""
    unique = []
    for value in flatten_list(list_of_lists):
        if value not in unique:
            unique.append(value)
    return unique


def type_counts(values):
    """Map type names to how often they occur in the flattened values."""
    counts = {}
    for value in values:
        name = type(value).__name__
        if name not in counts:
            counts[name] = 0
        counts[name] += 1
    return counts


def select_samples(names, samples):
    """Return (label, data) pairs for the requested sample names."""
    chosen = []
    for name in names:
        if name not in samples:
            raise KeyError("unknown sample %r; choose from %s" % (name, ", ".join(samples)))
        chosen.append((name, samples[name]))
    return chosen


def format_report(label, list_of_lists):
    """Build a short multi-line report about flattening one input."""
    flat = flatten_list(list_of_lists)
    lines = ["%s: %r -> %r" % (label, list_of_lists, flat)]
    if not flat:
        lines.append("  (empty result)")
        return "\n".join(lines)
    lines.append("  unique: %r" % (unique_flatten(list_of_lists),))
    for name, count in sorted(type_counts(flat).items()):
        lines.append("  %s x%d" % (name, count))
    return "\n".join(lines)


def main(argv):
    samples = {
        "pairs": [[1, 2], [3, 4, 5]],
        "empty": [[]],
        "duplicates": [["a", "b"], ["b"], ("c", "a")],
        "mixed": [[1, 1.5], [True, None], ["text"]],
    }
    requested = argv[1:] or list(samples)
    for label, data in select_samples(requested, samples):
        print(format_report(label, data))
    deeply_nested = [[1, [2, [3, 4]]], (5, [[6]]), []]
    print("deep_flatten: %r -> %r" % (deeply_nested, deep_flatten(deeply_nested)))


if __name__ == "__main__":
    main(sys.argv)

