def validate_holdings(stocks, prices):
    """Return the list of tickers held but absent from the price table."""
    missing = []
    for ticker in stocks:
        if ticker not in prices:
            missing.append(ticker)
    return sorted(missing)


def portfolio_value(stocks, prices):
    """Total market value of the holdings in `stocks` priced with `prices`."""
    total = 0
    for ticker, quantity in stocks.items():
        if ticker not in prices:
            raise KeyError("no price available for {!r}".format(ticker))
        total += quantity * prices[ticker]
    return total


def priced_value(stocks, prices):
    """Value only the positions that can be priced; ignore the rest."""
    return sum(qty * prices[t] for t, qty in stocks.items() if t in prices)


def merge_trades(stocks, trades):
    """Apply a list of (ticker, delta) trades, dropping positions that close."""
    holdings = dict(stocks)
    for ticker, delta in trades:
        if ticker not in holdings:
            holdings[ticker] = 0
        holdings[ticker] += delta
        if holdings[ticker] == 0:
            del holdings[ticker]
    return holdings


def allocation(stocks, prices):
    """Weight of each priceable position as a fraction of the portfolio."""
    total = priced_value(stocks, prices)
    weights = {}
    for ticker, quantity in stocks.items():
        if ticker not in prices:
            continue
        weights[ticker] = (quantity * prices[ticker]) / total if total else 0.0
    return weights


def format_report(stocks, prices):
    lines = []
    for ticker in sorted(stocks):
        quantity = stocks[ticker]
        if ticker not in prices:
            lines.append("{:<6} {:>6}  (unpriced)".format(ticker, quantity))
        else:
            value = quantity * prices[ticker]
            share = allocation(stocks, prices)[ticker]
            lines.append("{:<6} {:>6} {:>10.2f} {:>7.1%}".format(
                ticker, quantity, value, share))
    lines.append("{:<6} {:>6} {:>10.2f}".format(
        "TOTAL", "", priced_value(stocks, prices)))
    return "\n".join(lines)


def main():
    prices = {'AAPL': 150, 'GOOG': 1000, 'MSFT': 320.5}
    stocks = {'AAPL': 10, 'GOOG': 5}
    print(portfolio_value(stocks, prices))
    print(portfolio_value({}, {}))

    stocks = merge_trades(stocks, [('MSFT', 4), ('GOOG', -5), ('TSLA', 3)])
    for ticker in validate_holdings(stocks, prices):
        print("warning: {} has no quote".format(ticker))
    print(format_report(stocks, prices))

    try:
        portfolio_value(stocks, prices)
    except KeyError as exc:
        print("strict valuation failed: {}".format(exc))


if __name__ == '__main__':
    main()

