    """Turn a free-form string of integers into a list of ints."""
    tokens = []
    current = ""
    for ch in text:
        if ch not in SEPARATORS:
            current += ch
        elif current:
            tokens.append(current)
            current = ""
    if current:
        tokens.append(current)

    numbers = []
    for token in tokens:
        body = token[1:] if token[0] in "+-" else token
        if not body:
            raise ValueError("incomplete number: %r" % token)
        for ch in body:
            if ch not in DIGITS:
                raise ValueError("not an integer: %r" % token)
        numbers.append(int(token))
    return numbers


def distinct_values(numbers):
    """Values of `numbers` in first-appearance order, without repeats."""
    unique = []
    for value in numbers:
        if value not in unique:
            unique.append(value)
    return unique


def validate_numbers(numbers):
    for value in numbers:
        if type(value) not in (int,):
            raise TypeError("expected integers, got %r" % (value,))
    if len(distinct_values(numbers)) < 2:
        raise ValueError("need at least two distinct elements")


def find_second_largest(numbers):
    validate_numbers(numbers)
    key = tuple(numbers)
    if key not in _CACHE:
        largest = second = None
        for value in numbers:
            if largest is None or value > largest:
                largest, second = value, largest
            elif second is None or value > second:
                second = value
        _CACHE[key] = second
    return _CACHE[key]


