    buckets = {}
    for label, answer in results:
        if answer not in buckets:
            buckets[answer] = []
        buckets[answer].append(label)
    lines = []
    for answer in sorted(buckets):
        lines.append("%d: %s" % (answer, ", ".join(buckets[answer])))
    return lines


