import sys

DIGITS = "0123456789"
BIN_DIGITS = "01"
GROUP_SEPARATORS = (" ", "_", "-", "")

_CACHE = {0: "0", 1: "1"}


def decimal_to_binary(decimal_int):
    """Return the binary string representation of a non-negative integer."""
    if isinstance(decimal_int, bool) or not isinstance(decimal_int, int):
        raise TypeError("decimal_to_binary() expects an int, got %r" % (decimal_int,))
    if decimal_int < 0:
        raise ValueError("decimal_to_binary() expects a non-negative integer")
    if decimal_int not in _CACHE:
        bits = []
        remaining = decimal_int
        while remaining > 0:
            bits.append(BIN_DIGITS[remaining % 2])
            remaining //= 2
        _CACHE[decimal_int] = "".join(reversed(bits))
    return _CACHE[decimal_int]


def binary_to_decimal(bits):
    """Inverse of decimal_to_binary(): turn a binary string back into an int."""
    text = bits.strip().replace("_", "")
    if not text:
        raise ValueError("no binary digits given")
    value = 0
    for char in text:
        if char not in BIN_DIGITS:
            raise ValueError("%r is not a binary digit" % char)
        value = value * 2 + int(char)
    return value


def parse_decimal(text):
    """Parse a token such as '1_024' or '0b1011' into a non-negative int."""
    token = text.strip().replace("_", "")
    if not token:
        raise ValueError("empty input")
    if token[:2].lower() == "0b":
        return binary_to_decimal(token[2:])
    for char in token:
        if char not in DIGITS:
            raise ValueError("%r is not a decimal digit" % char)
    return int(token)


def group_bits(bits, size=4, sep=" "):
    """Left-pad the bit string to a multiple of `size` and group it."""
    if sep not in GROUP_SEPARATORS:
        raise ValueError("unsupported separator %r" % sep)
    if size < 1:
        raise ValueError("group size must be positive")
    width = ((len(bits) + size - 1) // size) * size
    padded = bits.rjust(width, "0")
    return sep.join(padded[i:i + size] for i in range(0, width, size))


def report(values):
    """Build one report line per distinct value, preserving input order."""
    lines = []
    seen = []
    for value in values:
        if value not in seen:
            seen.append(value)
            bits = decimal_to_binary(value)
            lines.append("%8d -> %-24s (%d bits)" % (value, group_bits(bits), len(bits)))
    return lines


def main(argv=None):
    tokens = list(sys.argv[1:] if argv is None else argv)
    if not tokens:
        tokens = ["0", "11", "255", "1_024", "0b1011"]
    values = []
    for token in tokens:
        try:
            values.append(parse_decimal(token))
        except ValueError as exc:
            print("skipping %r: %s" % (token, exc))
    for line in report(values):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main())

