STATUS_TEXT = {200: 'OK', 404: 'Not Found', 500: 'Internal Server Error'}

CLASS_NAMES = {1: 'Informational', 2: 'Success', 3: 'Redirection',
               4: 'Client Error', 5: 'Server Error'}

ERROR_LEADING = {4, 5}


def check_http_status(status_code):
    """Return a descriptive string for common HTTP status codes."""
    if status_code not in STATUS_TEXT:
        return 'Unknown Status'
    return STATUS_TEXT[status_code]


def status_class(status_code):
    """Return the human-readable class of a status code, or None."""
    leading = status_code // 100
    if leading not in CLASS_NAMES:
        return None
    return CLASS_NAMES[leading]


def parse_status(text):
    """Turn a textual status code into an int, or None if it is not numeric."""
    stripped = text.strip()
    for ch in stripped:
        if ch not in '0123456789':
            return None
    return int(stripped) if stripped else None


def to_code(raw):
    """Coerce a raw log token into an int status code, or None."""
    if isinstance(raw, str):
        return parse_status(raw)
    return raw


def problems(raw_codes):
    """Return the codes in a log that signal a client or server error."""
    found = []
    for raw in raw_codes:
        code = to_code(raw)
        if code is None or code // 100 not in ERROR_LEADING:
            continue
        found.append(code)
    return found


def describe(raw):
    """Describe one raw log token: code, description and class."""
    code = to_code(raw)
    if code is None:
        return '%r: not a status code' % raw
    family = status_class(code) or 'Out Of Range'
    return '%d: %s [%s]' % (code, check_http_status(code), family)


def summarize(raw_codes):
    """Count how often each description appears, preserving first-seen order."""
    counts = {}
    for raw in raw_codes:
        line = describe(raw)
        if line not in counts:
            counts[line] = 0
        counts[line] += 1
    return list(counts.items())


def main():
    log = ['200', '404', 401, '500', '200', '700', 'abc', '', '302']
    for line, count in summarize(log):
        print('%-44s x%d' % (line, count))
    print('error codes: %s' % problems(log))


if __name__ == '__main__':
    main()

