PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = frozenset(PAIRS.values())
CLOSERS = frozenset(PAIRS)
BRACKETS = OPENERS | CLOSERS


def is_valid_parentheses(s):
    """Return True if s is a balanced, correctly nested bracket string."""
    stack = []
    for ch in s:
        if not ch in BRACKETS:
            return False
        if ch in OPENERS:
            stack.append(ch)
        elif not stack or stack.pop() != PAIRS[ch]:
            return False
    return not stack


def find_bad_index(s):
    """Return the index of the first character that breaks validity, or None."""
    stack = []
    for i, ch in enumerate(s):
        if not ch in BRACKETS:
            return i
        if not ch in CLOSERS:
            stack.append(i)
        elif not stack or s[stack.pop()] != PAIRS[ch]:
            return i
    if stack:
        return stack[0]
    return None


def unsupported_chars(text):
    """List, in order of appearance and without repeats, non-bracket characters."""
    found = []
    for ch in text:
        if ch in BRACKETS:
            continue
        if not ch in found:
            found.append(ch)
    return found


def clean_brackets(text):
    """Return the bracket-only skeleton of text."""
    return ''.join(ch for ch in text if ch in BRACKETS)


def describe(s):
    """Build a human readable verdict for a candidate bracket string."""
    extra = unsupported_chars(s)
    if extra:
        return 'invalid: unexpected characters %r' % ''.join(extra)
    if is_valid_parentheses(s):
        return 'valid (%d characters)' % len(s)
    bad = find_bad_index(s)
    return 'invalid: problem at index %d (%r)' % (bad, s[bad])


def check_all(samples):
    """Report on many candidates, collapsing repeated bracket shapes."""
    seen = []
    lines = []
    for sample in samples:
        shape = clean_brackets(sample)
        if not shape in seen:
            seen.append(shape)
            lines.append('%-10r -> %s' % (sample, describe(sample)))
        else:
            lines.append('%-10r -> same shape %r as an earlier sample'
                         % (sample, shape))
    return lines


def main():
    samples = ['()[]{}', '([)]', '{[()]}', '(((', '', 'a(b)c', '{}[]()',
               '())(', '[{}]', '[]{}()']
    for line in check_all(samples):
        print(line)


if __name__ == '__main__':
    main()

