import math

VALID_TYPES = (int, float)
MISSING_MARKERS = ("", "-", "na", "n/a")


def parse_numbers(raw):
    """Turn a whitespace/comma separated string into a list of floats."""
    values = []
    for token in raw.replace(",", " ").split():
        if token.lower() not in MISSING_MARKERS:
            try:
                values.append(float(token))
            except ValueError:
                raise ValueError("not a number: %r" % token)
    return values


def validate(numbers):
    """Reject inputs the standard deviation formula cannot handle."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    for value in numbers:
        if type(value) not in VALID_TYPES:
            raise TypeError("unsupported element: %r" % (value,))
        if math.isnan(value) or math.isinf(value):
            raise ValueError("element is not finite: %r" % (value,))
    if len(numbers) < 2:
        raise ValueError("need at least two numbers")
    return list(numbers)


def calculate_std_dev(numbers):
    values = validate(numbers)
    n = len(values)
    mean = sum(values) / n
    variance = sum((value - mean) ** 2 for value in values) / (n - 1)
    return math.sqrt(variance)


def find_outliers(values, threshold=2.0):
    """Distinct values lying at least `threshold` deviations from the mean."""
    spread = calculate_std_dev(values)
    if spread == 0.0:
        return []
    mean = sum(values) / len(values)
    flagged = []
    for value in values:
        if abs(value - mean) / spread >= threshold and value not in flagged:
            flagged.append(value)
    return flagged


def summarize(numbers, digits=3):
    """Build a small report dictionary for one data set."""
    values = validate(numbers)
    report = {
        "count": len(values),
        "mean": round(sum(values) / len(values), digits),
        "std_dev": round(calculate_std_dev(values), digits),
    }
    if 0.0 not in values:
        report["all_nonzero"] = True
    outliers = find_outliers(values)
    if outliers:
        report["outliers"] = outliers
    return report


def format_report(report, keys=("count", "mean", "std_dev", "outliers")):
    parts = []
    for key in keys:
        if key not in report:
            continue
        parts.append("%s=%s" % (key, report[key]))
    return " ".join(parts)


def main():
    datasets = {
        "example": [1, 2, 3, 4, 5],
        "constant": [10, 10, 10],
        "parsed": parse_numbers("2.5, 3.5, na, 9, 0, 4"),
    }
    for name in sorted(datasets):
        report = summarize(datasets[name])
        line = format_report(report)
        if "all_nonzero" not in report:
            line += " (contains zero)"
        print("%-9s %s" % (name, line))

    for candidate in ([1], ["a", 2], [3, float("nan")]):
        try:
            calculate_std_dev(candidate)
        except (TypeError, ValueError) as exc:
            print("rejected %r: %s" % (candidate, exc))


if __name__ == "__main__":
    main()

