import sys
from itertools import groupby

VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
SUBTRACTIVE_PAIRS = {'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900}
REPEATABLE = {'I', 'X', 'C', 'M'}
TOKEN_VALUES = dict(VALUES)
TOKEN_VALUES.update(SUBTRACTIVE_PAIRS)


def normalize(text):
    cleaned = text.strip().upper()
    if not cleaned:
        raise ValueError('roman numeral must not be empty')
    for char in cleaned:
        if char not in VALUES:
            raise ValueError('invalid roman digit: %r' % char)
    return cleaned


def validate(roman_numeral):
    """Check repetition and subtraction rules, returning the clean numeral."""
    numeral = normalize(roman_numeral)
    for char, group in groupby(numeral):
        count = len(list(group))
        if count > 1 and char not in REPEATABLE:
            raise ValueError('%s cannot be repeated in %s' % (char, numeral))
        if count > 3:
            raise ValueError('%s repeated too often in %s' % (char, numeral))
    for index, char in enumerate(numeral[:-1]):
        nxt = numeral[index + 1]
        if VALUES[char] < VALUES[nxt] and char + nxt not in SUBTRACTIVE_PAIRS:
            raise ValueError('illegal subtraction %s%s' % (char, nxt))
    return numeral


def tokenize(numeral):
    """Split a numeral into single letters and subtractive pairs."""
    tokens = []
    index = 0
    while index < len(numeral):
        token = numeral[index:index + 2]
        if token not in TOKEN_VALUES:
            token = numeral[index]
        tokens.append(token)
        index += len(token)
    return tokens


def roman_to_int(roman_numeral):
    """Convert a Roman numeral string to its integer value."""
    numeral = validate(roman_numeral)
    total = 0
    previous = 0
    for token in tokenize(numeral):
        value = TOKEN_VALUES[token]
        if previous and value >= previous and token not in REPEATABLE:
            raise ValueError('%s is out of order in %s' % (token, numeral))
        total += value
        previous = value
    return total


def report(numerals):
    """Build a text report of conversions, skipping repeated inputs."""
    lines = []
    seen = set()
    for item in numerals:
        key = item.strip().upper()
        if key not in seen:
            seen.add(key)
            try:
                lines.append('%-10s -> %d' % (item, roman_to_int(item)))
            except ValueError as exc:
                lines.append('%-10s -> error: %s' % (item, exc))
    return '\n'.join(lines)


if __name__ == '__main__':
    print(report(sys.argv[1:]))

