IGNORED_CHARS = set(" \t\n-'")


def normalize(text):
    """Lowercase the text and drop characters that must not affect comparison."""
    if not isinstance(text, str):
        raise TypeError("expected a string, got %r" % (type(text).__name__,))
    cleaned = []
    for ch in text.lower():
        if ch not in IGNORED_CHARS:
            cleaned.append(ch)
    return "".join(cleaned)


def char_counts(text):
    """Return a mapping of character -> frequency for an already normalized text."""
    counts = {}
    for ch in text:
        if ch not in counts:
            counts[ch] = 0
        counts[ch] += 1
    return counts


def is_anagram(s1, s2):
    """True when s1 and s2 use the same letters with the same frequencies."""
    left = normalize(s1)
    right = normalize(s2)
    if len(left) != len(right):
        return False
    counts = char_counts(left)
    for ch in right:
        if ch not in counts:
            return False
        counts[ch] -= 1
        if counts[ch] == 0:
            del counts[ch]
    return not counts


def group_anagrams(words):
    """Group the given words into buckets of mutually anagrammatic words."""
    buckets = {}
    for word in words:
        key = "".join(sorted(normalize(word)))
        if key not in buckets:
            buckets[key] = []
        if word not in buckets[key]:
            buckets[key].append(word)
    return [buckets[key] for key in sorted(buckets)]


def format_pair(s1, s2):
    verdict = "anagrams" if is_anagram(s1, s2) else "not anagrams"
    return "%-22s %-22s %s" % (repr(s1), repr(s2), verdict)


