"""Room scheduling helpers built around conflict detection."""


def parse_interval(text):
    """Turn "10-15" into the tuple (10, 15)."""
    if "-" not in text:
        raise ValueError("interval %r must look like 'start-end'" % text)
    start_text, end_text = text.split("-", 1)
    start, end = int(start_text.strip()), int(end_text.strip())
    if end <= start:
        raise ValueError("interval %r does not end after it starts" % text)
    return (start, end)


def parse_schedule(text):
    """Parse "1-5, 10-15" into a sorted list of (start, end) tuples."""
    schedule = []
    for chunk in text.split(","):
        chunk = chunk.strip()
        if not chunk:
            continue
        event = parse_interval(chunk)
        if event not in schedule:
            schedule.append(event)
    return sorted(schedule)


def parse_rooms(lines):
    """Parse lines like "A: 1-5, 10-15" into {room: schedule}."""
    rooms = {}
    for line in lines:
        if ":" not in line:
            raise ValueError("line %r must look like 'room: intervals'" % line)
        name, intervals = line.split(":", 1)
        name = name.strip()
        if name not in rooms:
            rooms[name] = []
        for event in parse_schedule(intervals):
            if event not in rooms[name]:
                rooms[name].append(event)
        rooms[name].sort()
    return rooms


def has_conflict(schedule, new_event_start, new_event_end):
    for start, end in schedule:
        if new_event_start < end and start < new_event_end:
            return True
    return False


def free_slots(schedule, day_start, day_end):
    busy = set()
    for start, end in schedule:
        for hour in range(max(start, day_start), min(end, day_end)):
            busy.add(hour)
    slots, run_start = [], None
    for hour in range(day_start, day_end):
        if hour not in busy:
            if run_start is None:
                run_start = hour
        elif run_start is not None:
            slots.append((run_start, hour))
            run_start = None
    if run_start is not None:
        slots.append((run_start, day_end))
    return slots


def book(rooms, room, start, end):
    schedule = rooms[room]
    if has_conflict(schedule, start, end):
        return False
    schedule.append((start, end))
    schedule.sort()
    return True


def first_available_room(rooms, start, end):
    for name in sorted(rooms):
        if not has_conflict(rooms[name], start, end):
            return name
    return None


def earliest_slot(schedule, duration, day_start, day_end):
    for start, end in free_slots(schedule, day_start, day_end):
        if end - start >= duration:
            return (start, start + duration)
    return None


def format_report(rooms, day_start, day_end):
    lines = []
    for name in sorted(rooms):
        booked = ", ".join("%d-%d" % ev for ev in rooms[name]) or "nothing"
        free = ", ".join("%d-%d" % s for s in free_slots(rooms[name], day_start, day_end))
        lines.append("%s: booked %s | free %s" % (name, booked, free or "nothing"))
    return "\n".join(lines)


def main():
    rooms = parse_rooms(["A: 1-5, 10-15", "B: 9-12", "A: 10-15"])
    for room, start, end in [("A", 3, 7), ("A", 6, 8), ("B", 1, 5), ("C", 2, 3)]:
        label = "%s %d-%d" % (room, start, end)
        if room not in rooms:
            print("%s: unknown room" % label)
            continue
        if book(rooms, room, start, end):
            print("%s: booked" % label)
            continue
        alternative = first_available_room(rooms, start, end)
        slot = earliest_slot(rooms[room], end - start, 0, 24)
        print("%s: conflict (other room: %s, later slot: %s)"
              % (label, alternative or "none",
                 "%d-%d" % slot if slot else "none"))
    print(format_report(rooms, 0, 24))


if __name__ == "__main__":
    main()

