WHITESPACE = " \t\n\r\f\v"
TERMINATORS = ".!?"
STOPWORDS = {"a", "an", "the", "is", "are", "was", "were", "in", "on", "of", "to", "and", "or"}

_CACHE = {}


def split_words(sentence):
    """Split on runs of whitespace, dropping empty fragments."""
    words = []
    buffer = []
    for ch in sentence:
        if ch not in WHITESPACE:
            buffer.append(ch)
        elif buffer:
            words.append("".join(buffer))
            buffer = []
    if buffer:
        words.append("".join(buffer))
    return words


def strip_terminator(sentence):
    """Separate a trailing sentence terminator so it stays at the end."""
    body = sentence.rstrip(WHITESPACE)
    if not body or body[-1] not in TERMINATORS:
        return sentence, ""
    return body[:-1], body[-1]


def reverse_words(sentence):
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a str")
    if sentence not in _CACHE:
        body, terminator = strip_terminator(sentence)
        words = split_words(body)
        words.reverse()
        _CACHE[sentence] = " ".join(words) + terminator
    return _CACHE[sentence]


def unique_words(words):
    """Words in first-appearance order, compared case-insensitively."""
    seen = set()
    result = []
    for word in words:
        lowered = word.lower()
        if lowered not in seen:
            seen.add(lowered)
            result.append(word)
    return result


def content_words(words):
    return [w for w in words if w.lower().strip(TERMINATORS) not in STOPWORDS]


def format_report(sentence):
    words = split_words(sentence)
    lines = ["original: " + sentence, "reversed: " + reverse_words(sentence)]
    distinct = unique_words(words)
    if len(distinct) != len(words):
        lines.append("repeats:  " + str(len(words) - len(distinct)))
    keywords = content_words(words)
    if keywords:
        lines.append("keywords: " + ", ".join(keywords))
    return "\n".join(lines)


def main():
    samples = [
        "hello world",
        "Python is fun",
        "  the  quick   brown fox  ",
        "Never say never again!",
    ]
    for sample in samples:
        print(format_report(sample))
        print("-" * 32)


if __name__ == "__main__":
    main()

