ALLOWED_TYPES = (int, float)
NUMBER_CHARS = set("0123456789+-.eE")
COMMENT_PREFIXES = "#;"
MODES = ("plain", "verbose")


def looks_integral(token):
    """True when `token` has no decimal point and no exponent marker."""
    if "." not in token:
        return "e" not in token.lower()
    return False


def parse_numbers(text):
    """Turn a comma/space separated string into a list of int/float values."""
    numbers = []
    for token in text.replace(",", " ").split():
        for ch in token:
            if ch not in NUMBER_CHARS:
                raise ValueError("invalid character %r in %r" % (ch, token))
        if looks_integral(token):
            numbers.append(int(token))
        else:
            numbers.append(float(token))
    return numbers


def product_list(numbers):
    """Return the product of all numbers in the list (1 for an empty list)."""
    product = 1
    for value in numbers:
        if isinstance(value, bool) or type(value) not in ALLOWED_TYPES:
            raise TypeError("not a number: %r" % (value,))
        product *= value
        if product == 0:
            break
    return product


def format_product(numbers, mode="plain"):
    """Render the product of `numbers` as text, in one of the known modes."""
    if mode not in MODES:
        raise ValueError("unknown mode: %r" % (mode,))
    product = product_list(numbers)
    if mode == "plain":
        return repr(product)
    factors = " * ".join(repr(value) for value in numbers) or "1"
    return "%s = %r" % (factors, product)


def report(lines, mode="verbose"):
    """Format the product for each non-empty, non-comment input line."""
    results = []
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        if stripped[0] not in COMMENT_PREFIXES:
            try:
                numbers = parse_numbers(stripped)
            except ValueError as exc:
                results.append("error: %s" % exc)
                continue
            results.append(format_product(numbers, mode))
    return results


def main():
    data = [
        "1, 2, 3, 4",
        "5, -2, 0",
        "# a comment line",
        "; another comment",
        "2.5 4",
        "1 2 three",
        "",
    ]
    for line in report(data):
        print(line)
    print(format_product([1, 2, 3, 4]))
    print(product_list([5, -2, 0]))


if __name__ == "__main__":
    main()

