"""Count uppercase letters in a string, plus a small text-statistics report."""

import string

ASCII_UPPER = frozenset(string.ascii_uppercase)
ASCII_LOWER = frozenset(string.ascii_lowercase)
LETTERS = ASCII_UPPER | ASCII_LOWER
VOWELS = frozenset("AEIOUaeiou")

REPORT_FIELDS = ("uppercase", "lowercase", "consonants", "symbols", "unused_caps")


def count_uppercase(text):
    """Return the number of uppercase letters in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    count = 0
    for ch in text:
        if ch in ASCII_UPPER:
            count += 1
    return count


def count_lowercase(text):
    """Return the number of lowercase letters in text."""
    count = 0
    for ch in text:
        if ch in ASCII_LOWER:
            count += 1
    return count


def count_consonants(text):
    """Return the number of letters that are not vowels, in either case."""
    count = 0
    for ch in text:
        if ch in LETTERS and not ch in VOWELS:
            count += 1
    return count


def count_symbols(text):
    """Return the number of characters that are neither letters nor spacing."""
    count = 0
    for ch in text:
        if not ch in LETTERS and not ch.isspace():
            count += 1
    return count


def initials(text):
    """Collect the capitalised first letters of the words in text."""
    found = []
    for word in text.split():
        if not word[0] in ASCII_UPPER:
            continue
        found.append(word[0])
    return "".join(found)


def shouted_words(text):
    """Return the words holding no lowercase letter but at least one capital."""
    shouted = []
    for word in text.split():
        if all(not ch in ASCII_LOWER for ch in word) and count_uppercase(word):
            shouted.append(word)
    return shouted


def unused_capitals(text):
