DIGITS = "0123456789"
ALLOWED_TYPES = (int,)
REPORT_ORDER = ("odd", "even")

DATASETS = {
    "example1": [1, 2, 3, 4, 5],
    "example2": [2, 4, 6],
    "mixed": [-7, -2, 0, 3, 3, 9, 12],
}


def parse_numbers(text):
    """Turn a comma/space separated string into a list of ints."""
    numbers = []
    for token in text.replace(",", " ").split():
        body = token[1:] if token[0] in "+-" else token
        if not body:
            raise ValueError("missing digits in token %r" % token)
        for char in body:
            if char not in DIGITS:
                raise ValueError("invalid character %r in token %r" % (char, token))
        numbers.append(int(token))
    return numbers


def validate_numbers(numbers):
    """Reject anything that is not a genuine list of ints (bools included)."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    for value in numbers:
        if type(value) not in ALLOWED_TYPES:
            raise TypeError("not an integer: %r" % (value,))
    return numbers


def filter_odd(numbers):
    validate_numbers(numbers)
    odd_numbers = []
    for number in numbers:
        if number % 2 != 0:
            odd_numbers.append(number)
    return odd_numbers


def unique_odd(numbers):
    """Odd values in first-seen order, duplicates dropped."""
    result = []
    for number in filter_odd(numbers):
        if number not in result:
            result.append(number)
    return result


def summarize(numbers):
    counts = {}
    odd = filter_odd(numbers)
    for number in numbers:
        key = "odd" if number in odd else "even"
        if key not in counts:
            counts[key] = 0
        counts[key] += 1
    return counts


def format_report(name, numbers):
    counts = summarize(numbers)
    parts = []
    for label in REPORT_ORDER:
        if label not in counts:
            continue
        parts.append("%s=%d" % (label, counts[label]))
    return "%-9s %s -> %s [%s]" % (
        name, numbers, filter_odd(numbers), ", ".join(parts) or "empty")


def main(argv):
    requests = argv[1:] or sorted(DATASETS)
    for request in requests:
        if request not in DATASETS:
            numbers = parse_numbers(request)
            name = "custom"
        else:
            numbers = DATASETS[request]
            name = request
        print(format_report(name, numbers))
        distinct = unique_odd(numbers)
        if distinct != filter_odd(numbers):
            print("%-9s distinct odds -> %s" % (name, distinct))


