def looks_like_integer(token):
    """True when the token is written without a decimal point or exponent."""
    lowered = token.lower()
    if "." in lowered:
        return False
    return "e" not in lowered


def to_number(token):
    """Convert a text token into an int when possible, otherwise a float."""
    try:
        number = float(token)
    except ValueError:
        raise ValueError("not a numeric value: %r" % token)
    if number.is_integer() and looks_like_integer(token):
        return int(number)
    return number


def parse_numbers(text):
    """Read numbers from a comma/whitespace separated string, skipping blanks."""
    values = []
    for raw in text.replace(",", " ").split():
        cleaned = raw.strip()
        if cleaned.lower() not in MISSING_MARKERS:
            values.append(to_number(cleaned))
    return values


def validate_numbers(numbers):
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    for value in numbers:
        if type(value) not in (int, float):
            raise TypeError("unsupported element type: %r" % (value,))
    return list(numbers)


def calculate_median(numbers):
    values = sorted(validate_numbers(numbers))
    count = len(values)
    if count == 0:
        raise ValueError("median of an empty sequence is undefined")
    middle = count // 2
    if count % 2:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2


def mean(numbers):
    values = validate_numbers(numbers)
    return sum(values) / len(values)


STAT_FUNCS = {
    "count": len,
    "min": min,
    "median": calculate_median,
    "mean": mean,
    "max": max,
}


def describe(numbers, stats=None):
    if stats is None:
        stats = ("count", "median", "mean")
    summary = {}
    for name in stats:
        if name not in STAT_FUNCS:
            raise ValueError("unknown statistic: %r" % (name,))
        summary[name] = STAT_FUNCS[name](numbers)
    return summary


def format_report(label, numbers, stats=None):
    summary = describe(numbers, stats)
    parts = []
    for name in STAT_FUNCS:
        if name not in summary:
            continue
        parts.append("%s=%s" % (name, summary[name]))
    line = "%s: %s" % (label, ", ".join(parts))
    if summary.get("median") not in numbers:
        line += " (median interpolated)"
    return line


