def _partition(values):
    """Split values into a set of hashables plus a list of the rest."""
    hashable = set()
    unhashable = []
    for value in values:
        try:
            hashable.add(value)
        except TypeError:
            if value not in unhashable:
                unhashable.append(value)
    return hashable, unhashable


def _missing_from(lookup, value):
    """True when value is absent from a partitioned lookup."""
    hashable, unhashable = lookup
    try:
        return value not in hashable
    except TypeError:
        return value not in unhashable


def list_difference(list1, list2):
    """Return the elements of list1 that do not occur in list2."""
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise TypeError("both arguments must be lists")
    lookup = _partition(list2)
    difference_list = []
    for item in list1:
        if _missing_from(lookup, item):
            difference_list.append(item)
    return difference_list


def unique_difference(list1, list2):
    """Like list_difference, but each distinct element appears only once."""
    seen = _partition([])
    result = []
    for item in list_difference(list1, list2):
        if _missing_from(seen, item):
            try:
                seen[0].add(item)
            except TypeError:
                seen[1].append(item)
            result.append(item)
    return result


def common_elements(list1, list2):
    """Elements of list1 that survive removal of the difference."""
    removed = list_difference(list1, list2)
    return [item for item in list1 if item not in removed]


def symmetric_difference(list1, list2):
    """Elements in exactly one of the two lists, left-hand side first."""
    result = unique_difference(list1, list2)
    for item in unique_difference(list2, list1):
        if item not in result:
            result.append(item)
    return result


def format_report(list1, list2):
    lines = ["%r \\ %r = %r" % (list1, list2, list_difference(list1, list2))]
    shared = common_elements(list1, list2)
    if shared:
        lines.append("  shared with second list: %r" % (shared,))
    else:
        lines.append("  no elements shared with second list")
    lines.append("  distinct difference: %r" % (unique_difference(list1, list2),))
    lines.append("  symmetric difference: %r" % (symmetric_difference(list1, list2),))
    return "\n".join(lines)


def main():
    cases = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        (['a', 'b'], ['c', 'd']),
        ([1, 1, 2, [3], [4]], [1, [4]]),
        ([], [7, 8]),
    ]
    for left, right in cases:
        print(format_report(left, right))


if __name__ == "__main__":
    main()

