}

WEEKDAY_NAMES = ["Thursday", "Friday", "Saturday", "Sunday",
                 "Monday", "Tuesday", "Wednesday"]

OPTIONS = {'--days': 'days', '--weekday': 'weekday'}


def _is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month not in MONTH_DAYS:
        raise ValueError("month out of range: %r" % (month,))
    if month == 2 and _is_leap(year):
        return 29
    return MONTH_DAYS[month]


def parse_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError("expected 'YYYY-MM-DD', got %r" % (date_str,))
    if (len(parts[0]), len(parts[1]), len(parts[2])) != (4, 2, 2):
        raise ValueError("wrong field widths in %r" % (date_str,))
    for part in parts:
        for ch in part:
            if ch not in DIGITS:
                raise ValueError("bad character %r in %r" % (ch, date_str))
    year, month, day = (int(p) for p in parts)
    if day < 1 or day > days_in_month(year, month):
        raise ValueError("day out of range for that month: %r" % (date_str,))
    return year, month, day


