def validate_inventory(inventory):
    """Return a cleaned copy of the inventory, dropping unusable entries."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict of item -> quantity")
    cleaned = {}
    for item, quantity in inventory.items():
        if not isinstance(item, str):
            raise TypeError("inventory keys must be strings")
        if type(quantity) not in (int, float):
            raise TypeError("quantity for %r must be numeric" % item)
        if quantity < 0:
            raise ValueError("quantity for %r must not be negative" % item)
        cleaned[item] = quantity
    return cleaned


def normalize_items(items_to_check):
    """Strip whitespace, drop blanks, and keep the first occurrence of each item."""
    if isinstance(items_to_check, str):
        raise TypeError("items_to_check must be a list of strings, not a string")
    normalized = []
    for raw in items_to_check:
        if not isinstance(raw, str):
            raise TypeError("item names must be strings")
        name = raw.strip()
        if not name:
            continue
        if name not in normalized:
            normalized.append(name)
    return normalized


def check_stock(inventory, items_to_check):
    """Return the available quantity of each requested item (0 when absent)."""
    stock = validate_inventory(inventory)
    stock_levels = {}
    for item in normalize_items(items_to_check):
        if item not in stock:
            stock_levels[item] = 0
        else:
            stock_levels[item] = stock[item]
    return stock_levels


def unknown_items(inventory, stock_levels):
    """Requested items that the inventory does not list at all."""
    return [item for item in stock_levels if item not in inventory]


def restock_plan(stock_levels, minimum=5):
    """Amount to order per item so every requested item reaches the minimum."""
    plan = {}
    for item, quantity in stock_levels.items():
        shortfall = minimum - quantity
        if shortfall > 0:
            plan[item] = shortfall
    return plan


def format_report(inventory, stock_levels, minimum=5):
    """Build a human-readable stock report with restock hints."""
    plan = restock_plan(stock_levels, minimum)
    lines = []
    for item, quantity in sorted(stock_levels.items()):
        if item not in plan:
            lines.append("%-10s %4d  ok" % (item, quantity))
        else:
            lines.append("%-10s %4d  order %d" % (item, quantity, plan[item]))
    unknown = unknown_items(inventory, stock_levels)
    if unknown:
        lines.append("not carried: " + ", ".join(sorted(unknown)))
    return "\n".join(lines)


def main():
    warehouse = {'apple': 10, 'banana': 5, 'cherry': 2}
    requested = ['apple', 'orange', ' banana ', 'cherry', 'apple']
    levels = check_stock(warehouse, requested)
    print(levels)
    print(format_report(warehouse, levels))
    print(check_stock({}, ['milk']))


if __name__ == '__main__':
    main()

