VALID_FEEDBACK = ('Too high', 'Too low', 'Correct!')
DIGITS = set('0123456789')


def parse_guess(text, low=1, high=100):
    """Turn raw player input into an int inside the legal guessing range."""
    stripped = text.strip()
    if not stripped:
        raise ValueError('empty input')
    body = stripped[1:] if stripped[0] in '+-' else stripped
    for char in body:
        if char not in DIGITS:
            raise ValueError('not a number: %r' % text)
    value = int(stripped)
    if value not in range(low, high + 1):
        raise ValueError('outside %d-%d: %d' % (low, high, value))
    return value


def simulate_guess(target, guess):
    """Feedback for a single round of the guessing game."""
    if guess > target:
        return 'Too high'
    if guess < target:
        return 'Too low'
    return 'Correct!'


def narrow_range(low, high, guess, feedback):
    """Shrink the still-possible range according to the feedback given."""
    if feedback not in VALID_FEEDBACK:
        raise ValueError('unknown feedback: %r' % feedback)
    if feedback == 'Too high':
        return low, guess - 1
    if feedback == 'Too low':
        return guess + 1, high
    return guess, guess


def suggest_guess(low, high, tried):
    """Untried number closest to the middle of the still-possible range."""
    candidates = [n for n in range(low, high + 1) if n not in tried]
    middle = (low + high) // 2
    return min(candidates, key=lambda n: abs(n - middle))


def play_round(target, guesses, low=1, high=100):
    """Feed raw guesses to the game and record what happened for each one."""
    if target not in range(low, high + 1):
        raise ValueError('target %d is unreachable' % target)
    transcript = []
    seen = []
    lo, hi = low, high
    for raw in guesses:
        try:
            guess = parse_guess(raw, low, high)
        except ValueError as exc:
            transcript.append(('invalid', str(exc)))
            continue
        if guess in seen:
            hint = suggest_guess(lo, hi, seen)
            transcript.append(('repeat', 'already tried %d, try %d' % (guess, hint)))
            continue
        seen.append(guess)
        feedback = simulate_guess(target, guess)
        transcript.append((guess, feedback))
        lo, hi = narrow_range(lo, hi, guess, feedback)
        if feedback == 'Correct!':
            break
    return transcript


def format_transcript(transcript):
    lines = []
    for label, message in transcript:
        if label not in ('invalid', 'repeat'):
            lines.append('Guess %d -> %s' % (label, message))
        else:
            lines.append('%s: %s' % (label.capitalize(), message))
    solved = any(message == 'Correct!' for _, message in transcript)
    lines.append('Solved' if solved else 'Not solved')
    return '\n'.join(lines)


def main():
    print(simulate_guess(7, 5))
    print(simulate_guess(7, 7))
    inputs = ['50', 'twelve', '25', '25', '12', '7']
    print(format_transcript(play_round(7, inputs)))


if __name__ == '__main__':
    main()

