VALID_OPERATIONS = ('push', 'pop')
LITERALS = {'none': None, 'true': True, 'false': False}


def simulate_stack(stack, operation, item=None):
    """Perform a single stack operation and return its result."""
    if not isinstance(stack, list):
        raise TypeError("stack must be a list")
    if operation not in VALID_OPERATIONS:
        raise ValueError("unknown operation: %r" % (operation,))
    if operation == 'push':
        stack.append(item)
        return stack
    if not stack:
        return None
    return stack.pop()


def parse_command(line):
    """Turn a text command such as 'push 3' into (operation, item)."""
    parts = line.split()
    if not parts:
        return None
    operation = parts[0].lower()
    if operation not in VALID_OPERATIONS:
        raise ValueError("cannot parse command: %r" % (line,))
    if operation == 'pop':
        return operation, None
    if len(parts) < 2:
        raise ValueError("push requires an item: %r" % (line,))
    return operation, convert(' '.join(parts[1:]))


def convert(text):
    """Convert a textual item to a literal, int or float when possible."""
    key = text.lower()
    if key not in LITERALS:
        try:
            return int(text)
        except ValueError:
            pass
        try:
            return float(text)
        except ValueError:
            return text
    return LITERALS[key]


def describe(operation, item, result):
    """Build a human readable line describing one performed operation."""
    if operation == 'push':
        return "pushed %r -> %r" % (item, result)
    if result is None:
        return "pop on empty stack -> None"
    return "popped %r" % (result,)


def run_script(lines, stack=None):
    """Run textual commands; return the log, final stack and pushed items."""
    if stack is None:
        stack = []
    log = []
    pushed = []
    for raw in lines:
        line = raw if '#' not in raw else raw.split('#', 1)[0]
        command = parse_command(line)
        if command is None:
            continue
        operation, item = command
        if operation == 'push' and item not in pushed:
            pushed.append(item)
        result = simulate_stack(stack, operation, item)
        log.append(describe(operation, item, result))
    return log, stack, pushed


def main():
    script = [
        "push 1",
        "push 2",
        "pop",
        "push hello",
        "push 3.5",
        "# nothing here",
        "pop",
        "pop",
        "pop",
    ]
    log, stack, pushed = run_script(script)
    for entry in log:
        print(entry)
    print("final stack:", stack)
    for item in pushed:
        if item not in stack:
            print("consumed:", item)


if __name__ == '__main__':
    main()

