import re

MENTION_RE = re.compile(r"@([A-Za-z0-9_]+)")
RESERVED = {"here", "everyone", "channel", "all"}


def extract_mentions(text):
    """Return the list of @mentions found in text, without the '@' symbol."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    mentions_list = []
    for match in MENTION_RE.finditer(text):
        start = match.start()
        if start > 0 and text[start - 1] not in " \t\n\r(<[{'\"":
            continue
        mentions_list.append(match.group(1))
    return mentions_list


def unique_mentions(text):
    """Mentions in order of first appearance, compared case-insensitively."""
    seen = set()
    result = []
    for name in extract_mentions(text):
        key = name.lower()
        if key not in seen:
            seen.add(key)
            result.append(name)
    return result


def real_users(text):
    """Drop broadcast keywords such as @here or @everyone."""
    return [name for name in unique_mentions(text) if name.lower() not in RESERVED]


def mention_counts(text):
    """Map each lowercase mention to how many times it occurs."""
    counts = {}
    for name in extract_mentions(text):
        key = name.lower()
        if key not in counts:
            counts[key] = 0
        counts[key] += 1
    return counts


def format_report(text):
    """Build a short human-readable summary of the mentions in text."""
    users = real_users(text)
    counts = mention_counts(text)
    if not users:
        return "no mentions"
    lines = []
    for name in users:
        lines.append("  @{} x{}".format(name, counts[name.lower()]))
    broadcasts = [n for n in unique_mentions(text) if n not in users]
    if broadcasts:
        lines.append("  broadcast: " + ", ".join(sorted(broadcasts)))
    return "\n".join(lines)


def main():
    samples = [
        "Hello @user1, how are you @user2?",
        "No mentions here.",
        "@here ping @Dev @dev and email me at bob@example.com",
        "(@alice) said hi to @bob_99!",
    ]
    for sample in samples:
        print(repr(sample))
        print("  mentions:", extract_mentions(sample))
        print(format_report(sample))


if __name__ == "__main__":
