"""Cubes up to a limit, with a small command-line reporting front end."""

import sys

_CACHE = {}
_DIGITS = "0123456789"


def cubes_up_to(limit):
    """Return the cubes of 0..limit inclusive as a list of ints."""
    if not isinstance(limit, int):
        raise TypeError("limit must be an int, got %r" % (limit,))
    if limit < 0:
        raise ValueError("limit must not be negative")
    if limit not in _CACHE:
        _CACHE[limit] = [n ** 3 for n in range(limit + 1)]
    cubes_list = list(_CACHE[limit])
    return cubes_list


def parse_limit(text):
    """Turn a command-line token into a non-negative int limit."""
    token = text.strip()
    if token == "":
        raise ValueError("empty limit")
    for ch in token:
        if ch not in _DIGITS:
            raise ValueError("limit %r is not a non-negative integer" % (text,))
    return int(token)


def missing_cubes(values, limit):
    """Values that are not among the cubes of 0..limit."""
    cubes = cubes_up_to(limit)
    return [v for v in values if v not in cubes]


def cubes_without_digit(limit, digit):
    """Cubes of 0..limit whose decimal form lacks the given digit."""
    if digit not in _DIGITS:
        raise ValueError("digit must be a single decimal character")
    return [c for c in cubes_up_to(limit) if digit not in str(c)]


def format_report(limit):
    """Build a short human-readable report for one limit."""
    cubes = cubes_up_to(limit)
    lines = ["limit %d -> %s" % (limit, cubes)]
    lines.append("  count: %d, largest: %d" % (len(cubes), cubes[-1]))
    zeroless = cubes_without_digit(limit, "0")
    lines.append("  without the digit '0': %s" % (zeroless,))
    probes = [limit ** 3, limit ** 3 + 1]
    absent = missing_cubes(probes, limit)
    lines.append("  probes %s absent from the list: %s" % (probes, absent))
    return "\n".join(lines)


def main(argv):
    args = argv[1:] or ["3", "0"]
    seen = []
    for text in args:
        if text not in seen:
            seen.append(text)
            try:
                limit = parse_limit(text)
            except ValueError as exc:
                print("skipping %r: %s" % (text, exc))
                continue
            print(format_report(limit))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

