ALLOWED_TYPES = (int, float)
COMMENT_MARKERS = "#;"


def _as_number(item, label):
    """Convert a single entry to float, rejecting bools and non-numeric types."""
    if isinstance(item, bool) or type(item) not in ALLOWED_TYPES:
        raise TypeError("{0} must be numeric, got {1!r}".format(label, item))
    return float(item)


def weighted_average(values, weights):
    """Return the weighted average of values with the given weights."""
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("values must not be empty")
    numerator = 0.0
    denominator = 0.0
    for index, (value, weight) in enumerate(zip(values, weights)):
        v = _as_number(value, "values[{0}]".format(index))
        w = _as_number(weight, "weights[{0}]".format(index))
        if w < 0.0:
            raise ValueError("weights[{0}] must not be negative".format(index))
        numerator += v * w
        denominator += w
    if denominator == 0.0:
        raise ValueError("the sum of the weights must not be zero")
    return numerator / denominator


def parse_record(line):
    """Parse 'label: value weight, value weight, ...' into (label, values, weights)."""
    if ":" not in line:
        raise ValueError("missing ':' separator in record {0!r}".format(line))
    label, payload = line.split(":", 1)
    label = label.strip()
    if not label:
        raise ValueError("record has an empty label")
    values = []
    weights = []
    for chunk in payload.split(","):
        parts = chunk.split()
        if len(parts) != 2:
            raise ValueError("expected 'value weight' pairs, got {0!r}".format(chunk))
        values.append(float(parts[0]))
        weights.append(float(parts[1]))
    return label, values, weights


def is_data_line(line):
    """True for a stripped line that carries data rather than a comment."""
    return bool(line) and line[0] not in COMMENT_MARKERS


def summarize(lines, wanted=None):
    """Build a {label: weighted average} mapping for the requested labels."""
    result = {}
    for line in lines:
        stripped = line.strip()
        if not is_data_line(stripped):
            continue
        label, values, weights = parse_record(stripped)
        if wanted is not None and label not in wanted:
            continue
        if label in result:
            raise ValueError("duplicate label {0!r}".format(label))
        result[label] = weighted_average(values, weights)
    if wanted is not None:
        for label in wanted:
            if label not in result:
                raise KeyError("no record found for label {0!r}".format(label))
    return result


def format_report(averages):
    width = max(len(label) for label in averages) if averages else 0
    lines = []
    for label in sorted(averages):
        lines.append("{0:<{1}}  {2:.3f}".format(label, width, averages[label]))
    return "\n".join(lines)


def main():
    print(weighted_average([10, 20, 30], [1, 2, 1]))
    print(weighted_average([5, 10], [0.5, 0.5]))
    data = [
        "; label: value weight pairs",
        "grades: 10 1, 20 2, 30 1",
        "coin: 5 0.5, 10 0.5",
        "ignored: 1 1, 2 1",
    ]
    print(format_report(summarize(data, wanted=["grades", "coin"])))


if __name__ == "__main__":
    main()

