VALID_LEVELS = ('DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL')


def parse_log_line(log_line):
    """Split 'Timestamp - Level - Message' into its three components."""
    if not isinstance(log_line, str):
        raise TypeError('log_line must be a string')
    if ' - ' not in log_line:
        raise ValueError('log_line must contain " - " separators')
    parts = log_line.split(' - ', 2)
    if len(parts) < 3:
        raise ValueError('log_line must have a timestamp, a level and a message')
    timestamp, level, message = (part.strip() for part in parts)
    if ':' not in timestamp:
        raise ValueError('timestamp must contain a time of day')
    parsed_log = {
        'timestamp': timestamp,
        'level': level.upper(),
        'message': message,
    }
    return parsed_log


def normalise_level(parsed_log):
    """Return the level, falling back to 'UNKNOWN' for unrecognised names."""
    level = parsed_log['level']
    if level not in VALID_LEVELS:
        return 'UNKNOWN'
    return level


def select_levels(entries, wanted):
    """Keep only the entries whose level appears in wanted."""
    chosen = []
    for entry in entries:
        if entry['level'] not in wanted:
            continue
        chosen.append(entry)
    return chosen


def summarise(entries):
    """Count how many entries carry each level."""
    counts = {}
    for entry in entries:
        level = entry['level']
        if level not in counts:
            counts[level] = 0
        counts[level] += 1
    return counts


def parse_log_file(lines):
    """Parse an iterable of raw lines, skipping blanks and reporting failures."""
    parsed = []
    errors = []
    for number, raw in enumerate(lines, start=1):
        if raw.strip() == '':
            continue
        try:
            entry = parse_log_line(raw.rstrip('\n'))
        except ValueError as exc:
            errors.append((number, str(exc)))
            continue
        entry['level'] = normalise_level(entry)
        parsed.append(entry)
    return parsed, errors


def format_entry(entry):
    """Render one parsed entry as an aligned single-line report row."""
    return '[%s] %-8s %s' % (entry['timestamp'], entry['level'], entry['message'])


def main():
    raw_lines = [
        '2023-10-26 10:30:00 - INFO - User logged in.',
        '',
        '2023-10-26 11:00:00 - ERROR - File not found.',
        '2023-10-26 11:05:12 - trace - Cache warmed.',
        'malformed line without separators',
    ]
    entries, errors = parse_log_file(raw_lines)
    for entry in select_levels(entries, ('ERROR', 'CRITICAL', 'INFO')):
        print(format_entry(entry))
    for level, total in sorted(summarise(entries).items()):
        print('%s: %d' % (level, total))
    for number, reason in errors:
        print('line %d skipped: %s' % (number, reason))


if __name__ == '__main__':
    main()

