import secrets
import string
import sys

DIGITS = string.digits
ROUND_DIGITS = ("0", "5")
WEAK_SEQUENCES = ("0123456789", "9876543210")


def generate_pin(length):
    """Return a random numeric PIN of the requested length as a string."""
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an integer")
    if length < 1:
        raise ValueError("length must be at least 1")
    return "".join(secrets.choice(DIGITS) for _ in range(length))


def is_numeric_pin(text):
    """True when text is non-empty and made only of decimal digits."""
    if not text:
        return False
    for ch in text:
        if ch not in DIGITS:
            return False
    return True


def looks_weak(pin):
    """Report simple weaknesses: repeated digit, digit run, no round digit."""
    reasons = []
    if len(set(pin)) == 1:
        reasons.append("all digits identical")
    for seq in WEAK_SEQUENCES:
        if len(pin) > 2 and pin in seq:
            reasons.append("consecutive digit run")
            break
    missing = [d for d in ROUND_DIGITS if d not in pin]
    if len(missing) == len(ROUND_DIGITS):
        reasons.append("no round digit")
    return reasons


def generate_strong_pin(length, issued=(), attempts=20):
    """Generate a PIN that avoids the weak patterns and any already issued one."""
    candidate = generate_pin(length)
    for _ in range(attempts):
        if candidate not in issued and not looks_weak(candidate):
            return candidate
        candidate = generate_pin(length)
    return candidate


def parse_lengths(args):
    """Turn command line arguments into a list of distinct PIN lengths."""
    lengths = []
    for arg in args:
        if not is_numeric_pin(arg):
            raise ValueError("length arguments must be digits: %r" % arg)
        value = int(arg)
        if value not in lengths:
            lengths.append(value)
    return lengths or [4, 6, 8]


def summarize(rows):
    """Collect the distinct weakness notes seen across the generated PINs."""
    reasons = []
    for _pin, notes in rows:
        for note in notes:
            if note not in reasons:
                reasons.append(note)
    return reasons


def format_report(rows):
    """Build a human readable table of PINs and their notes."""
    lines = []
    for pin, notes in rows:
        lines.append("%-10s %s" % (pin, ", ".join(notes) or "ok"))
    return "\n".join(lines)


def main():
    pins = []
    for length in parse_lengths(sys.argv[1:]):
        pins.append(generate_strong_pin(length, pins))
    rows = [(pin, looks_weak(pin)) for pin in pins]
    print(format_report(rows))
    print("weaknesses left:", ", ".join(summarize(rows)) or "none")


if __name__ == "__main__":
    main()

