import sys


ALLOWED_DIGITS = "0123456789"


def parse_number(text):
    """Turn a user supplied string into an int, rejecting junk input."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("empty input")
    sign = 1
    body = cleaned
    if cleaned[0] in "+-":
        body = cleaned[1:]
        if cleaned[0] == "-":
            sign = -1
    if not body:
        raise ValueError("sign without digits")
    for char in body:
        if char not in ALLOWED_DIGITS:
            raise ValueError(f"{char!r} is not a digit")
    return sign * int(body)


def sort_digits(number):
    """Return the integer formed by sorting the digits of `number` ascending."""
    if not isinstance(number, int):
        raise TypeError("sort_digits expects an int")
    sign = -1 if number < 0 else 1
    digits = sorted(str(abs(number)))
    return sign * int("".join(digits))


def unique_digits(number):
    """Digit characters of `number`, in order of first appearance."""
    seen = []
    for char in str(abs(number)):
        if char not in seen:
            seen.append(char)
    return seen


def describe_change(original, result):
    """Short human readable notes about what sorting did to the digits."""
    digits = str(abs(original))
    notes = []
    if "0" not in digits:
        notes.append("no zero digits")
    if len(str(abs(result))) != len(digits):
        notes.append("leading zeros dropped")
    if original == result:
        notes.append("already sorted")
    notes.append("distinct digits: " + ",".join(unique_digits(original)))
    return "; ".join(notes)


def sort_all(numbers, cache):
    """Sort the digits of every number, reusing previously computed answers."""
    for number in numbers:
        if number not in cache:
            cache[number] = sort_digits(number)
    return cache


def main(argv):
    inputs = argv[1:] or ["321", "5049", "-7210", "1000", "9"]
    texts = []
    for text in inputs:
        if text not in texts:
            texts.append(text)
    numbers = []
    for text in texts:
        try:
            numbers.append(parse_number(text))
        except ValueError as exc:
            print(f"skipping {text!r}: {exc}")
    cache = sort_all(numbers, {})
    for number in numbers:
        result = cache[number]
        print(f"{number} -> {result} ({describe_change(number, result)})")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

