"""Divisibility check for 3 and 5, with parsing and reporting helpers."""

DIGITS = "0123456789"
SEPARATORS = ",;"


def parse_int(text):
    """Convert a textual token into an int, rejecting malformed input."""
    token = text.strip()
    if not token:
        raise ValueError("empty token")
    sign = 1
    if token[0] not in DIGITS:
        if token[0] == "-":
            sign = -1
        elif token[0] != "+":
            raise ValueError("invalid leading character %r" % token[0])
        token = token[1:]
    if not token:
        raise ValueError("missing digits after sign")
    for char in token:
        if char not in DIGITS:
            raise ValueError("invalid character %r in number" % char)
    return sign * int(token)


def parse_line(line):
    """Split a line on commas, semicolons or whitespace; drop repeated values."""
    cleaned = "".join(" " if ch in SEPARATORS else ch for ch in line)
    numbers = []
    for token in cleaned.split():
        value = parse_int(token)
        if value not in numbers:
            numbers.append(value)
    return numbers


def is_divisible_by_3_and_5(number):
    """Return True if `number` is divisible by both 3 and 5."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be a plain int")
    return number % 3 == 0 and number % 5 == 0


def classify(numbers):
    """Group numbers by their divisibility verdict."""
    groups = {}
    for number in numbers:
        verdict = is_divisible_by_3_and_5(number)
        if verdict not in groups:
            groups[verdict] = []
        groups[verdict].append(number)
    return groups


def format_report(numbers):
    """Build a human readable report for the given numbers."""
    groups = classify(numbers)
    lines = ["%d -> %s" % (n, is_divisible_by_3_and_5(n)) for n in numbers]
    for verdict in (True, False):
        if verdict not in groups:
            continue
        label = "divisible" if verdict else "not divisible"
        values = ", ".join(str(n) for n in groups[verdict])
        lines.append("%s by 3 and 5: %s" % (label, values))
    return "\n".join(lines)


def main():
    samples = ["15, 10", "0 -30 7 15", "45;+60;-4"]
    for raw in samples:
        try:
            numbers = parse_line(raw)
        except ValueError as exc:
            print("skipping %r: %s" % (raw, exc))
            continue
        print("input: %s" % raw)
        print(format_report(numbers))
        print("-" * 32)


if __name__ == "__main__":
    main()

