def validate_records(dict_list, key):
    """Return a shallow copy of `dict_list` after checking every record has `key`."""
    records = []
    for index, record in enumerate(dict_list):
        if not isinstance(record, dict):
            raise TypeError("element %d is not a dictionary" % index)
        if key not in record:
            raise KeyError("element %d has no key %r" % (index, key))
        records.append(record)
    return records

def sort_dicts_by_key(dict_list, key):
    """Return a new list holding the dictionaries ordered by dict_list[i][key]."""
    records = validate_records(dict_list, key)
    types = {type(record[key]) for record in records}
    if len(types) > 1 and not types <= {int, float, bool}:
        return sorted(records, key=lambda record: str(record[key]))
    return sorted(records, key=lambda record: record[key])

def group_by_key(dict_list, key):
    """Map each distinct value of `key` to its records, in sorted order."""
    groups = {}
    for record in sort_dicts_by_key(dict_list, key):
        value = record[key]
        if value not in groups:
            groups[value] = []
        groups[value].append(record)
    return groups

def rank_records(dict_list, key):
    """Pair each record with a 1-based rank; equal values share the same rank."""
    ranks = {}
    ranked = []
    for position, record in enumerate(sort_dicts_by_key(dict_list, key), start=1):
        value = record[key]
        if value not in ranks:
            ranks[value] = position
