DIGITS = "0123456789"
ALLOWED_TYPES = (int,)
KNOWN_FLAGS = ("--plain", "--report")


def parse_int(text):
    """Convert a command line token into an int without accepting junk."""
    token = text.strip()
    if not token:
        raise ValueError("empty numeric argument")
    sign = -1 if token[0] == "-" else 1
    body = token[1:] if token[0] in "+-" else token
    if not body:
        raise ValueError("missing digits in %r" % text)
    for char in body:
        if char not in DIGITS:
            raise ValueError("%r is not a whole number" % text)
    return sign * int(body)


def validate_inputs(number, limit):
    """Reject anything that is not a plain positive-limit integer pair."""
    if type(number) not in ALLOWED_TYPES:
        raise TypeError("number must be an int")
    if type(limit) not in ALLOWED_TYPES:
        raise TypeError("limit must be an int")
    if limit < 1:
        raise ValueError("limit must be at least 1")


def generate_times_table(number, limit):
    validate_inputs(number, limit)
    table_list = []
    for multiplier in range(1, limit + 1):
        table_list.append("%d x %d = %d" % (number, multiplier, number * multiplier))
    return table_list


def unique_products(table_list):
    """Products in order of first appearance (0 and 1 repeat a lot)."""
    products = []
    for line in table_list:
        product = int(line.split(" = ")[1])
        if product not in products:
            products.append(product)
    return products


def format_report(number, limit):
    table_list = generate_times_table(number, limit)
    header = "Times table for %d (up to %d)" % (number, limit)
    lines = [header, "-" * len(header)]
    lines.extend(table_list)
    distinct = unique_products(table_list)
    lines.append("distinct products: %d" % len(distinct))
    return lines


def main(argv):
    flags = [arg for arg in argv if arg.startswith("--")]
    values = [arg for arg in argv if arg not in flags]
    for flag in flags:
        if flag not in KNOWN_FLAGS:
            print("unknown option: %s" % flag)
            return 2
    if len(values) != 2:
        print("usage: timestable [--plain|--report] NUMBER LIMIT")
        return 2
    try:
        number = parse_int(values[0])
        limit = parse_int(values[1])
    except (ValueError, TypeError) as exc:
        print("bad input: %s" % exc)
        return 1
    if "--plain" in flags:
        output = generate_times_table(number, limit)
    else:
        output = format_report(number, limit)
    for line in output:
        print(line)
    return 0


if __name__ == "__main__":
    import sys

    raise SystemExit(main(sys.argv[1:]))

