NUMBER_TYPES = (int, float)
ROW_TYPES = (list, tuple)
ALLOWED_NUMBER_CHARS = set("0123456789+-.eE")
ALIGNMENTS = ("left", "right")


def parse_number(token):
    """Convert a text token into an int or a float."""
    for char in token:
        if char not in ALLOWED_NUMBER_CHARS:
            raise ValueError("invalid character %r in number %r" % (char, token))
    if "." in token:
        return float(token)
    if "e" in token.lower():
        return float(token)
    return int(token)


def parse_matrix(text):
    """Read a matrix written as '1 2; 3 4' into a list of lists."""
    rows = []
    for chunk in text.split(";"):
        chunk = chunk.strip()
        if chunk:
            rows.append([parse_number(token) for token in chunk.split()])
    return rows


def validate_matrix(matrix, label):
    """Check that matrix is a rectangular collection of rows of numbers."""
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("%s must be a non-empty list of rows" % label)
    width = len(matrix[0])
    for index, row in enumerate(matrix):
        if type(row) not in ROW_TYPES:
            raise TypeError("row %d of %s is not a sequence" % (index, label))
        if len(row) != width:
            raise ValueError("row %d of %s has an inconsistent length" % (index, label))
        for value in row:
            if type(value) not in NUMBER_TYPES:
                raise TypeError("%s contains a non-numeric entry: %r" % (label, value))
    return len(matrix), width


def matrix_subtract(matrix1, matrix2):
    """Element-wise difference matrix1 - matrix2."""
    shape1 = validate_matrix(matrix1, "matrix1")
    shape2 = validate_matrix(matrix2, "matrix2")
    if shape1 != shape2:
        raise ValueError("shape mismatch: %r vs %r" % (shape1, shape2))
    return [[a - b for a, b in zip(row1, row2)]
            for row1, row2 in zip(matrix1, matrix2)]


def rows_without_zero(matrix):
    """Indices of rows in which no entry equals zero."""
    return [index for index, row in enumerate(matrix) if 0 not in row]


def format_matrix(matrix, align="right"):
    """Render a matrix as aligned text rows."""
    if align not in ALIGNMENTS:
        raise ValueError("align must be one of %r" % (ALIGNMENTS,))
    cells = [[str(value) for value in row] for row in matrix]
    width = max(len(cell) for row in cells for cell in row)
    lines = []
    for row in cells:
        if align == "right":
            lines.append(" ".join(cell.rjust(width) for cell in row))
        else:
            lines.append(" ".join(cell.ljust(width) for cell in row))
    return "\n".join(lines)


def report(matrix1, matrix2, align="right"):
    """Subtract, print the difference and note rows free of zeros."""
    result = matrix_subtract(matrix1, matrix2)
    print(format_matrix(result, align))
    interesting = rows_without_zero(result)
    if interesting:
        print("rows with no zero difference: %s" % interesting)
    else:
        print("every row contains at least one zero difference")
    return result


def main():
    report([[1, 2], [3, 4]], [[1, 1], [1, 1]])
    report([[5, 0]], [[1, -1]], align="left")
    report(parse_matrix("5 0; 2.5 7"), parse_matrix("1 -1; 0.5 3"))


if __name__ == "__main__":
    main()

