CURRENCY_SYMBOLS = {"USD": "$", "EUR": "€", "GBP": "£"}
REQUIRED_FIELDS = ("symbol", "buy_price", "sell_price", "quantity")


def calculate_stock_profit(buy_price, sell_price, quantity):
    """Return the profit (positive) or loss (negative) of one round trip."""
    for name, value in (("buy_price", buy_price), ("sell_price", sell_price)):
        if type(value) not in (int, float):
            raise TypeError(name + " must be a number")
        if value < 0:
            raise ValueError(name + " must not be negative")
    if not isinstance(quantity, int) or isinstance(quantity, bool):
        raise TypeError("quantity must be an integer")
    if quantity < 0:
        raise ValueError("quantity must not be negative")
    return float((sell_price - buy_price) * quantity)


def parse_trade(record):
    """Normalise a dict describing one trade into usable values."""
    missing = [field for field in REQUIRED_FIELDS if field not in record]
    if missing:
        raise KeyError("missing trade fields: " + ", ".join(missing))
    currency = record.get("currency", "USD")
    if currency not in CURRENCY_SYMBOLS:
        raise ValueError("unsupported currency: " + str(currency))
    return {
        "symbol": str(record["symbol"]).upper(),
        "buy_price": float(record["buy_price"]),
        "sell_price": float(record["sell_price"]),
        "quantity": int(record["quantity"]),
        "currency": currency,
    }


def format_amount(amount, currency="USD"):
    if currency not in CURRENCY_SYMBOLS:
        raise ValueError("unsupported currency: " + str(currency))
    sign = "-" if amount < 0 else ""
    return "{}{}{:,.2f}".format(sign, CURRENCY_SYMBOLS[currency], abs(amount))


def summarise_trades(records):
    """Aggregate profit per symbol and the overall total."""
    per_symbol = {}
    total = 0.0
    for record in records:
        trade = parse_trade(record)
        result = calculate_stock_profit(
            trade["buy_price"], trade["sell_price"], trade["quantity"]
        )
        symbol = trade["symbol"]
        if symbol not in per_symbol:
            per_symbol[symbol] = 0.0
        per_symbol[symbol] += result
        total += result
    return per_symbol, total


def report(records, currency="USD"):
    per_symbol, total = summarise_trades(records)
    lines = []
    for symbol in sorted(per_symbol):
        amount = per_symbol[symbol]
        label = "profit" if amount >= 0 else "loss"
        lines.append("{:<6} {:>14}  ({})".format(symbol, format_amount(amount, currency), label))
