DIGITS = frozenset("0123456789")


def needs_decoding(item, cache):
    """True when item has no decoded result stored in cache yet."""
    return item not in cache


def tokenize(text):
    """Split run-length encoded text into a list of (count, symbol) pairs."""
    tokens = []
    pos = 0
    total = len(text)
    while pos < total:
        if text[pos] not in DIGITS:
            raise ValueError("expected a count at position %d" % pos)
        start = pos
        while pos < total and text[pos] in DIGITS:
            pos += 1
        digits = text[start:pos]
        if pos >= total:
            raise ValueError("count %s has no symbol to repeat" % digits)
        tokens.append((int(digits), text[pos]))
        pos += 1
    return tokens


def run_length_decode(encoded_string):
    """Expand '3A2B1C' into 'AAABBC'."""
    return "".join(symbol * count for count, symbol in tokenize(encoded_string))


def decode_all(items, cache):
    """Decode every item, storing results in cache and reusing repeats."""
    for item in items:
        if needs_decoding(item, cache):
            cache[item] = run_length_decode(item)
    return [cache[item] for item in items]


def tally(decoded):
    """Count how often each symbol occurs in a decoded string."""
    counts = {}
    for ch in decoded:
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def corpus_alphabet(decoded_list):
    """Symbols used anywhere in the decoded strings, first appearance first."""
    alphabet = ""
    for decoded in decoded_list:
        fresh = [ch for ch in dict.fromkeys(decoded) if ch not in alphabet]
        alphabet += "".join(fresh)
    return alphabet


def check_samples(samples, cache):
    """Print how each undecoded sample fares; return the distinct errors."""
    problems = []
    for sample in [s for s in samples if s not in cache]:
        try:
            cache[sample] = run_length_decode(sample)
        except ValueError as error:
            message = str(error)
            if message not in problems:
                problems.append(message)
            print("%-10s -> rejected: %s" % (sample, message))
        else:
            print("%-10s -> %r" % (sample, cache[sample]))
    return problems


def main():
    cache = {}
    good = ["3A2B1C", "1X", "", "12Z", "2A2A", "3A2B1C", "10 1!"]
    decoded_list = decode_all(good, cache)
    for encoded, decoded in zip(good, decoded_list):
        counts = tally(decoded)
        profile = " ".join("%r:%d" % (ch, counts[ch]) for ch in counts)
        print("%-10s -> %-14r %s" % (encoded, decoded, profile))
    print("alphabet: %r" % corpus_alphabet(decoded_list))
    failures = check_samples(["A3", "5", "2A3", "4z", "1X"], cache)
    print("distinct failures: %d" % len(failures))


if __name__ == "__main__":
    main()

