HEX_DIGITS = "0123456789ABCDEF"
DECIMAL_DIGITS = "0123456789"
SIGNS = "+-"
STYLES = {"plain": "", "prefixed": "0x"}


def decimal_to_hex(decimal_num):
    """Return the hexadecimal representation of an integer."""
    if not isinstance(decimal_num, int) or isinstance(decimal_num, bool):
        raise TypeError("decimal_num must be an int")
    if decimal_num == 0:
        return "0"
    value = abs(decimal_num)
    digits = []
    while value > 0:
        digits.append(HEX_DIGITS[value % 16])
        value //= 16
    if decimal_num < 0:
        digits.append("-")
    return "".join(reversed(digits))


def split_sign(text):
    """Separate a leading '+'/'-' from the rest of a numeric token."""
    if text[:1] not in SIGNS:
        return "+", text
    return text[0], text[1:]


def hex_to_decimal(hex_string):
    """Inverse of decimal_to_hex, accepting a sign and an optional 0x prefix."""
    sign, body = split_sign(hex_string.strip().upper())
    if body.startswith("0X"):
        body = body[2:]
    if not body:
        raise ValueError("no hexadecimal digits found in %r" % hex_string)
    total = 0
    for char in body:
        if char not in HEX_DIGITS:
            raise ValueError("invalid hexadecimal digit %r" % char)
        total = total * 16 + HEX_DIGITS.index(char)
    return -total if sign == "-" else total


def parse_decimal(token):
    """Turn a user-supplied token such as '255' or '-16' into an int."""
    sign, body = split_sign(token.strip())
    if not body:
        raise ValueError("empty number: %r" % token)
    for char in body:
        if char not in DECIMAL_DIGITS:
            raise ValueError("%r is not a decimal integer" % token)
    return -int(body) if sign == "-" else int(body)


def unique(values):
    """Drop repeated values while keeping the original order."""
    kept = []
    for value in values:
        if value not in kept:
            kept.append(value)
    return kept


def digits_used(texts):
    """Collect the hexadecimal digits appearing in the rendered numbers."""
    found = []
    for text in texts:
        for char in text.upper():
            if char in HEX_DIGITS and char not in found:
                found.append(char)
    return "".join(sorted(found))


def render(decimal_num, style):
    """Format one number, keeping the sign in front of the 0x prefix."""
    sign, body = split_sign(decimal_to_hex(decimal_num))
    return ("-" if sign == "-" else "") + STYLES[style] + body


def build_report(tokens, style="plain"):
    """Convert every token and report bad input and round-trip failures."""
    if style not in STYLES:
        raise ValueError("unknown style %r" % style)
    numbers = []
    problems = []
    for token in unique(tokens):
        try:
            numbers.append(parse_decimal(token))
        except ValueError as exc:
            problems.append("skipping %s (%s)" % (token, exc))
    rendered = [render(number, style) for number in numbers]
    width = max([len(text) for text in rendered], default=0)
    lines = []
    for number, text in zip(numbers, rendered):
        row = "%8d -> %s" % (number, text.rjust(width))
        if hex_to_decimal(text) != number:
            row += "  [round-trip mismatch]"
        lines.append(row)
    lines.append("digits used: %s" % digits_used(rendered))
    return lines + problems


def main():
    tokens = ["255", "10", "0", "4095", "-31", "1048576", "255", "twelve"]
    for style in sorted(STYLES):
        print("style: %s" % style)
        for line in build_report(tokens, style):
            print(line)


if __name__ == "__main__":
    main()

