"""Hexadecimal literal parsing and conversion helpers."""

HEX_DIGITS = "0123456789ABCDEF"
PREFIXES = ("0X", "&H")
SUFFIXES = ("H",)
SEPARATORS = " _,"
SIGNS = ("+", "-")


def strip_prefix(text):
    """Drop a leading base marker such as 0x or &H."""
    marker = text[:2].upper()
    if marker not in PREFIXES:
        return text
    return text[2:]


def strip_suffix(text):
    """Drop a trailing assembler-style H marker."""
    marker = text[-1:].upper()
    if marker not in SUFFIXES:
        return text
    return text[:-1]


def remove_separators(text):
    kept = []
    for char in text:
        if char not in SEPARATORS:
            kept.append(char)
    return "".join(kept)


def split_sign(text):
    first = text[:1]
    if first not in SIGNS:
        return "", text
    return first, text[1:]


def validate(digits):
    if not digits:
        raise ValueError("empty hexadecimal string")
    for position, char in enumerate(digits):
        if char not in HEX_DIGITS:
            raise ValueError("bad digit %r at index %d" % (char, position))
    return digits


def normalize(hex_string):
    """Return (sign, upper-case digit string) for a hex literal."""
    if not isinstance(hex_string, str):
        raise ValueError("hex_to_decimal expects a string")
    sign, body = split_sign(hex_string.strip())
    body = strip_suffix(strip_prefix(body.strip()))
    return sign, validate(remove_separators(body).upper())


def hex_to_decimal(hex_string):
    """Convert a hexadecimal string into its decimal integer value."""
    sign, digits = normalize(hex_string)
    decimal_num = 0
    for char in digits:
        decimal_num = decimal_num * 16 + HEX_DIGITS.index(char)
    return -decimal_num if sign == "-" else decimal_num


def describe(hex_string):
    """Format one input with its decimal value, or the parse error."""
    try:
        sign, digits = normalize(hex_string)
    except ValueError as exc:
        return "%-12s -> error: %s" % (repr(hex_string), exc)
    canonical = sign + (digits.lstrip("0") or "0")
    decimal_num = hex_to_decimal(hex_string)
    if hex_string not in (canonical, canonical.lower()):
        return "%-12s -> %d (canonical %s)" % (
            repr(hex_string), decimal_num, canonical)
    return "%-12s -> %d" % (repr(hex_string), decimal_num)


def main():
    samples = ["FF", "A", "0x1f", "00ff", "dead_beef", "1Fh",
               "-2A", "", "G1", 42]
    for sample in samples:
        print(describe(sample))


