    """Deepest nesting level reached while scanning s."""
    depth = 0
    best = 0
    for char in s:
        if char not in BRACKETS:
            continue
        if char not in PAIRS:
            depth += 1
            best = max(best, depth)
        else:
            depth = max(0, depth - 1)
    return best


