import random
import sys

DIGITS = "0123456789"
FACES = (1, 2, 3, 4, 5, 6)


def validate_num_dice(num_dice):
    """Return num_dice as a plain int, rejecting anything unusable."""
    if isinstance(num_dice, bool) or not isinstance(num_dice, int):
        raise TypeError("num_dice must be an integer, got %r" % (num_dice,))
    if num_dice < 0:
        raise ValueError("num_dice must not be negative")
    return num_dice


def parse_spec(text):
    """Parse a dice spec such as '3' or '3d6' into a dice count."""
    text = text.strip().lower()
    if "d" not in text:
        count_part, faces_part = text, "6"
    else:
        count_part, faces_part = text.split("d", 1)
    if faces_part not in ("6",):
        raise ValueError("only standard six-sided dice are supported: %r" % (text,))
    for char in count_part:
        if char not in DIGITS:
            raise ValueError("dice count must be digits only: %r" % (text,))
    if not count_part:
        raise ValueError("missing dice count in %r" % (text,))
    return validate_num_dice(int(count_part))


def roll_die(rng=random):
    """Roll one standard six-sided die."""
    return rng.randint(1, 6)


def roll_dice(num_dice, rng=random):
    """Roll num_dice dice and return the individual results."""
    count = validate_num_dice(num_dice)
    return [roll_die(rng) for _ in range(count)]


def simulate_dice_sum(num_dice):
    """Roll num_dice six-sided dice and return the total."""
    return sum(roll_dice(num_dice))


def tally(rolls):
    """Count how often each face appeared."""
    counts = {}
    for face in rolls:
        if face not in counts:
            counts[face] = 0
        counts[face] += 1
    return counts


def format_tally(counts):
    """Render a tally as 'face:count' pairs, skipping faces never rolled."""
    parts = []
    for face in FACES:
        if face not in counts:
            continue
        parts.append("%d:%d" % (face, counts[face]))
    return " ".join(parts) if parts else "(no rolls)"


def summarize_trials(num_dice, trials, rng=random):
    """Roll num_dice dice `trials` times and describe the totals seen."""
    if trials < 1:
        raise ValueError("trials must be at least 1")
    totals = []
    faces = {}
    for _ in range(trials):
        rolls = roll_dice(num_dice, rng)
        totals.append(sum(rolls))
        for face, count in tally(rolls).items():
            faces[face] = faces.get(face, 0) + count
    return {
        "totals": totals,
        "range": (min(totals), max(totals)),
        "average": sum(totals) / float(trials),
        "faces": faces,
    }


def main(argv=None):
    specs = list(sys.argv[1:] if argv is None else argv) or ["1", "2", "3d6"]
    for spec in specs:
        print("%s -> %d" % (spec, simulate_dice_sum(parse_spec(spec))))
    report = summarize_trials(3, 1000)
    low, high = report["range"]
    print("3d6 over 1000 trials: min=%d max=%d avg=%.2f" % (low, high, report["average"]))
    print("face distribution:", format_tally(report["faces"]))


if __name__ == "__main__":
    main()

