import re
import sys

DIGITS = "0123456789"


def parse_numbers(text):
    """Turn a textual list such as "1, 2, 3, 2" into a list of integers."""
    tokens = [token for token in re.split(r"[\s,;]+", text.strip()) if token]
    if not tokens:
        raise ValueError("no numbers found in input")
    numbers = []
    for token in tokens:
        for char in token:
            if char not in DIGITS:
                raise ValueError("%r is not a positive integer" % token)
        numbers.append(int(token))
    return numbers


def validate_numbers(numbers):
    """Check the 1..N-with-one-duplicate shape and return N."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    n = len(numbers) - 1
    if n < 1:
        raise ValueError("need at least two entries to hold a duplicate")
    expected = frozenset(range(1, n + 1))
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("all entries must be plain integers")
        if value not in expected:
            raise ValueError("%r is outside the range 1..%d" % (value, n))
    return n


def find_duplicate(numbers):
    """Return the single value that occurs twice in numbers."""
    validate_numbers(numbers)
    seen = set()
    for value in numbers:
        if value not in seen:
            seen.add(value)
        else:
            return value
    raise ValueError("no duplicated number present")


def index_positions(numbers):
    """Map every value to the (ascending) indices where it occurs."""
    positions = {}
    for index, value in enumerate(numbers):
        if value not in positions:
            positions[value] = []
        positions[value].append(index)
    return positions


