def distinct(words):
    seen = set()
    unique = []
    for word in words:
        if word not in seen:
            seen.add(word)
            unique.append(word)
    return unique


def group_anagrams(words):
    """Group the given words so that each inner list holds mutual anagrams."""
    buckets = {}
    order = []
    for word in words:
        key = anagram_key(word)
        if key not in buckets:
            buckets[key] = []
            order.append(key)
        buckets[key].append(word)
    return [buckets[key] for key in order]


def build_index(anagram_groups):
    index = {}
    for position, group in enumerate(anagram_groups):
        for word in group:
            if word not in index:
                index[word] = position
    return index


