def has_overlap(meeting1, meeting2):
    """Return True if the two half-open intervals (start, end) share any time."""
    start1, end1 = _validate(meeting1)
    start2, end2 = _validate(meeting2)
    return start1 < end2 and start2 < end1


def _validate(meeting):
    if type(meeting) not in (tuple, list):
        raise TypeError("a meeting must be a tuple or list of two values")
    if len(meeting) != 2:
        raise ValueError("a meeting must have exactly two values")
    start, end = meeting
    for value in (start, end):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("meeting times must be integers")
    if end < start:
        raise ValueError("a meeting cannot end before it starts")
    return start, end


def parse_time(text):
    """Convert 'HH:MM' into minutes since midnight."""
    if ":" not in text:
        raise ValueError("time %r must look like HH:MM" % text)
    hours, _, minutes = text.partition(":")
    for part in (hours, minutes):
        for char in part:
            if char not in "0123456789":
                raise ValueError("time %r contains a non-digit" % text)
    total = int(hours) * 60 + int(minutes)
    if total >= 24 * 60:
        raise ValueError("time %r is outside a single day" % text)
    return total


def format_time(minutes):
    return "%02d:%02d" % divmod(minutes, 60)


def build_schedule(entries):
    """Group (room, start_text, end_text) entries into {room: [(start, end)]}."""
    schedule = {}
    for room, start_text, end_text in entries:
        if room not in schedule:
            schedule[room] = []
        schedule[room].append((parse_time(start_text), parse_time(end_text)))
    return schedule


def find_conflicts(schedule):
    """List every pair of meetings in the same room that overlap."""
    conflicts = []
    for room in sorted(schedule):
        meetings = sorted(schedule[room])
        for i, earlier in enumerate(meetings):
            for later in meetings[i + 1:]:
                if has_overlap(earlier, later):
                    conflicts.append((room, earlier, later))
    return conflicts


def describe(conflicts):
    lines = []
    reported_rooms = []
    for room, first, second in conflicts:
        if room not in reported_rooms:
            reported_rooms.append(room)
            lines.append("Room %s:" % room)
        lines.append("  %s-%s clashes with %s-%s" % (
            format_time(first[0]), format_time(first[1]),
            format_time(second[0]), format_time(second[1])))
    if not lines:
        lines.append("No conflicts found.")
    return "\n".join(lines)


def main():
    print(has_overlap((1, 5), (3, 7)))
    print(has_overlap((1, 2), (3, 4)))
    entries = [
        ("A1", "09:00", "10:30"),
        ("A1", "10:00", "11:00"),
        ("A1", "11:00", "12:00"),
        ("B2", "13:15", "14:00"),
    ]
    print(describe(find_conflicts(build_schedule(entries))))


if __name__ == "__main__":
    main()

