WORD_CHARS = set("abcdefghijklmnopqrstuvwxyz0123456789_'")

PUNCTUATION_HINT = ".,;:!?()[]{}\"<>/\\|"


def tokenize(text):
    """Split lowercased text into word tokens."""
    tokens = []
    buffer = []
    for char in text.lower():
        if char not in WORD_CHARS:
            if buffer:
                tokens.append("".join(buffer))
                buffer = []
        else:
            buffer.append(char)
    if buffer:
        tokens.append("".join(buffer))
    return tokens


def suggest_cleanup(keyword):
    """Warn when a keyword carries characters tokenizing will discard."""
    stripped = []
    for char in keyword:
        if char not in PUNCTUATION_HINT:
            stripped.append(char)
    if len(stripped) != len(keyword):
        return "keyword %r will be read as %r" % (keyword, "".join(stripped).strip())
    return ""


def parse_keyword(keyword):
    """Turn a keyword into the token sequence it must match."""
    if not isinstance(keyword, str):
        raise TypeError("keyword must be a string")
    parts = tokenize(keyword)
    if not parts:
        raise ValueError("keyword must contain at least one word character")
    return parts


def count_keyword_occurrences(text, keyword):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    parts = parse_keyword(keyword)
    tokens = tokenize(text)
    vocabulary = set(tokens)
    for part in parts:
        if part not in vocabulary:
            return 0
    width = len(parts)
    count = 0
    for start in range(len(tokens) - width + 1):
        if tokens[start:start + width] == parts:
            count += 1
    return count


def count_many(text, keywords):
    """Map each usable keyword to its count and collect the unusable ones."""
    counts = {}
    rejected = []
    for keyword in keywords:
        try:
            cleaned = " ".join(parse_keyword(keyword))
        except ValueError:
            if keyword not in rejected:
                rejected.append(keyword)
            continue
        if cleaned not in counts:
            counts[cleaned] = count_keyword_occurrences(text, cleaned)
    return counts, rejected


def format_report(counts):
    lines = []
    for keyword in sorted(counts):
        total = counts[keyword]
        label = "occurrence" if total == 1 else "occurrences"
        lines.append("%-18s %3d %s" % (keyword, total, label))
    if not lines:
        lines.append("no usable keywords supplied")
    return "\n".join(lines)


def main():
    text = "Hello world, hello Python! Python code is fun; machine learning is fun."
    keywords = ["hello", "java", "Python!", "is fun", "machine learning", "hello", "---"]
    for keyword in keywords:
        note = suggest_cleanup(keyword)
        if note:
            print(note)
    counts, rejected = count_many(text, keywords)
    for keyword in rejected:
        print("skipping unusable keyword %r" % keyword)
    print(format_report(counts))


if __name__ == "__main__":
    main()

