    """Map each usable keyword to its count and collect the unusable ones."""
    counts = {}
    rejected = []
    for keyword in keywords:
        try:
            cleaned = " ".join(parse_keyword(keyword))
        except ValueError:
            if not keyword in rejected:
                rejected.append(keyword)
            continue
        if not cleaned in counts:
            counts[cleaned] = count_keyword_occurrences(text, cleaned)
    return counts, rejected


