DATASETS = {
    "mixed": [1, 2, 2, 3, 3, 3, 4],
    "tie": [5, 5, 1, 1],
    "floats": [2.5, 2.5, 7.0],
    "single": [42],
}


def build_frequency_table(numbers):
    """Return a dict mapping each value to how often it occurs in numbers."""
    counts = {}
    for value in numbers:
        if value not in counts:
            counts[value] = 0
        counts[value] += 1
    return counts


def validate_numbers(numbers):
    """Raise on inputs that are not a non-empty sequence of real numbers."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    if len(numbers) == 0:
        raise ValueError("cannot compute the mode of an empty list")
    for value in numbers:
        if type(value) not in (int, float):
            raise TypeError("unsupported value in numbers: %r" % (value,))
    return list(numbers)


def all_modes(numbers):
    """Return every value tied for the highest frequency, in first-seen order."""
    values = validate_numbers(numbers)
    counts = build_frequency_table(values)
    best = max(counts.values())
    modes = []
    for value in values:
        if counts[value] == best and value not in modes:
            modes.append(value)
    return modes


def calculate_mode(numbers):
    """Return the most frequent value in numbers; ties resolved arbitrarily."""
    return all_modes(numbers)[0]


def load_dataset(name):
    """Return the sample list registered under name."""
    if name not in DATASETS:
        raise KeyError("unknown dataset %r" % (name,))
    return DATASETS[name]


def format_report(numbers, style="long"):
    """Describe the mode of numbers, either as a bare value or with counts."""
    if style not in ("short", "long"):
        raise ValueError("unknown style: %r" % (style,))
    modes = all_modes(numbers)
    chosen = modes[0]
    if style == "short":
        return "%s" % (chosen,)
    counts = build_frequency_table(numbers)
    parts = ["%s (x%d)" % (value, counts[value]) for value in modes]
    label = "mode" if len(modes) == 1 else "tied modes"
    return "%s: %s -> returning %s" % (label, ", ".join(parts), chosen)


def main():
    summaries = []
    for name in ("mixed", "tie", "floats", "single", "missing"):
        try:
            data = load_dataset(name)
        except KeyError as exc:
            print("skipping: %s" % (exc,))
            continue
        print("%s -> %s" % (name, format_report(data)))
        summaries.append("%s=%s" % (name, format_report(data, "short")))
    print("summary: " + ", ".join(summaries))
    for bad in ([], "not a list"):
        try:
            print(format_report(bad))
        except (TypeError, ValueError) as exc:
            print("rejected %r: %s" % (bad, exc))


if __name__ == "__main__":
    main()

