WHITESPACE = " \t\n\r\f\v"
TERMINATORS = ".!?"
STOPWORDS = frozenset({"a", "an", "the", "is", "are", "of", "and", "to", "in", "it"})


def _split_words(sentence):
    """Split on any run of whitespace, dropping the separators."""
    words = []
    current = []
    for ch in sentence:
        if ch not in WHITESPACE:
            current.append(ch)
        elif current:
            words.append("".join(current))
            current = []
    if current:
        words.append("".join(current))
    return words


def _strip_terminator(word):
    """Split a trailing '.', '!' or '?' off a non-empty word."""
    if word[-1] not in TERMINATORS:
        return word, ""
    return word[:-1], word[-1]


def _word_keys(sentence):
    """Lower-cased words with sentence punctuation removed, in reading order."""
    keys = []
    for word in _split_words(sentence):
        core = _strip_terminator(word)[0].lower()
        if core:
            keys.append(core)
    return keys


def word_counts(sentence):
    """Map each normalised word to how often it occurs."""
    counts = {}
    for key in _word_keys(sentence):
        if key not in counts:
            counts[key] = 0
        counts[key] += 1
    return counts


def unique_words(sentence):
    """Normalised words in first-appearance order, duplicates dropped."""
    seen = []
    for key in _word_keys(sentence):
        if key not in seen:
            seen.append(key)
    return seen


def keywords(sentence):
    """Unique words that carry meaning, i.e. everything but the stop words."""
    return [word for word in unique_words(sentence) if word not in STOPWORDS]


def repeated_words(sentence):
    counts = word_counts(sentence)
    return [word for word in unique_words(sentence) if counts[word] > 1]


def reverse_sentence_words(sentence):
    """Reverse the order of the words in `sentence`, keeping each word intact."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a str, got %s" % type(sentence).__name__)
    return " ".join(reversed(_split_words(sentence)))


def reverse_preserving_terminator(sentence):
    """Reverse word order but keep sentence punctuation and capitalisation sane."""
    words = _split_words(sentence)
    if not words:
        return ""
    core, terminator = _strip_terminator(words[-1])
    words = words[:-1]
    if core:
        words.append(core)
    text = " ".join(reversed(words))
    if text:
        text = text[0].upper() + text[1:]
    return text + terminator


def format_report(sentence):
    return "\n".join(["input:    %r" % sentence,
                      "reversed: %r" % reverse_sentence_words(sentence),
                      "polished: %r" % reverse_preserving_terminator(sentence),
                      "keywords: %s" % ", ".join(keywords(sentence)),
                      "repeated: %s" % ", ".join(repeated_words(sentence))])


def main():
    samples = ["hello world",
               "python is fun",
               "The quick brown fox jumps!",
               "never odd or never",
               "   spaced   out   text   "]
    for sentence in samples:
        print(format_report(sentence))
        print("-" * 40)


if __name__ == "__main__":
    main()

