def merge_dicts(dict1, dict2):
    """Return a new dict with dict2's entries overriding dict1's on shared keys."""
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise TypeError("merge_dicts expects two dictionaries")
    merged = {}
    for key, value in dict1.items():
        merged[key] = value
    for key, value in dict2.items():
        merged[key] = value
    return merged


def classify_keys(dict1, dict2):
    """Split dict2's keys into the ones that are new and the ones that override."""
    added = []
    overridden = []
    for key in dict2:
        if key not in dict1:
            added.append(key)
        else:
            overridden.append(key)
    return added, overridden


def untouched_keys(dict1, dict2):
    """Keys of dict1 whose values survive the merge unchanged."""
    return [key for key in dict1 if key not in dict2]


def merge_order(dict1, dict2):
    """Display order for a merge: dict1's keys, then dict2's brand-new keys."""
    order = list(dict1)
    for key in dict2:
        if key not in dict1:
            order.append(key)
    return order


def changed_entries(original, merged):
    """Entries of merged that are new or differ from original, as triples."""
    changes = []
    for key, value in merged.items():
        if key not in original:
            changes.append((key, None, value))
        elif original[key] != value:
            changes.append((key, original[key], value))
    return changes


def describe_merge(dict1, dict2):
    """Build a short human-readable report of what the merge does."""
    added, overridden = classify_keys(dict1, dict2)
    kept = untouched_keys(dict1, dict2)
    lines = []
    if added:
        lines.append("added: " + ", ".join(repr(k) for k in added))
    if overridden:
        parts = ["%r: %r -> %r" % (k, dict1[k], dict2[k]) for k in overridden]
        lines.append("overwritten: " + "; ".join(parts))
    if kept:
        lines.append("kept: " + ", ".join(repr(k) for k in kept))
    if not lines:
        lines.append("nothing to merge")
    return "\n".join(lines)


def merge_all(dicts):
    """Fold a sequence of dictionaries left to right, later values winning."""
