DIGITS = "0123456789"
MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
MIN_YEAR = 1
MAX_YEAR = 9999


def _is_leap(year):
    if year % 4 != 0:
        return False
    if year % 100 != 0:
        return True
    return year % 400 == 0


def _days_in_month(year, month):
    if month == 2 and _is_leap(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def parse_date(date_str):
    if not isinstance(date_str, str):
        raise TypeError("date must be a string in 'YYYY-MM-DD' format")
    parts = date_str.strip().split("-")
    if len(parts) != 3:
        raise ValueError("malformed date: %r" % date_str)
    year_text, month_text, day_text = parts
    if len(year_text) != 4 or len(month_text) != 2 or len(day_text) != 2:
        raise ValueError("malformed date: %r" % date_str)
    for chunk in parts:
        for ch in chunk:
            if ch not in DIGITS:
                raise ValueError("non-digit in date: %r" % date_str)
    year, month, day = int(year_text), int(month_text), int(day_text)
    if year not in range(MIN_YEAR, MAX_YEAR + 1):
        raise ValueError("year out of supported range in %r" % date_str)
    if month not in range(1, 13):
        raise ValueError("month out of range in %r" % date_str)
    if day not in range(1, _days_in_month(year, month) + 1):
        raise ValueError("day out of range in %r" % date_str)
    return year, month, day


def to_ordinal(year, month, day):
    total = 0
    for y in range(MIN_YEAR, year):
        total += 366 if _is_leap(y) else 365
    for m in range(1, month):
        total += _days_in_month(year, m)
    return total + day


def days_between_dates(start_date_str, end_date_str):
    start = to_ordinal(*parse_date(start_date_str))
    end = to_ordinal(*parse_date(end_date_str))
    return end - start


def describe(start_date_str, end_date_str):
    delta = days_between_dates(start_date_str, end_date_str)
    if delta not in (-1, 0, 1):
        unit = "days"
    else:
        unit = "day"
    if delta < 0:
        direction = "before"
    else:
        direction = "after"
    return "%s is %d %s %s %s" % (end_date_str, abs(delta), unit, direction, start_date_str)


def main():
    pairs = [
        ("2023-01-01", "2023-01-05"),
        ("2023-01-01", "2022-12-25"),
        ("2020-02-28", "2020-03-01"),
        ("2023-13-01", "2023-01-01"),
        ("2023/01/01", "2023-01-02"),
    ]
    for start, end in pairs:
        try:
            print(describe(start, end))
        except (TypeError, ValueError) as exc:
            print("skipping (%s, %s): %s" % (start, end, exc))


if __name__ == "__main__":
    main()

