import random

STANDARD_DICE = (4, 6, 8, 10, 12, 20, 100)
DIGITS = "0123456789"


def roll_die(num_sides):
    """Return a random integer between 1 and num_sides (inclusive)."""
    if not isinstance(num_sides, int) or isinstance(num_sides, bool):
        raise TypeError("num_sides must be an integer")
    if num_sides < 2:
        raise ValueError("a die needs at least 2 sides")
    return random.randint(1, num_sides)


def parse_dice_notation(text):
    """Turn notation like '3d6' or 'd20' into a (count, sides) pair."""
    cleaned = text.strip().lower()
    if "d" not in cleaned:
        raise ValueError("missing 'd' in dice notation: %r" % text)
    count_part, sides_part = cleaned.split("d", 1)
    for char in count_part + sides_part:
        if char not in DIGITS:
            raise ValueError("bad dice notation: %r" % text)
    if not sides_part:
        raise ValueError("no side count given in %r" % text)
    count = int(count_part) if count_part else 1
    return count, int(sides_part)


def roll_pool(count, num_sides):
    """Roll `count` dice of the same kind and return the individual results."""
    if count < 1:
        raise ValueError("must roll at least one die")
    return [roll_die(num_sides) for _ in range(count)]


def tally(results):
    """Count how often each face came up."""
    counts = {}
    for value in results:
        if value not in counts:
            counts[value] = 0
        counts[value] += 1
    return counts


def describe_die(num_sides):
    """Label a die, flagging shapes outside the usual tabletop set."""
    label = "d%d" % num_sides
    if num_sides not in STANDARD_DICE:
        return label + " (non-standard)"
    return label


def format_report(notation, results):
    """Render a roll of `notation` as a short human-readable summary."""
    count, sides = parse_dice_notation(notation)
    lines = ["%s -> %s" % (describe_die(sides), ", ".join(str(r) for r in results))]
    lines.append("total: %d over %d dice" % (sum(results), count))
    counts = tally(results)
    faces = []
    for face in range(1, sides + 1):
        if face not in counts:
            continue
        faces.append("%d x%d" % (face, counts[face]))
    if faces:
        lines.append("faces: " + "; ".join(faces))
    return "\n".join(lines)


def main():
    print(roll_die(6))
    print(roll_die(20))
    for notation in ("3d6", "d20", "5d100"):
        count, sides = parse_dice_notation(notation)
        print(format_report(notation, roll_pool(count, sides)))


if __name__ == "__main__":
    main()

