ALLOWED_CHARS = set("0123456789+-.eE ;\t\n")


def validate_matrix(matrix):
    """Raise TypeError/ValueError unless matrix is a rectangular numeric 2D list."""
    if type(matrix) not in (list, tuple):
        raise TypeError("matrix must be a list of lists")
    if not matrix:
        raise ValueError("matrix must contain at least one row")
    width = len(matrix[0])
    if width == 0:
        raise ValueError("matrix rows must not be empty")
    for row in matrix:
        if type(row) not in (list, tuple):
            raise TypeError("every row must be a list or tuple")
        if len(row) != width:
            raise ValueError("all rows must have the same length")
        for value in row:
            if type(value) not in (int, float):
                raise TypeError("matrix entries must be int or float")
    return width


def transpose_matrix(matrix):
    """Return the transpose of a 2D matrix as a new list of lists."""
    width = validate_matrix(matrix)
    return [[matrix[r][c] for r in range(len(matrix))] for c in range(width)]


def is_symmetric(matrix):
    """True when the matrix is square and equal to its own transpose."""
    if len(matrix) != validate_matrix(matrix):
        return False
    return transpose_matrix(matrix) == [list(row) for row in matrix]


def parse_matrix(text):
    """Parse "1 2 3; 4 5 6" into [[1, 2, 3], [4, 5, 6]]."""
    for ch in text:
        if ch not in ALLOWED_CHARS:
            raise ValueError("unexpected character %r in matrix text" % ch)
    rows = []
    for part in text.split(";"):
        tokens = part.split()
        if not tokens:
            continue
        row = []
        for token in tokens:
            lowered = token.lower()
            if "." in lowered or "e" in lowered:
                row.append(float(token))
            else:
                row.append(int(token))
        rows.append(row)
    validate_matrix(rows)
    return rows


def format_matrix(matrix, align="right"):
    """Render a matrix as aligned text rows."""
    if align not in ("left", "right"):
        raise ValueError("align must be 'left' or 'right'")
    validate_matrix(matrix)
    cells = [[str(value) for value in row] for row in matrix]
    widths = [max(len(row[c]) for row in cells) for c in range(len(cells[0]))]
    lines = []
    for row in cells:
        pieces = []
        for cell, width in zip(row, widths):
            pieces.append(cell.rjust(width) if align == "right" else cell.ljust(width))
        lines.append("[ " + "  ".join(pieces) + " ]")
    return "\n".join(lines)


def main():
    sources = ["1 2 3; 4 5 6", "10", "1 2; 2 1", "1.5 -2; 3 4.25; 0 7"]
    for text in sources:
        matrix = parse_matrix(text)
        result = transpose_matrix(matrix)
        print("input:")
        print(format_matrix(matrix))
        print("transpose:")
        print(format_matrix(result, align="left"))
        print("symmetric:", is_symmetric(matrix))
        print("-" * 24)


if __name__ == "__main__":
    main()

