IGNORED_CHARS = " \t\n-'"


def normalize(text):
    """Lowercase the text and drop the characters that must be ignored."""
    if not isinstance(text, str):
        raise TypeError("expected a string, got %r" % (type(text).__name__,))
    cleaned = []
    for ch in text.lower():
        if ch not in IGNORED_CHARS:
            cleaned.append(ch)
    return "".join(cleaned)


def letter_counts(text):
    """Return a mapping of letter -> number of occurrences."""
    counts = {}
    for ch in text:
        if ch not in counts:
            counts[ch] = 0
        counts[ch] += 1
    return counts


def are_anagrams(str1, str2):
    """True when str1 and str2 use the same letters, ignoring case and spaces."""
    left = normalize(str1)
    right = normalize(str2)
    if len(left) != len(right):
        return False
    counts = letter_counts(left)
    for ch in right:
        if ch not in counts:
            return False
        counts[ch] -= 1
        if counts[ch] == 0:
            del counts[ch]
    return not counts


def anagram_key(word):
    """Canonical signature shared by all anagrams of a word."""
    return "".join(sorted(normalize(word)))


def group_anagrams(words):
    """Group the given words into lists of mutual anagrams."""
    groups = {}
    for word in words:
        key = anagram_key(word)
        if key not in groups:
            groups[key] = []
        if word not in groups[key]:
            groups[key].append(word)
    return groups


def format_groups(groups):
    """Render the non-trivial groups as sorted, human readable lines."""
    lines = []
    for key in sorted(groups):
        members = groups[key]
        if len(members) < 2:
            continue
        lines.append("%s: %s" % (key, ", ".join(sorted(members))))
    return lines


def main():
    pairs = [("listen", "silent"), ("hello", "world"), ("Dormitory", "dirty room")]
    for first, second in pairs:
        print("%-12s %-12s -> %s" % (first, second, are_anagrams(first, second)))

    vocabulary = ["listen", "silent", "enlist", "world", "hello", "tinsel", "below", "elbow"]
    groups = group_anagrams(vocabulary)
    report = format_groups(groups)
    if not report:
        print("no anagram groups found")
    for line in report:
        print(line)

    lonely = [w for w in vocabulary if w not in sum(
        [g for g in groups.values() if len(g) > 1], [])]
    print("without partner: %s" % (", ".join(lonely) or "none",))


if __name__ == "__main__":
    main()

