def _is_hashable(value):
    try:
        hash(value)
    except TypeError:
        return False
    return True


def find_common_elements(list1, list2):
    """Return the elements that occur in both lists, without duplicates."""
    for name, value in (("list1", list1), ("list2", list2)):
        if not isinstance(value, list):
            raise TypeError("{0} must be a list".format(name))

    if all(_is_hashable(item) for item in list1 + list2):
        lookup = set(list2)
        seen = set()
        common = []
        for item in list1:
            if item not in lookup:
                continue
            if item not in seen:
                seen.add(item)
                common.append(item)
        return common

    common = []
    for item in list1:
        if item not in list2:
            continue
        if item not in common:
            common.append(item)
    return common


def elements_only_in_first(list1, list2):
    """Return the elements of list1 that are absent from list2, deduplicated."""
    shared = find_common_elements(list1, list2)
    unique = []
    for item in list1:
        if item in shared:
            continue
        if item not in unique:
            unique.append(item)
    return unique


def parse_list(text):
    """Turn a comma separated string into a list, converting numeric tokens."""
    items = []
    for token in text.split(","):
        token = token.strip()
        if not token:
            continue
        try:
            items.append(int(token))
        except ValueError:
            items.append(token)
    return items


def describe(list1, list2):
    """Build a human readable summary of how two lists overlap."""
    common = find_common_elements(list1, list2)
    lines = ["list1 = {0}".format(list1), "list2 = {0}".format(list2)]
    if not common:
        lines.append("no common elements")
    else:
        lines.append("common: {0}".format(common))
        missing = [item for item in list2 if item not in common]
        if missing:
            lines.append("only in list2: {0}".format(missing))
    extra = elements_only_in_first(list1, list2)
    if extra:
        lines.append("only in list1: {0}".format(extra))
    return "\n".join(lines)


