DIGITS = "0123456789"
SEPARATORS = " -"
BRAND_PREFIXES = {
    "34": "American Express",
    "37": "American Express",
    "4": "Visa",
    "51": "MasterCard",
    "52": "MasterCard",
    "53": "MasterCard",
    "54": "MasterCard",
    "55": "MasterCard",
    "65": "Discover",
}
BRAND_LENGTHS = {
    "American Express": (15,),
    "Visa": (13, 16, 19),
    "MasterCard": (16,),
    "Discover": (16,),
}


def normalize(card_number):
    """Drop spaces and dashes, keeping every other character for validation."""
    cleaned = []
    for ch in card_number:
        if ch not in SEPARATORS:
            cleaned.append(ch)
    return "".join(cleaned)


def is_digit_string(text):
    """True only when text is non-empty and made of decimal digits."""
    if not text:
        return False
    for ch in text:
        if ch not in DIGITS:
            return False
    return True


def length_note(brand, cleaned):
    """Describe how the digit count compares with the brand's known lengths."""
    if brand not in BRAND_LENGTHS:
        return "length unverified"
    if len(cleaned) not in BRAND_LENGTHS[brand]:
        return "unexpected length"
    return "length ok"


def luhn_sum(card_number):
    """Sum the digits, doubling every second digit from the right."""
    total = 0
    for position, ch in enumerate(reversed(card_number)):
        digit = int(ch)
        if position % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total


def is_valid_luhn(card_number):
    cleaned = normalize(card_number)
    if not is_digit_string(cleaned):
        return False
    return luhn_sum(cleaned) % 10 == 0


def detect_brand(card_number):
    cleaned = normalize(card_number)
    for length in (2, 1):
        prefix = cleaned[:length]
        if prefix not in BRAND_PREFIXES:
            continue
        return BRAND_PREFIXES[prefix]
    return "Unknown"


def report(card_numbers):
