import math

NUMERIC_TYPES = (int, float)
UNITS = {"m": 1.0, "km": 0.001, "cm": 100.0}
STYLES = {"plain": "{value:.3f} {unit}", "verbose": "distance = {value:.3f} {unit}"}


def _as_float(value, name):
    if type(value) not in NUMERIC_TYPES:
        try:
            value = float(value)
        except (TypeError, ValueError):
            raise TypeError("coordinate %s must be a number, got %r" % (name, value))
    return float(value)


def euclidean_distance_2d(x1, y1, x2, y2):
    x1 = _as_float(x1, "x1")
    y1 = _as_float(y1, "y1")
    x2 = _as_float(x2, "x2")
    y2 = _as_float(y2, "y2")
    return math.hypot(x2 - x1, y2 - y1)


def parse_point(text):
    text = text.strip().lstrip("(").rstrip(")")
    if "," not in text:
        raise ValueError("point %r must contain a comma separator" % text)
    raw_x, raw_y = text.split(",", 1)
    return _as_float(raw_x.strip(), "x"), _as_float(raw_y.strip(), "y")


def parse_points(lines):
    points = []
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        points.append(parse_point(stripped))
    return points


def unique_points(points):
    seen = []
    for point in points:
        if point not in seen:
            seen.append(point)
    return seen


def path_length(points, unit="m"):
    if unit not in UNITS:
        raise ValueError("unknown unit %r" % unit)
    total = 0.0
    for (x1, y1), (x2, y2) in zip(points, points[1:]):
        total += euclidean_distance_2d(x1, y1, x2, y2)
    return total * UNITS[unit]


def format_distance(value, unit="m", style="plain"):
    if style not in STYLES:
        raise ValueError("unknown style %r" % style)
    return STYLES[style].format(value=value, unit=unit)


def main():
    raw = ["# route", "0, 0", "3,4", "(3, 4)", "3, 8", ""]
    points = parse_points(raw)
    route = unique_points(points)
    print("points:", route)
    for (x1, y1), (x2, y2) in zip(route, route[1:]):
        leg = euclidean_distance_2d(x1, y1, x2, y2)
        print("leg", (x1, y1), "->", (x2, y2), format_distance(leg))
    print(format_distance(path_length(route, "m"), "m", "verbose"))
    print(format_distance(path_length(route, "km"), "km", "verbose"))
    print(euclidean_distance_2d(0, 0, 3, 4), euclidean_distance_2d(1, 1, 1, 1))


if __name__ == "__main__":
    main()

