import sys

DIGITS = "0123456789"
KNOWN_FLAGS = ("--quiet", "--unique")


def parse_limit(text):
    """Turn a command line token into a non-negative int limit."""
    token = text.strip()
    if not token:
        raise ValueError("empty limit")
    for ch in token:
        if ch not in DIGITS:
            raise ValueError("limit must be a non-negative integer: %r" % text)
    return int(token)


def parse_args(args):
    flags = []
    positional = []
    for arg in args:
        if arg.startswith("-"):
            if arg not in KNOWN_FLAGS:
                raise ValueError("unknown option: %s" % arg)
            if arg not in flags:
                flags.append(arg)
        else:
            positional.append(arg)
    return flags, positional


def fibonacci_sequence(n):
    """Fibonacci numbers strictly below n, starting with 0 and 1."""
    seq = []
    current, nxt = 0, 1
    while current < n:
        seq.append(current)
        current, nxt = nxt, current + nxt
    return seq


def unique_terms(seq):
    out = []
    for value in seq:
        if value not in out:
            out.append(value)
    return out


def missing_terms(values, seq):
    return [value for value in values if value not in seq]


def parity_summary(seq):
    evens = sum(1 for value in seq if value % 2 == 0)
    return evens, len(seq) - evens


def format_report(limit, seq, flags):
    shown = unique_terms(seq) if "--unique" in flags else seq
    lines = ["Fibonacci numbers below %d: %s" % (limit, shown)]
    if "--quiet" not in flags:
        evens, odds = parity_summary(seq)
        lines.append("count=%d evens=%d odds=%d" % (len(seq), evens, odds))
        if seq:
            lines.append("largest term: %d" % seq[-1])
    return "\n".join(lines)


def main(argv):
    try:
        flags, positional = parse_args(argv[1:])
        limit = parse_limit(positional[0]) if positional else 10
        probes = [parse_limit(token) for token in positional[1:]]
    except ValueError as err:
        print("error: %s" % err)
        return 1
    seq = fibonacci_sequence(limit)
    print(format_report(limit, seq, flags))
    absent = missing_terms(probes, seq)
    if absent:
        print("not Fibonacci terms below %d: %s" % (limit, absent))
    elif probes:
        print("all probed values are Fibonacci terms below %d" % limit)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

