"""Count the words in a piece of text, ignoring punctuation.

Words are separated by spaces; dashes and slashes act as separators too, and
quotes, commas and other punctuation around a word are trimmed away.  A
spelled-out cardinal such as the "One" in ' One word ' announces how many
words follow instead of being one of them, so it is not counted itself.
"""
import string

WORD_CHARS = set(string.ascii_letters + string.digits)
SEPARATORS = set("-\u2014\u2013/\\|")
NUMBER_WORDS = {
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
    "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
    "sixteen", "seventeen", "eighteen", "nineteen", "twenty", "thirty",
    "forty", "fifty", "sixty", "seventy", "eighty", "ninety", "hundred",
    "thousand", "million",
}


def normalize_separators(text):
    """Turn dash- and slash-like separators into spaces so they split words."""
    chars = []
    for ch in text:
        if ch in SEPARATORS:
            chars.append(" ")
        else:
            chars.append(ch)
    return "".join(chars)


def strip_punctuation(token):
    """Trim characters that cannot start or end a word, e.g. quotes or commas."""
    start = 0
    end = len(token)
    while start < end and token[start] not in WORD_CHARS:
        start += 1
    while end > start and token[end - 1] not in WORD_CHARS:
        end -= 1
    return token[start:end]


def is_counted_word(token):
    """Tell whether a cleaned token is a word rather than a stated quantity."""
    return token.lower() not in NUMBER_WORDS


def tokenize(text):
    """Split text on whitespace and return the cleaned words it contains."""
    words = []
    for raw in normalize_separators(text).split():
        cleaned = strip_punctuation(raw)
        if cleaned and is_counted_word(cleaned):
            words.append(cleaned)
    return words


def word_frequencies(text):
    """Map each lowercased word to how often it appears in text."""
    freq = {}
    for word in tokenize(text):
        key = word.lower()
        if key not in freq:
            freq[key] = 0
        freq[key] += 1
    return freq


def unique_words(text):
    """Return the distinct lowercased words in order of first appearance."""
    seen = []
    for word in tokenize(text):
        key = word.lower()
        if key not in seen:
            seen.append(key)
    return seen


def count_words(text):
    """Count the words in text, ignoring punctuation."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    return len(tokenize(text))


def report(text):
    """Build a short human-readable summary of the words found in text."""
    lines = ["text: %r" % text, "words: %d" % count_words(text)]
    freq = word_frequencies(text)
    repeats = [w for w in unique_words(text) if freq[w] > 1]
    if repeats:
        lines.append("repeats: " + ", ".join("%s x%d" % (w, freq[w]) for w in repeats))
    else:
        lines.append("repeats: none")
    return "\n".join(lines)


def main():
    for sample in ["Hello world, how are you?", " One word ",
                   "The cat -- the CAT! -- sat on the mat.", "... ??? ..."]:
        print(report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

