def validate_values(input_dict):
    """Ensure every value can be compared against a numeric threshold."""
    for key, value in input_dict.items():
        if type(value) not in (int, float):
            raise TypeError("value for key %r is not numeric: %r" % (key, value))


def filter_dict_by_value(input_dict, threshold):
    """Return the pairs of input_dict whose value is greater than threshold."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict")
    if type(threshold) not in (int, float):
        raise TypeError("threshold must be an int or a float")
    validate_values(input_dict)
    return {key: value for key, value in input_dict.items() if value > threshold}


