WEIGHT_UNITS = {"kg": 1.0, "lb": 0.45359237, "st": 6.35029318}
HEIGHT_UNITS = {"m": 1.0, "cm": 0.01, "in": 0.0254, "ft": 0.3048}
COMMENT_MARKERS = "#;"

CATEGORIES = (
    (18.5, "Underweight"),
    (25.0, "Normal weight"),
    (30.0, "Overweight"),
    (float("inf"), "Obese"),
)


def to_kilograms(value, unit):
    if unit not in WEIGHT_UNITS:
        raise ValueError("unsupported weight unit: %s" % unit)
    return value * WEIGHT_UNITS[unit]


def to_meters(value, unit):
    if unit not in HEIGHT_UNITS:
        raise ValueError("unsupported height unit: %s" % unit)
    return value * HEIGHT_UNITS[unit]


def parse_quantity(token, default_unit):
    parts = token.split()
    if len(parts) not in (1, 2):
        raise ValueError("expected '<number> [unit]', got %r" % token)
    if len(parts) == 1:
        return float(parts[0]), default_unit
    return float(parts[0]), parts[1]


def parse_record(line):
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 3:
        raise ValueError("expected 'name, weight, height' in %r" % line)
    name, raw_weight, raw_height = fields
    if not name:
        raise ValueError("record is missing a name")
    weight, weight_unit = parse_quantity(raw_weight, "kg")
    height, height_unit = parse_quantity(raw_height, "m")
    return name, to_kilograms(weight, weight_unit), to_meters(height, height_unit)


def calculate_bmi(weight_kg, height_m):
    if weight_kg <= 0 or height_m <= 0:
        raise ValueError("weight and height must be positive")
    return round(weight_kg / (height_m * height_m), 2)


def classify_bmi(bmi):
    for upper, label in CATEGORIES:
        if bmi < upper:
            return label
    raise ValueError("bmi out of range: %r" % bmi)


def build_report(lines):
    rows = []
    seen = set()
    for line in lines:
        text = line.strip()
        if text and text[0] not in COMMENT_MARKERS:
            name, weight_kg, height_m = parse_record(text)
            if name not in seen:
                seen.add(name)
                bmi = calculate_bmi(weight_kg, height_m)
                rows.append((name, bmi, classify_bmi(bmi)))
    return rows


def main():
    data = [
        "# name, weight, height",
        "Alice, 70 kg, 1.75 m",
        "Bob, 90, 1.80",
        "Carol, 132 lb, 64 in",
        "Alice, 71 kg, 1.75 m",
        "Dan, 11 st, 5.9 ft",
    ]
    grouped = {}
    for name, bmi, label in build_report(data):
        print("%-8s %6.2f  %s" % (name, bmi, label))
        if label not in grouped:
            grouped[label] = []
        grouped[label].append(name)
    print("-" * 30)
    for label, names in grouped.items():
        print("%-14s %d  %s" % (label, len(names), ", ".join(names)))


if __name__ == "__main__":
    main()

