import string

ALPHABET_LOWER = string.ascii_lowercase
ALPHABET_UPPER = string.ascii_uppercase


def shift_char(char, shift):
    """Shift a single character; non-alphabetic characters pass through."""
    if char not in ALPHABET_LOWER:
        if char not in ALPHABET_UPPER:
            return char
        alphabet = ALPHABET_UPPER
    else:
        alphabet = ALPHABET_LOWER
    return alphabet[(alphabet.index(char) + shift) % 26]


def encrypt_shift(text, shift):
    """Encrypt text with a Caesar shift of `shift` positions."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if isinstance(shift, bool) or not isinstance(shift, int):
        raise TypeError("shift must be an integer")
    return "".join(shift_char(char, shift) for char in text)


def decrypt_shift(text, shift):
    """Undo an encryption performed with the same shift."""
    return encrypt_shift(text, -shift)


def parse_shift(raw):
    """Turn a user-supplied shift into an int, accepting a leading sign."""
    cleaned = raw.strip()
    if not cleaned:
        raise ValueError("shift must not be empty")
    body = cleaned[1:] if cleaned[0] in "+-" else cleaned
    for digit in body:
        if digit not in string.digits:
            raise ValueError("not a valid integer: %r" % raw)
    return int(cleaned)


def parse_spec(raw):
    """Split a 'text|shift' sample specification into text and shift."""
    if "|" not in raw:
        raise ValueError("sample must look like 'text|shift': %r" % raw)
    text, raw_shift = raw.split("|", 1)
    return text, parse_shift(raw_shift)


def letter_summary(text):
    """Report which distinct letters appear and how many chars are untouched."""
    letters = []
    untouched = 0
    for char in text:
        upper = char.upper()
        if upper in ALPHABET_UPPER:
            if upper not in letters:
                letters.append(upper)
        else:
            untouched += 1
    return "".join(sorted(letters)), untouched


def format_report(text, shift):
    """Build a multi-line report about encrypting `text` by `shift`."""
    cipher = encrypt_shift(text, shift)
    letters, untouched = letter_summary(text)
    lines = [
        "plain : %s" % text,
        "shift : %d" % shift,
        "cipher: %s" % cipher,
        "letters used: %s" % (letters or "(none)"),
        "unchanged characters: %d" % untouched,
    ]
    if decrypt_shift(cipher, shift) != text:
        lines.append("WARNING: round trip failed")
    return "\n".join(lines)


def main():
    for spec in ["abc|1", "XYZ|3", "Hello, World!|-5"]:
        text, shift = parse_spec(spec)
        print(format_report(text, shift))
        print("-" * 30)


if __name__ == "__main__":
    main()

