HEX_DIGITS = "0123456789abcdefABCDEF"
FALSEY_FLAGS = ("0", "false", "no", "")
KNOWN_PARAMS = ("name", "age", "q", "path", "debug", "flag")


def _is_hex_escape(escape):
    """Return True when escape is a two-character hexadecimal sequence."""
    if len(escape) != 2:
        return False
    for digit in escape:
        if digit not in HEX_DIGITS:
            return False
    return True


def percent_decode(text):
    """Decode %XX escapes, leaving malformed escapes untouched."""
    out = []
    i = 0
    while i < len(text):
        escape = text[i + 1:i + 3]
        if text[i] == "%" and _is_hex_escape(escape):
            out.append(chr(int(escape, 16)))
            i += 3
        else:
            out.append(text[i])
            i += 1
    return "".join(out)


def split_key_value(chunk):
    """Split one raw chunk into its key half and its value half."""
    if "=" not in chunk:
        return chunk, ""
    key, value = chunk.split("=", 1)
    return key, value


def parse_url_params(query_string):
    """Parse a URL query string into a dictionary of key-value pairs."""
    params = {}
    for chunk in query_string.strip().lstrip("?#").split("&"):
        raw_key, raw_value = split_key_value(chunk)
        key = percent_decode(raw_key)
        if not key:
            continue
        if key not in params:
            params[key] = percent_decode(raw_value)
    return params


def missing_params(params, required):
    """Return the required keys the parsed parameters do not provide."""
    return [name for name in required if name not in params]


def unknown_params(params):
    """Return the parsed keys that fall outside the recognised set."""
    return [name for name in sorted(params) if name not in KNOWN_PARAMS]


