"""Longest common prefix helpers plus a small reporting driver."""


def _validate(strings):
    """Reject inputs that are not a list of plain strings."""
    if not isinstance(strings, list):
        raise TypeError("strings must be a list of str")
    for item in strings:
        if not isinstance(item, str):
            raise TypeError("every element must be a str, got " + repr(item))


def _unique(strings):
    """Duplicates cannot change the prefix, so drop them (order preserved)."""
    kept = []
    for word in strings:
        if word not in kept:
            kept.append(word)
    return kept


def longest_common_prefix(strings):
    _validate(strings)
    words = _unique(strings)
    if not words:
        return ""
    shortest = min(words, key=len)
    for index, char in enumerate(shortest):
        for word in words:
            if word[index] != char:
                return shortest[:index]
    return shortest


def branching_characters(strings, prefix):
    """Distinct characters that follow the shared prefix."""
    branches = []
    cut = len(prefix)
    for word in strings:
        tail = word[cut:cut + 1]
        if tail and tail not in branches:
            branches.append(tail)
    return sorted(branches)


def group_by_prefix(strings, length):
    """Bucket the words by their first `length` characters."""
    groups = {}
    for word in strings:
        key = word[:length]
        if key not in groups:
            groups[key] = []
        groups[key].append(word)
    return groups


def common_letters(strings):
    """Letters shared by every word, regardless of position."""
    if not strings:
        return []
    shared = []
    for char in strings[0]:
        if char not in shared:
            if all(char in word for word in strings[1:]):
                shared.append(char)
    return sorted(shared)


def format_report(strings):
    prefix = longest_common_prefix(strings)
    lines = ["words: " + (", ".join(strings) if strings else "(none)")]
    lines.append("longest common prefix: " + repr(prefix))
    branches = branching_characters(strings, prefix)
    if branches:
        lines.append("branches after prefix: " + " ".join(branches))
    extras = [c for c in common_letters(strings) if c not in prefix]
    lines.append("shared letters outside the prefix: " + " ".join(extras))
    for key, members in sorted(group_by_prefix(strings, len(prefix) + 1).items()):
        lines.append("  [" + key + "] " + ", ".join(members))
    return "\n".join(lines)


def main():
    datasets = [
        ["flower", "flow", "flight"],
        ["dog", "racecar", "car"],
        ["interspecies", "interstellar", "interstate", "interstate"],
        ["single"],
        [],
    ]
    for data in datasets:
        print(format_report(data))
        print("-" * 40)


if __name__ == "__main__":
    main()

