NAMED_MATRICES = {
    "identity": [[1, 0], [0, 1]],
    "flip": [[0, 1], [1, 0]],
    "double": [[2, 0], [0, 2]],
}

_PRODUCT_CACHE = {}


def validate_matrix(matrix, name="matrix"):
    if not isinstance(matrix, list) or len(matrix) != 2:
        raise ValueError("%s must be a list of 2 rows" % name)
    for row in matrix:
        if not isinstance(row, list) or len(row) != 2:
            raise ValueError("%s must have rows of length 2" % name)
        for entry in row:
            if type(entry) not in (int, float):
                raise TypeError("%s contains a non-numeric entry: %r" % (name, entry))
    return matrix


def parse_matrix(text):
    if ";" not in text:
        raise ValueError("expected two rows separated by ';': %r" % text)
    rows = []
    for chunk in text.split(";"):
        numbers = []
        for token in chunk.replace(",", " ").split():
            try:
                numbers.append(int(token))
            except ValueError:
                numbers.append(float(token))
        rows.append(numbers)
    return validate_matrix(rows, "parsed matrix")


def lookup_matrix(name):
    if name not in NAMED_MATRICES:
        raise KeyError("unknown matrix name %r" % name)
    return [row[:] for row in NAMED_MATRICES[name]]


def resolve(value):
    if isinstance(value, str):
        if value in NAMED_MATRICES:
            return lookup_matrix(value)
        return parse_matrix(value)
    return validate_matrix(value)


def multiply_2x2_matrices(matrix_a, matrix_b):
    validate_matrix(matrix_a, "matrix_a")
    validate_matrix(matrix_b, "matrix_b")
    key = (tuple(map(tuple, matrix_a)), tuple(map(tuple, matrix_b)))
    if key not in _PRODUCT_CACHE:
        _PRODUCT_CACHE[key] = [
            [
                matrix_a[i][0] * matrix_b[0][j] + matrix_a[i][1] * matrix_b[1][j]
                for j in range(2)
            ]
            for i in range(2)
        ]
    return [row[:] for row in _PRODUCT_CACHE[key]]


def format_matrix(matrix, style="plain"):
    if style not in ("plain", "grid"):
        raise ValueError("unsupported style %r" % style)
    cells = [["%g" % entry for entry in row] for row in matrix]
    width = max(len(text) for row in cells for text in row)
    lines = [" ".join(text.rjust(width) for text in row) for row in cells]
    if style == "plain":
        return "\n".join(lines)
    border = "+" + "-" * (len(lines[0]) + 2) + "+"
    return "\n".join([border] + ["| %s |" % line for line in lines] + [border])


def main():
    jobs = [
        ([[1, 2], [3, 4]], [[5, 6], [7, 8]], "grid"),
        ("identity", [[10, 20], [30, 40]], "plain"),
        ("1 2; 3 4", "flip", "grid"),
    ]
    for left, right, style in jobs:
        product = multiply_2x2_matrices(resolve(left), resolve(right))
        print("%r x %r =" % (left, right))
        print(format_matrix(product, style))
        print()


if __name__ == "__main__":
    main()

