import sys

ALLOWED_CHARS = set("0123456789+-.eE")
DEFAULT_ORDER = ("example1", "example2", "parsed", "wide")


def parse_series(text):
    """Turn a comma/space separated string of numbers into a list of floats."""
    tokens = text.replace(",", " ").split()
    if not tokens:
        raise ValueError("no numbers found in input")
    values = []
    for token in tokens:
        for ch in token:
            if ch not in ALLOWED_CHARS:
                raise ValueError("illegal character %r in token %r" % (ch, token))
        values.append(float(token))
    return values


def calculate_sma(data, window_size):
    """Simple moving average of `data` over a sliding window of `window_size`."""
    if not isinstance(window_size, int) or isinstance(window_size, bool):
        raise TypeError("window_size must be an int")
    if window_size < 1:
        raise ValueError("window_size must be positive")
    for value in data:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("data must contain only ints or floats")
    if window_size > len(data):
        return []
    window_total = float(sum(data[:window_size]))
    averages = [window_total / window_size]
    for index in range(window_size, len(data)):
        window_total += data[index] - data[index - window_size]
        averages.append(window_total / window_size)
    return averages


def select_names(argv, datasets):
    """Resolve the dataset names to report on, skipping repeated requests."""
    selected = []
    for name in argv:
        if name not in datasets:
            raise SystemExit("unknown dataset %r" % name)
        if name not in selected:
            selected.append(name)
    return selected or list(DEFAULT_ORDER)


def run_dataset(datasets, windows, name):
    if name not in windows:
        raise KeyError("no window size configured for dataset %r" % name)
    return calculate_sma(datasets[name], windows[name])


def describe(averages):
    """Basic statistics about a series of moving averages."""
    if not averages:
        return {}
    return {
        "count": len(averages),
        "first": averages[0],
        "last": averages[-1],
        "min": min(averages),
        "max": max(averages),
    }


def trend(stats):
    if "first" not in stats:
        return "undefined"
    if stats["last"] > stats["first"]:
        return "rising"
    if stats["last"] < stats["first"]:
        return "falling"
    return "flat"


def format_report(label, averages, width=8):
    cells = ["%.2f" % value for value in averages]
    body = "".join(cell.rjust(width) for cell in cells)
    if not cells:
        body = "(window larger than data)"
    return "%-10s %s | trend: %s" % (label + ":", body, trend(describe(averages)))


def main():
    datasets = {
        "example1": [1, 2, 3, 4, 5],
        "example2": [10, 20, 30, 40],
        "parsed": parse_series("3, 7 11, 4.5 9 2"),
        "wide": [1, 2],
    }
    windows = {"example1": 3, "example2": 2, "parsed": 3, "wide": 5}
    for name in select_names(sys.argv[1:], datasets):
        print(format_report(name, run_dataset(datasets, windows, name)))


if __name__ == "__main__":
    main()

