        averages.append(window_total / window_size)
    return averages


def select_names(argv, datasets):
    """Resolve the dataset names to report on, skipping repeated requests."""
    selected = []
    for name in argv:
        if not name in datasets:
            raise SystemExit("unknown dataset %r" % name)
        if not name in selected:
            selected.append(name)
    return selected or list(DEFAULT_ORDER)


def run_dataset(datasets, windows, name):
    if not name in windows:
        raise KeyError("no window size configured for dataset %r" % name)
    return calculate_sma(datasets[name], windows[name])


def describe(averages):
    """Basic statistics about a series of moving averages."""
    if not averages:
        return {}
    return {
        "count": len(averages),
        "first": averages[0],
        "last": averages[-1],
        "min": min(averages),
        "max": max(averages),
    }


def trend(stats):
    if not "first" in stats:
        return "undefined"
    if stats["last"] > stats["first"]:
        return "rising"
    if stats["last"] < stats["first"]:
        return "falling"
    return "flat"


def format_report(label, averages, width=8):
    cells = ["%.2f" % value for value in averages]
    body = "".join(cell.rjust(width) for cell in cells)
    if not cells:
        body = "(window larger than data)"
    return "%-10s %s | trend: %s" % (label + ":", body, trend(describe(averages)))


def main():
    datasets = {
        "example1": [1, 2, 3, 4, 5],
        "example2": [10, 20, 30, 40],
        "parsed": parse_series("3, 7 11, 4.5 9 2"),
        "wide": [1, 2],
    }
    windows = {"example1": 3, "example2": 2, "parsed": 3, "wide": 5}
    for name in select_names(sys.argv[1:], datasets):
        print(format_report(name, run_dataset(datasets, windows, name)))


if __name__ == "__main__":
    main()

