"""Roman numeral parsing: validation, conversion and a small stdin report."""
import sys

ROMAN_VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
SUBTRACTIVE_PAIRS = {'IV', 'IX', 'XL', 'XC', 'CD', 'CM'}
REPEATABLE = {'I', 'X', 'C', 'M'}
SEPARATORS = ' \t\r\n,;'
CANONICAL_PAIRS = ((1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'),
                   (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'),
                   (5, 'V'), (4, 'IV'), (1, 'I'))


def tokenize(text):
    tokens, current = [], ''
    for ch in text:
        if ch not in SEPARATORS:
            current += ch
        elif current:
            tokens.append(current)
            current = ''
    if current:
        tokens.append(current)
    return tokens


def validate(roman):
    if not roman:
        raise ValueError('empty numeral')
    previous, run_length = '', 0
    for index, ch in enumerate(roman):
        if ch not in ROMAN_VALUES:
            raise ValueError('invalid character %r' % ch)
        run_length = run_length + 1 if ch == previous else 1
        previous = ch
        if ch not in REPEATABLE and run_length > 1:
            raise ValueError('%r cannot be repeated' % ch)
        if run_length > 3:
            raise ValueError('%r repeated more than three times' % ch)
        nxt = roman[index + 1:index + 2]
        if nxt and ROMAN_VALUES[ch] < ROMAN_VALUES.get(nxt, 0):
            if ch + nxt not in SUBTRACTIVE_PAIRS:
                raise ValueError('invalid subtraction %r' % (ch + nxt))


def convert_all(tokens):
    cache, report = {}, []
    for token in tokens:
        if token not in cache:
            try:
                cache[token] = roman_to_int(token)
            except ValueError as exc:
                cache[token] = 'error: %s' % exc
        report.append((token, cache[token]))
    return report


def roman_to_int(roman_numeral):
    """Convert a Roman numeral between I and MMMCMXCIX to its integer value."""
    roman = roman_numeral.strip().upper()
    validate(roman)
    total = 0
    for index, ch in enumerate(roman):
        value = ROMAN_VALUES[ch]
        nxt = roman[index + 1:index + 2]
        if nxt and value < ROMAN_VALUES[nxt]:
            total -= value
        else:
            total += value
    if int_to_roman(total) != roman:
        raise ValueError('non-canonical numeral %r' % roman)
    return total


def int_to_roman(number):
    if not 1 <= number <= 3999:
        raise ValueError('out of range: %d' % number)
    text = ''
    for value, symbol in CANONICAL_PAIRS:
        count, number = divmod(number, value)
        text += symbol * count
    return text


def main():
    for token, outcome in convert_all(tokenize(sys.stdin.read())):
        print('%-12s %s' % (token, outcome))


if __name__ == '__main__':
    main()

