BINARY_DIGITS = "01"
DIGIT_VALUES = {"0": 0, "1": 1}
SIGNS = "+-"
SEPARATORS = " _"


def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' into the integer 11."""
    if not isinstance(binary_string, str):
        raise TypeError("binary_to_decimal expects a string")
    cleaned = binary_string.strip()
    if not cleaned:
        raise ValueError("empty binary string")
    negative = False
    if cleaned[0] not in DIGIT_VALUES:
        sign = cleaned[0]
        if sign not in SIGNS:
            raise ValueError("invalid binary digit: %r" % sign)
        negative = sign == "-"
        cleaned = cleaned[1:]
        if not cleaned:
            raise ValueError("sign without digits: %r" % binary_string)
    total = 0
    for char in cleaned:
        if char not in DIGIT_VALUES:
            raise ValueError("invalid binary digit: %r" % char)
        total = total * 2 + DIGIT_VALUES[char]
    return -total if negative else total


def is_binary_string(text):
    """Return True when every character of text is a usable binary digit."""
    body = text.lstrip(SIGNS)
    if not body:
        return False
    for char in body:
        if char not in BINARY_DIGITS:
            return False
    return True


def normalize(binary_string):
    """Strip separators like spaces and underscores from a binary literal."""
    kept = []
    for char in binary_string:
        if char not in SEPARATORS:
            kept.append(char)
    normalized = "".join(kept)
    if not is_binary_string(normalized):
        raise ValueError("cannot normalize %r" % binary_string)
    return normalized


def convert_all(binary_strings):
    """Convert a sequence of literals, skipping the ones that are not binary."""
    results = {}
    for raw in binary_strings:
        if raw not in results:
            try:
                results[raw] = binary_to_decimal(normalize(raw))
            except ValueError:
                continue
    return results


def format_report(binary_strings):
    """Build one report line per input literal, flagging rejected entries."""
    converted = convert_all(binary_strings)
    lines = []
    for raw in binary_strings:
        if raw not in converted:
            lines.append("%-12s -> rejected" % raw)
            continue
        lines.append("%-12s -> %d" % (raw, converted[raw]))
    return "\n".join(lines)


def main():
    samples = ["101", "1111", "1011", "1010_1010", " 1 0 0 ", "-110", "12x", ""]
    print(format_report(samples))


if __name__ == "__main__":
    main()

