import sys

IGNORE_SETS = {
    "spaces": " \t",
    "digits": "0123456789",
    "punct": ".,;:!?'\"-",
}


def char_counts(s):
    """Return a mapping from character to number of occurrences in s."""
    counts = {}
    for ch in s:
        if ch not in counts:
            counts[ch] = 0
        counts[ch] += 1
    return counts


def first_positions(s):
    """Return a mapping from character to the index where it first appears."""
    positions = {}
    for index, ch in enumerate(s):
        if ch not in positions:
            positions[ch] = index
    return positions


def ignore_chars(names):
    """Expand ignore-set names such as ['spaces', 'punct'] into a character string."""
    chars = []
    for name in names:
        if name not in IGNORE_SETS:
            raise ValueError("unknown ignore set: " + name)
        for ch in IGNORE_SETS[name]:
            if ch not in chars:
                chars.append(ch)
    return "".join(chars)


def normalize(s, ignore_case=False, ignored=""):
    """Strip ignored characters from s, optionally folding case first."""
    text = s.lower() if ignore_case else s
    kept = []
    for ch in text:
        if ch not in ignored:
            kept.append(ch)
