from collections import OrderedDict

SUPPORTED_KEY_TYPES = ("str", "int", "float", "bool", "tuple")
NUMERIC_TYPES = ("int", "float", "bool")


def _key_family(key):
    """Return the comparison family of a key, rejecting unorderable types."""
    name = type(key).__name__
    if name not in SUPPORTED_KEY_TYPES:
        raise TypeError("unsupported key type: %s" % name)
    if name not in NUMERIC_TYPES:
        return name
    return "number"


def _check_keys_sortable(input_dict):
    """Raise TypeError unless all keys belong to a single comparison family."""
    families = sorted({_key_family(key) for key in input_dict})
    if len(families) > 1:
        raise TypeError("keys of mixed kinds cannot be ordered: %s" % families)


def sort_dict_by_key(input_dict):
    """Return a new OrderedDict holding the items of input_dict, keys ascending."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict")
    _check_keys_sortable(input_dict)
    return OrderedDict((key, input_dict[key]) for key in sorted(input_dict))


def merge_sorted(*dicts):
    """Merge several dicts, keeping the first value seen for a key, then sort."""
    merged = {}
    for source in dicts:
        if not isinstance(source, dict):
            raise TypeError("merge_sorted accepts dicts only")
        for key, value in source.items():
            if key not in merged:
                merged[key] = value
    return sort_dict_by_key(merged)


def select_sorted(input_dict, keys):
    """Sorted view of input_dict restricted to keys; missing keys are reported."""
    absent = [key for key in keys if key not in input_dict]
    if absent:
        raise KeyError("missing keys: %s" % absent)
    wanted = set(keys)
    return sort_dict_by_key({k: v for k, v in input_dict.items() if k in wanted})


def describe_order(ordered, expected_keys):
    """Compare the produced key order with an expected sequence of keys."""
    actual = list(ordered)
    extra = [key for key in actual if key not in expected_keys]
    missing = [key for key in expected_keys if key not in actual]
    if extra or missing:
        return "key mismatch: extra=%s missing=%s" % (extra, missing)
    if actual != list(expected_keys):
        return "order mismatch: %s != %s" % (actual, list(expected_keys))
    return "order ok"


def format_dict(ordered):
    """Render an ordered mapping as 'key=value' pairs joined by commas."""
    return ", ".join("%r=%r" % pair for pair in ordered.items())


def main():
    first = sort_dict_by_key({'b': 2, 'a': 1, 'c': 3})
    print(format_dict(first))
    print(describe_order(first, ['a', 'b', 'c']))

    second = sort_dict_by_key({'z': 26, 'y': 25})
    print(format_dict(second))
    print(describe_order(second, ['y', 'z']))

    numbers = sort_dict_by_key({10: 'ten', 2: 'two', 7: 'seven'})
    print(format_dict(numbers))

    combined = merge_sorted({'d': 4, 'a': 1}, {'a': 99, 'c': 3})
    print(format_dict(combined))
    print(format_dict(select_sorted(combined, ['c', 'a'])))

    for bad in ({'a': 1, 2: 'two'}, [('a', 1)]):
        try:
            sort_dict_by_key(bad)
        except TypeError as exc:
            print("rejected: %s" % exc)

    try:
        select_sorted(first, ['a', 'q'])
    except KeyError as exc:
        print("rejected: %s" % exc)


if __name__ == "__main__":
