"""Filter strings by minimum length, then deduplicate and report them."""

import string

ALLOWED_FORMATS = ("plain", "bullets", "csv", "grouped")


def unique_preserving_order(strings):
    """Drop case-insensitive repeats, keeping the first appearance of each."""
    seen = set()
    result = []
    for text in strings:
        key = text.casefold()
        if key not in seen:
            seen.add(key)
            result.append(text)
    return result


def quote_csv_field(text):
    """Quote a field only when it would otherwise break the CSV line."""
    if "," not in text:
        return text
    return '"%s"' % text.replace('"', '""')


def group_by_initial(strings):
    """Bucket strings by first letter, filing non-letter starts under '#'."""
    groups = {}
    for text in strings:
        initial = text[:1].upper()
        if initial not in string.ascii_uppercase:
            initial = "#"
        if initial not in groups:
            groups[initial] = []
        groups[initial].append(text)
    return groups


def format_report(strings, style="plain"):
    """Render the kept strings in one of the supported styles."""
    if style not in ALLOWED_FORMATS:
        raise ValueError("unknown style: %r" % (style,))
    if not strings:
        return "(no matches)"
    if style == "bullets":
        return "\n".join(" - " + text for text in strings)
    if style == "csv":
        return ",".join(quote_csv_field(text) for text in strings)
    if style == "grouped":
        groups = group_by_initial(strings)
        lines = []
        for initial in sorted(groups):
            lines.append("%s: %s" % (initial, ", ".join(groups[initial])))
        return "\n".join(lines)
    return "\n".join(strings)


def filter_by_length(string_list, min_length):
    """Return the items of string_list whose length exceeds min_length."""
    if not isinstance(min_length, int) or isinstance(min_length, bool):
        raise TypeError("min_length must be an int")
    result = []
    for item in string_list:
        if not isinstance(item, str):
            raise TypeError("string_list must hold only strings, got %r" % (item,))
        if len(item) > min_length:
            result.append(item)
    return result


def summarize(raw_items, min_length, style="plain"):
    """Full pipeline: trim blank-padded input, filter, deduplicate, render."""
    trimmed = (str(raw).strip() for raw in raw_items)
    candidates = [text for text in trimmed if text]
    kept = filter_by_length(candidates, min_length)
    return format_report(unique_preserving_order(kept), style)


def main():
    print(filter_by_length(['apple', 'cat', 'banana'], 4))
    print(filter_by_length(['a', 'b', 'c'], 2))
    words = ['  apple ', 'cat', 'banana', 'APPLE', '', 'kiwi, fresh', '42nd street']
    for style in ALLOWED_FORMATS:
        print("[%s]" % style)
        print(summarize(words, 3, style))


if __name__ == "__main__":
    main()

