DIGITS = frozenset("0123456789")
SIGNS = "+-"
CATEGORIES = ("even", "odd")
DEFAULT_TOKENS = "4 7 -12 0 4 13 100 2x -3 +8"


def parse_int(token):
    """Convert a textual token into an int, rejecting anything malformed."""
    text = token.strip()
    if not text:
        raise ValueError("empty token")
    if text[0] in SIGNS:
        body = text[1:]
    else:
        body = text
    if not body:
        raise ValueError("token %r has a sign but no digits" % token)
    for ch in body:
        if ch not in DIGITS:
            raise ValueError("token %r contains the invalid character %r" % (token, ch))
    return int(text)


def split_options(argv):
    """Separate --even/--odd selectors from the numeric tokens on a command line."""
    wanted = []
    tokens = []
    for arg in argv:
        if arg.startswith("--"):
            name = arg[2:]
            if name not in CATEGORIES:
                raise SystemExit("unknown option %r" % arg)
            wanted.append(name)
        else:
            tokens.append(arg)
    return wanted or list(CATEGORIES), tokens


def is_even(number):
    """Return True when number is an even integer."""
    if not isinstance(number, int) or isinstance(number, bool):
