            current = ""
    if current:
        tokens.append(current)
    return tokens


def parse_token(token):
    """Convert a token of decimal digits into an int."""
    for char in token:
        if char not in DIGITS:
            raise ValueError("not a positive integer literal: %r" % token)
    return int(token)


def is_data_line(line):
    """True for lines holding data rather than blanks or comments."""
    return bool(line) and line[0] not in COMMENT_PREFIXES


def validate_numbers(numbers):
    """Return `numbers` as a list, rejecting anything but >=4 positive ints."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of integers")
    if len(numbers) < 4:
        raise ValueError("numbers must contain at least four values")
    for value in numbers:
        if type(value) not in (int,):
            raise TypeError("all values must be plain integers, got %r" % (value,))
        if value <= 0:
            raise ValueError("all values must be positive, got %d" % value)
    return list(numbers)


def sum_two_smallest(numbers):
    """Return the sum of the two smallest positive numbers in `numbers`."""
    values = validate_numbers(numbers)
    smallest = None
    second = None
    for value in values:
        if smallest is None or value < smallest:
            smallest, second = value, smallest
        elif second is None or value < second:
            second = value
    return smallest + second


