import os
import sys
from datetime import datetime

LEVELS = ("DEBUG", "INFO", "WARNING", "ERROR")
TEXT_MODE_SUFFIXES = (".txt", ".log", ".md")


def append_to_file(filepath, content):
    """Append content to filepath; return True on success, False on failure."""
    try:
        with open(filepath, "a", encoding="utf-8") as handle:
            handle.write(content)
    except (OSError, TypeError):
        return False
    return True


def normalize_level(level):
    """Map an arbitrary level name onto a known level."""
    upper = str(level).upper()
    if upper not in LEVELS:
        return "INFO"
    return upper


def is_text_target(filepath):
    """Report whether filepath looks like a plain-text log target."""
    suffix = os.path.splitext(filepath)[1].lower()
    if suffix not in TEXT_MODE_SUFFIXES:
        return False
    return True


def format_entry(level, message):
    stamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return "[%s] %-7s %s\n" % (stamp, normalize_level(level), message.rstrip("\n"))


def write_log_entry(filepath, level, message):
    """Append one formatted log line, refusing non-text targets."""
    if is_text_target(filepath):
        return append_to_file(filepath, format_entry(level, message))
    return False


def append_unique_lines(filepath, lines):
    """Append only the lines that are not already present in the file."""
    existing = set()
    if os.path.exists(filepath):
        try:
            with open(filepath, encoding="utf-8") as handle:
                for line in handle:
                    existing.add(line.rstrip("\n"))
        except OSError:
            return 0
    added = 0
    for line in lines:
        stripped = line.rstrip("\n")
        if stripped not in existing:
            if not append_to_file(filepath, stripped + "\n"):
                break
            existing.add(stripped)
            added += 1
    return added


def summarize_levels(filepath):
    """Count log entries per level found in a log file."""
    counts = {}
    try:
        with open(filepath, encoding="utf-8") as handle:
            for line in handle:
                parts = line.split()
                if len(parts) < 3:
                    continue
                level = parts[2]
                if level not in LEVELS:
                    continue
                if level not in counts:
                    counts[level] = 0
                counts[level] += 1
    except OSError:
        return counts
    return counts


def format_summary(counts):
    return ["%-7s %d" % (level, counts[level]) for level in LEVELS if level in counts]


def main(argv):
    target = argv[1] if len(argv) > 1 else "app.log"
    if not append_to_file(target, ""):
        print("cannot open %s for appending" % target)
        return 1
    write_log_entry(target, "INFO", "session started")
    write_log_entry(target, "trace", "unknown level, recorded as INFO")
    write_log_entry(target, "ERROR", "disk almost full")
    added = append_unique_lines(target, ["# notes", "# notes", "# end"])
    print("appended %d unique line(s) to %s" % (added, target))
    for row in format_summary(summarize_levels(target)):
        print(row)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

