import sys
from datetime import date

MONTH_NAMES = {
    1: "January", 2: "February", 3: "March", 4: "April",
    5: "May", 6: "June", 7: "July", 8: "August",
    9: "September", 10: "October", 11: "November", 12: "December",
}

DAYS_IN_MONTH = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
                 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}

SUFFIXES = {1: "st", 2: "nd", 3: "rd"}

SEPARATORS = "-/."

ALLOWED_CHARS = "0123456789" + SEPARATORS


def ordinal(day):
    if day % 100 not in (11, 12, 13):
        return "%d%s" % (day, SUFFIXES.get(day % 10, "th"))
    return "%dth" % day


def is_leap(year):
    if year % 4 != 0:
        return False
    if year % 100 != 0:
        return True
    return year % 400 == 0


def days_in_month(year, month):
    if month == 2 and is_leap(year):
        return 29
    return DAYS_IN_MONTH[month]


def parse_date(text):
    text = text.strip()
    for ch in text:
        if ch not in ALLOWED_CHARS:
            raise ValueError("unexpected character %r in %r" % (ch, text))
    for sep in SEPARATORS:
        text = text.replace(sep, "-")
    parts = text.split("-")
    if len(parts) != 3 or not all(parts):
        raise ValueError("expected a date formatted as YYYY-MM-DD")
    return tuple(int(part) for part in parts)


def validate(year, month, day):
    if year not in range(date.min.year, date.max.year + 1):
        raise ValueError("year %d is outside the supported range" % year)
    if month not in MONTH_NAMES:
        raise ValueError("month must be between 1 and 12")
    if day not in range(1, days_in_month(year, month) + 1):
        raise ValueError("day %d is out of range for %s %d"
                         % (day, MONTH_NAMES[month], year))


def days_since(year, month, day):
    validate(year, month, day)
    past = date(year, month, day)
    today = date.today()
    if past > today:
        raise ValueError("%s is not a past date" % past.isoformat())
    return (today - past).days


def describe(year, month, day):
    elapsed = days_since(year, month, day)
    when = "%s %s, %d" % (MONTH_NAMES[month], ordinal(day), year)
    if elapsed == 0:
        return "%s is today" % when
    unit = "day" if elapsed == 1 else "days"
    return "%d full %s since %s" % (elapsed, unit, when)


def main(argv):
    if not argv:
        print("usage: days_since.py YYYY-MM-DD [YYYY-MM-DD ...]")
        return 1
    status = 0
    seen = []
    for arg in argv:
        try:
            parsed = parse_date(arg)
            if parsed not in seen:
                seen.append(parsed)
                print(describe(*parsed))
        except ValueError as exc:
            print("error: %s" % exc)
            status = 1
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

