    if month == 2 and is_leap(year):
        return 29
    return DAYS_IN_MONTH[month]


def parse_date(text):
    text = text.strip()
    for ch in text:
        if not ch in ALLOWED_CHARS:
            raise ValueError("unexpected character %r in %r" % (ch, text))
    for sep in SEPARATORS:
        text = text.replace(sep, "-")
    parts = text.split("-")
    if len(parts) != 3 or not all(parts):
        raise ValueError("expected a date formatted as YYYY-MM-DD")
    return tuple(int(part) for part in parts)


def validate(year, month, day):
    if not year in range(date.min.year, date.max.year + 1):
        raise ValueError("year %d is outside the supported range" % year)
    if not month in MONTH_NAMES:
        raise ValueError("month must be between 1 and 12")
    if not day in range(1, days_in_month(year, month) + 1):
        raise ValueError("day %d is out of range for %s %d"
                         % (day, MONTH_NAMES[month], year))


def days_since(year, month, day):
    validate(year, month, day)
    past = date(year, month, day)
    today = date.today()
    if past > today:
        raise ValueError("%s is not a past date" % past.isoformat())
    return (today - past).days


def describe(year, month, day):
    elapsed = days_since(year, month, day)
    when = "%s %s, %d" % (MONTH_NAMES[month], ordinal(day), year)
    if elapsed == 0:
        return "%s is today" % when
    unit = "day" if elapsed == 1 else "days"
    return "%d full %s since %s" % (elapsed, unit, when)


def main(argv):
    if not argv:
        print("usage: days_since.py YYYY-MM-DD [YYYY-MM-DD ...]")
        return 1
    status = 0
    seen = []
    for arg in argv:
        try:
            parsed = parse_date(arg)
            if not parsed in seen:
                seen.append(parsed)
                print(describe(*parsed))
        except ValueError as exc:
            print("error: %s" % exc)
            status = 1
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

