        else:
            suffix = 2
            while "{}_{}".format(name, suffix) in header:
                suffix += 1
            header.append("{}_{}".format(name, suffix))
    return header


def clean_value(text):
    """Trim a field and treat missing-data tokens as an empty value."""
    value = text.strip()
    if value.lower() not in MISSING_TOKENS:
        return value
    return ""


def parse_csv(text):
    """Parse a whole CSV document into a header and a list of records."""
    rows = []
    for raw_line in text.splitlines():
        fields = parse_csv_line(raw_line)
        if all(field.strip() == "" for field in fields):
            continue
        rows.append(fields)
    if not rows:
        return [], []
    header = normalize_header(rows[0])
    records = []
    for fields in rows[1:]:
        record = {}
        for index, name in enumerate(header):
            record[name] = clean_value(fields[index]) if index < len(fields) else ""
        records.append(record)
    return header, records


def validate_records(records, required):
    """Report records that lack a required field or hold a bad quantity."""
    problems = []
    for position, record in enumerate(records, start=2):
        for field in required:
            if field not in record or record[field] == "":
                problems.append("line {}: missing {}".format(position, field))
        quantity = record.get("quantity", "")
        if quantity and not quantity.isdigit():
            problems.append("line {}: bad quantity {!r}".format(position, quantity))
    return problems


def summarize(records, key):
    """Count how many records fall into each value of the given column."""
    counts = {}
    for record in records:
        value = record.get(key) or "(unknown)"
        if value not in counts:
            counts[value] = 0
        counts[value] += 1
    return counts


def format_table(header, records, columns):
    """Render the chosen columns of the records as an aligned text table."""
    missing = [name for name in columns if name not in header]
    if missing:
        raise KeyError("unknown columns: {}".format(", ".join(missing)))
    widths = [max([len(name)] + [len(r[name]) for r in records]) for name in columns]
    lines = ["  ".join(name.ljust(w) for name, w in zip(columns, widths))]
    lines.append("  ".join("-" * w for w in widths))
    for record in records:
        lines.append("  ".join(record[name].ljust(w) for name, w in zip(columns, widths)))
    return "\n".join(lines)


