    document = "\n".join([
        "Name,Category,Quantity",
        "apple,fruit,4",
        "banana,fruit,",
        "",
        "cabbage,vegetable,12",
        "cherry,fruit,N/A",
    ])
    header, records = parse_csv(document)
    print(format_table(header, records, ["name", "category", "quantity"]))
    print()
    for category, count in sorted(summarize(records, "category").items()):
        print("{:<12} {}".format(category, count))
    print()
    for problem in validate_records(records, ["name", "category"]):
        print(problem)


if __name__ == "__main__":
    main()

