import math


class BankAccount:
    """A simple bank account with deposits, withdrawals and a transaction log."""

    VALID_KINDS = ("deposit", "withdraw")

    def __init__(self, initial_balance=0):
        if not self._is_valid_amount(initial_balance) or initial_balance < 0:
            raise ValueError("initial_balance must be a non-negative number")
        self.balance = initial_balance
        self.history = []

    @staticmethod
    def _is_valid_amount(amount):
        if type(amount) not in (int, float):
            return False
        return math.isfinite(amount)

    def _record(self, kind, amount, ok):
        if kind not in self.VALID_KINDS:
            raise ValueError("unknown transaction kind: %r" % (kind,))
        self.history.append((kind, amount, ok, self.balance))
        return ok

    def deposit(self, amount):
        if not self._is_valid_amount(amount) or amount <= 0:
            return self._record("deposit", amount, False)
        self.balance += amount
        return self._record("deposit", amount, True)

    def withdraw(self, amount):
        if not self._is_valid_amount(amount) or amount <= 0:
            return self._record("withdraw", amount, False)
        if amount > self.balance:
            return self._record("withdraw", amount, False)
        self.balance -= amount
        return self._record("withdraw", amount, True)

    def statement(self):
        lines = ["%-9s %10s %8s %10s" % ("kind", "amount", "result", "balance")]
        for kind, amount, ok, balance in self.history:
            shown = amount if self._is_valid_amount(amount) else "invalid"
            lines.append("%-9s %10s %8s %10s" % (
                kind, shown, "ok" if ok else "failed", balance))
        return "\n".join(lines)


def parse_amount(raw):
    """Turn an amount token into int/float, or return None if it isn't one."""
    if not raw or raw.count(".") > 1:
        return None
    for ch in raw:
        if ch not in "0123456789.":
            return None
    return float(raw) if "." in raw else int(raw)


def apply_commands(account, commands):
    """Run 'deposit 50' / 'withdraw 200' style commands, returning failures."""
    rejected = []
    for line in commands:
        parts = line.split()
        if len(parts) != 2:
            rejected.append((line, "malformed"))
            continue
        kind, raw = parts[0].lower(), parts[1]
        if kind not in BankAccount.VALID_KINDS:
            rejected.append((line, "unknown command"))
            continue
        amount = parse_amount(raw)
        if amount is None:
            rejected.append((line, "bad amount"))
            continue
        if not getattr(account, kind)(amount):
            rejected.append((line, "refused"))
    return rejected


def summarize(account):
    """Total the successful amounts per transaction kind."""
    totals = {}
    for kind, amount, ok, _balance in account.history:
        if not ok:
            continue
        if kind not in totals:
            totals[kind] = 0
        totals[kind] += amount
    return totals


def main():
    acc = BankAccount(100)
    commands = ["deposit 50", "withdraw 200", "transfer 10", "withdraw 25.5",
                "deposit abc", "deposit -5", "withdraw"]
    rejected = apply_commands(acc, commands)
    refused_lines = [line for line, _ in rejected]
    print(acc.statement())
    for line in commands:
        if line not in refused_lines:
            print("applied %r" % line)
    for line, reason in rejected:
        print("rejected %r: %s" % (line, reason))
    for kind, total in sorted(summarize(acc).items()):
        print("total %s: %s" % (kind, total))
    print("final balance: %s" % acc.balance)


if __name__ == "__main__":
    main()

