def update_inventory(inventory, item_name, quantity_change):
    """Apply a quantity change to an item, clamping the result at zero."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(item_name, str) or not item_name.strip():
        raise ValueError("item_name must be a non-empty string")
    if not isinstance(quantity_change, int) or isinstance(quantity_change, bool):
        raise TypeError("quantity_change must be an integer")
    if not item_name in inventory:
        inventory[item_name] = 0
    new_quantity = inventory[item_name] + quantity_change
    if new_quantity < 0:
        new_quantity = 0
    inventory[item_name] = new_quantity
    return inventory


def apply_transactions(inventory, transactions, catalogue=None):
    """Apply (item, change) pairs in order; items outside the catalogue are rejected."""
    rejected = []
    for item_name, quantity_change in transactions:
        if catalogue is not None and not item_name in catalogue:
            rejected.append(item_name)
            continue
        update_inventory(inventory, item_name, quantity_change)
    return inventory, rejected


def uncatalogued_items(inventory, catalogue):
    """Stocked items that the catalogue no longer lists, alphabetically ordered."""
    legacy = []
    for item_name in inventory:
        if not item_name in catalogue:
            legacy.append(item_name)
    return sorted(legacy)


def merge_shipment(inventory, shipment, catalogue):
    """Add a shipment's quantities into the inventory, creating missing items."""
    for item_name, quantity in shipment.items():
        if quantity < 0:
            raise ValueError("shipment quantities must not be negative")
        if not item_name in catalogue:
            raise ValueError("shipment contains uncatalogued item: " + item_name)
        update_inventory(inventory, item_name, quantity)
    return inventory


