def parse_clock(text):
    """Convert a 'HH:MM' string into minutes from midnight."""
    text = text.strip()
    if ":" not in text:
        raise ValueError("clock time must contain ':' -> %r" % text)
    hours, minutes = text.split(":", 1)
    for part in (hours, minutes):
        if part == "":
            raise ValueError("incomplete clock time: %r" % text)
        for ch in part:
            if ch not in "0123456789":
                raise ValueError("bad digit %r in %r" % (ch, text))
    total = int(hours) * 60 + int(minutes)
    if not 0 <= total <= 24 * 60:
        raise ValueError("clock time out of range: %r" % text)
    return total


def to_minutes(value):
    """Accept an int (minutes) or a 'HH:MM' string and return minutes."""
    if isinstance(value, bool) or type(value) not in (int, str):
        raise TypeError("unsupported time value: %r" % (value,))
    if isinstance(value, str):
        return parse_clock(value)
    return value


def format_minutes(total):
    return "%02d:%02d" % (total // 60, total % 60)


def normalize_event(event):
    if not isinstance(event, (tuple, list)) or len(event) != 2:
        raise ValueError("an event must be a (start, end) pair: %r" % (event,))
    start, end = to_minutes(event[0]), to_minutes(event[1])
    if end < start:
        raise ValueError("event ends before it starts: %r" % (event,))
    return start, end


def check_event_overlap(event1, event2):
    start1, end1 = normalize_event(event1)
    start2, end2 = normalize_event(event2)
    return start1 < end2 and start2 < end1


def load_schedule(entries):
    """Build a name -> (start, end) mapping from (name, start, end) triples."""
    schedule = {}
    for name, start, end in entries:
        if name not in schedule:
            schedule[name] = normalize_event((start, end))
        else:
            raise ValueError("duplicate event name: %r" % name)
    return schedule


def find_conflicts(schedule):
    names = sorted(schedule)
    conflicts = []
    for i, first in enumerate(names):
        for second in names[i + 1:]:
            if check_event_overlap(schedule[first], schedule[second]):
                conflicts.append((first, second))
    return conflicts


def conflict_report(schedule):
    conflicts = find_conflicts(schedule)
    conflicted = {name for pair in conflicts for name in pair}
    lines = []
    for first, second in conflicts:
        lines.append("CONFLICT: %s overlaps %s" % (first, second))
    for name in sorted(schedule):
        if name not in conflicted:
            start, end = schedule[name]
            lines.append("OK: %s (%s-%s)" % (name, format_minutes(start), format_minutes(end)))
    return lines


def main():
    print(check_event_overlap((10, 20), (15, 25)))
    print(check_event_overlap((10, 15), (20, 25)))
    schedule = load_schedule([
        ("standup", "09:00", "09:15"),
        ("design", "09:10", "10:00"),
        ("lunch", 12 * 60, 13 * 60),
        ("review", "13:00", "14:00"),
    ])
    for line in conflict_report(schedule):
        print(line)


if __name__ == "__main__":
    main()

