NUMERIC_TYPES = (int, float)
TOKEN_CHARS = set("0123456789+-.eE")
SEPARATORS = ",;\t"
COMMENT_MARKS = "#%"


def coerce_number(value):
    """Return value as a float, rejecting non-numeric input (bools included)."""
    if type(value) not in NUMERIC_TYPES:
        raise TypeError("unsupported value for statistics: %r" % (value,))
    return float(value)


def normalize_separators(text):
    """Replace field separators with spaces so the text can be split."""
    chars = []
    for ch in text:
        if ch not in SEPARATORS:
            chars.append(ch)
        else:
            chars.append(" ")
    return "".join(chars)


def parse_numbers(text):
    """Turn a field list such as '1, 2 3;4' into a list of floats."""
    numbers = []
    for token in normalize_separators(text).split():
        for ch in token:
            if ch not in TOKEN_CHARS:
                raise ValueError("bad character %r in token %r" % (ch, token))
        numbers.append(float(token))
    return numbers


def parse_block(text):
    """Parse 'label: values' lines, skipping blank and comment lines."""
    datasets = {}
    for raw in text.splitlines():
        line = raw.strip()
        if line and line[0] not in COMMENT_MARKS:
            label, sep, fields = line.partition(":")
            if not sep:
                raise ValueError("missing ':' in line %r" % (line,))
            label = label.strip()
            if label not in datasets:
                datasets[label] = parse_numbers(fields)
            else:
                raise ValueError("duplicate label %r" % (label,))
    return datasets


def distinct_values(values):
    unique = []
    for value in values:
        if value not in unique:
            unique.append(value)
    return unique


def mean_absolute_deviation(numbers):
    """Mean of the absolute deviations from the arithmetic mean."""
    values = [coerce_number(n) for n in numbers]
    if not values:
        return 0.0
    center = sum(values) / len(values)
    return sum(abs(v - center) for v in values) / len(values)


def summarize(numbers):
    values = [coerce_number(n) for n in numbers]
    mean = sum(values) / len(values) if values else 0.0
    return {"count": len(values), "distinct": len(distinct_values(values)),
            "mean": mean, "mad": mean_absolute_deviation(values)}


def resolve_datasets(names, datasets):
    """Look each name up, treating unknown names as inline number lists."""
    resolved = []
    for name in names:
        if name not in datasets:
            datasets[name] = parse_numbers(name)
        resolved.append((name, datasets[name]))
    return resolved


def format_report(label, stats):
    return "%-14s n=%d distinct=%d mean=%.4f mad=%.4f" % (
        label, stats["count"], stats["distinct"], stats["mean"], stats["mad"])


def main():
    config = """
# label: values
simple: 1, 2, 3, 4
tens: 10 20 30
mixed: 1.5, -2, 7, 0
empty:
"""
    datasets = parse_block(config)
    requested = ["simple", "tens", "empty", "mixed", "0.5 0.5 0.5"]
    for label, values in resolve_datasets(requested, datasets):
        print(format_report(label, summarize(values)))


if __name__ == "__main__":
    main()

