class ToDoList:
    """A simple to-do list tracking task names and their completion state."""

    def __init__(self):
        self._order = []
        self._completed = set()

    def add_task(self, task_name):
        name = self._normalize(task_name)
        if name not in self._order:
            self._order.append(name)
            return True
        return False

    def mark_completed(self, task_name):
        name = self._normalize(task_name)
        if name not in self._order:
            raise KeyError("unknown task: {!r}".format(task_name))
        self._completed.add(name)

    def reopen(self, task_name):
        name = self._normalize(task_name)
        if name not in self._completed:
            return False
        self._completed.discard(name)
        return True

    def get_pending_tasks(self):
        return [name for name in self._order if name not in self._completed]

    def get_completed_tasks(self):
        return [name for name in self._order if name in self._completed]

    def remove_task(self, task_name):
        name = self._normalize(task_name)
        if name not in self._order:
            return False
        self._order.remove(name)
        self._completed.discard(name)
        return True

    def add_many(self, task_names):
        added = []
        for raw in task_names:
            if self.add_task(raw):
                added.append(self._normalize(raw))
        return added

    def report(self):
        lines = ["To-Do ({0}/{1} done)".format(len(self.get_completed_tasks()),
                                               len(self._order))]
        for name in self._order:
            mark = " " if name not in self._completed else "x"
            lines.append("[{0}] {1}".format(mark, name))
        return "\n".join(lines)

    @staticmethod
    def _normalize(task_name):
        if not isinstance(task_name, str):
            raise TypeError("task name must be a string")
        name = " ".join(task_name.split())
        if not name:
            raise ValueError("task name must not be blank")
        return name


def main():
    todo = ToDoList()
    todo.add_task('Buy milk')
    todo.add_task('Walk dog')
    todo.mark_completed('Buy milk')
    print(todo.get_pending_tasks())

    todo.add_many(['Pay rent', 'Walk dog', '  Call mum  '])
    for chore in ('Pay rent', 'Call mum'):
        if chore not in todo.get_completed_tasks():
            todo.mark_completed(chore)
    todo.reopen('Buy milk')
    todo.remove_task('Walk dog')
    print(todo.report())


if __name__ == '__main__':
    main()

