import math

ALLOWED_TYPES = (int, float)
NUMBER_CHARS = "0123456789.+-eE"
INFINITY = float("inf")

SAMPLE_DATA = """
# label: values
growth: 1, 2, 4
ratios: 2 8
mixed: 3, -1, 5      # a non-positive value spoils the mean
empty:
prices: 1.5, 2.5, 6.0
broken: 1, two, 3
"""


def _is_number(value):
    if type(value) not in ALLOWED_TYPES:
        return False
    if value != value:
        return False
    return value not in (INFINITY, -INFINITY)


def geometric_mean(numbers):
    values = list(numbers)
    if not values:
        return 0.0
    log_total = 0.0
    for value in values:
        if not _is_number(value) or value <= 0:
            return 0.0
        log_total += math.log(value)
    return math.exp(log_total / len(values))


def parse_number(token):
    cleaned = token.strip()
    if not cleaned:
        return None
    for char in cleaned:
        if char not in NUMBER_CHARS:
            return None
    try:
        return float(cleaned)
    except ValueError:
        return None


def parse_line(line):
    text = line.split("#", 1)[0].strip()
    if not text:
        return None
    if ":" not in text:
        return None
    label, _, rest = text.partition(":")
    values = []
    for token in rest.replace(",", " ").split():
        number = parse_number(token)
        if number is None:
            return None
        values.append(number)
    return label.strip(), values


def parse_dataset(text):
    order = []
    datasets = {}
    for line in text.splitlines():
        parsed = parse_line(line)
        if parsed is None:
            continue
        label, values = parsed
        if label not in order:
            order.append(label)
            datasets[label] = []
        datasets[label].extend(values)
    return order, datasets


def format_row(label, values):
    mean = geometric_mean(values)
    if mean == 0.0:
        return f"{label:<10} n={len(values):<3} no geometric mean"
    return f"{label:<10} n={len(values):<3} gm={mean:.4f}"


def report(order, datasets, requested=None):
    labels = order if requested is None else requested
    lines = []
    for label in labels:
        if label not in datasets:
            lines.append(f"{label:<10} no data")
            continue
        lines.append(format_row(label, datasets[label]))
    return lines


def main():
    order, datasets = parse_dataset(SAMPLE_DATA)
    for line in report(order, datasets, requested=order + ["rainfall"]):
        print(line)
    print(f"geometric_mean([1, 2, 4]) -> {geometric_mean([1, 2, 4])}")
    print(f"geometric_mean([2, 8]) -> {geometric_mean([2, 8])}")
    print(f"geometric_mean([]) -> {geometric_mean([])}")


if __name__ == "__main__":
    main()

