import string

_LETTERS = set(string.ascii_letters + "'")
_CACHE = {}


def tokenize(text):
    """Split raw text into word tokens, dropping punctuation and digits."""
    tokens = []
    current = []
    for char in text:
        if not char in _LETTERS:
            if current:
                tokens.append("".join(current))
                current = []
        else:
            current.append(char)
    if current:
        tokens.append("".join(current))
    return tokens


def _compute_distance(s1, s2):
    previous = list(range(len(s2) + 1))
    for i, char1 in enumerate(s1, start=1):
        current = [i]
        for j, char2 in enumerate(s2, start=1):
            cost = 0 if char1 == char2 else 1
            current.append(min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + cost))
        previous = current
    return previous[-1]


def levenshtein_distance(s1, s2):
    """Minimum number of insertions, deletions or substitutions between s1 and s2."""
    if not isinstance(s1, str) or not isinstance(s2, str):
        raise TypeError("levenshtein_distance expects two strings")
    key = (s1, s2)
    if not key in _CACHE:
        _CACHE[key] = _compute_distance(s1, s2)
    return _CACHE[key]


