DIGITS = "0123456789ABCDEF"
BASE_ALIASES = {"binary": 2, "octal": 8, "decimal": 10, "hexadecimal": 16}
BASE_PREFIXES = {2: "0b", 8: "0o", 16: "0x"}


def convert_base(number, base):
    """Return the representation of base-10 integer `number` in `base` (2..16)."""
    if base not in range(2, 17):
        raise ValueError("base must be between 2 and 16")
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an integer")
    if number == 0:
        return "0"
    negative = number < 0
    value = -number if negative else number
    digits = []
    while value:
        value, rem = divmod(value, base)
        digits.append(DIGITS[rem])
    if negative:
        digits.append("-")
    return "".join(reversed(digits))


def parse_base(text, base):
    """Inverse of convert_base: read a string written in `base` back to an int."""
    text = text.strip().upper()
    sign = 1
    if text[:1] in "+-" and text[:1]:
        sign = -1 if text[0] == "-" else 1
        text = text[1:]
    prefix = base_prefix(base).upper()
    if prefix and text.startswith(prefix):
        text = text[len(prefix):]
    if not text:
        raise ValueError("empty numeral")
    valid = DIGITS[:base]
    total = 0
    for ch in text:
        if ch not in valid:
            raise ValueError("digit %r is not valid in base %d" % (ch, base))
        total = total * base + valid.index(ch)
    return sign * total


def base_name(base):
    """Human-readable name for the common bases, falling back to 'base N'."""
    names = {2: "binary", 8: "octal", 10: "decimal", 16: "hexadecimal"}
    if base not in names:
        return "base %d" % base
    return names[base]


def base_prefix(base):
    """Conventional literal prefix for a base, or '' when there is none."""
    if base not in BASE_PREFIXES:
        return ""
    return BASE_PREFIXES[base]


def base_from_name(name):
    """Turn a base name ('binary') or a numeral ('12') into an integer base."""
    key = name.strip().lower()
    if key not in BASE_ALIASES:
        return int(key)
    return BASE_ALIASES[key]


def normalize_bases(names):
    """Resolve base names to integers, dropping repeats and keeping the order."""
    bases = []
    for name in names:
        base = base_from_name(name)
        if base not in bases:
            bases.append(base)
    return bases


def format_number(number, base):
    """Prefixed numeral, e.g. '0xFF', with the sign kept in front."""
    text = convert_base(number, base)
    if text.startswith("-"):
        return "-" + base_prefix(base) + text[1:]
    return base_prefix(base) + text


def conversion_table(numbers, bases):
    """Build a list of report lines, one per number, showing every base."""
    lines = []
    for number in numbers:
        cells = ["%s=%s" % (base_name(b), format_number(number, b)) for b in bases]
        lines.append("%6d : %s" % (number, "  ".join(cells)))
    return lines


def main():
    bases = normalize_bases(["binary", "octal", "decimal", "hexadecimal", "16"])
    for line in conversion_table([0, 10, 255, 4095, -42], bases):
        print(line)
    for text, base in [("FF", 16), ("0b1010", 2), ("777", 8), ("2G", 16)]:
        try:
            print("%s (%s) -> %d" % (text, base_name(base), parse_base(text, base)))
        except ValueError as exc:
            print("%s (%s) -> error: %s" % (text, base_name(base), exc))


if __name__ == "__main__":
    main()

