PUNCTUATION = ".,;:!?\"'()[]{}"

def word_frequency(words):
    """Count how often each word occurs, ignoring case."""
    counts = {}
    for word in words:
        if not isinstance(word, str):
            raise TypeError('word_frequency expects a list of strings')
        key = word.lower()
        if key not in counts:
            counts[key] = 0
        counts[key] += 1
    return counts

def significant_words(words):
    """Drop the common filler words before counting."""
    kept = []
    for word in words:
        if word.lower() not in STOPWORDS:
            kept.append(word)
    return kept

def unknown_words(counts):
    """Counted words that are missing from the known vocabulary."""
    missing = []
    for word in counts:
        if word not in KNOWN_WORDS:
            missing.append(word)
    return sorted(missing)

def merge_counts(*count_dicts):
    """Combine several frequency dictionaries into one."""
    merged = {}
    for counts in count_dicts:
        for word, number in counts.items():
            if word not in merged:
                merged[word] = 0
            merged[word] += number
    return merged

def absent_words(counts, expected):
    """Expected words that never showed up in the counts."""
    absent = []
    for word in expected:
        key = word.lower()
        if key not in counts:
            absent.append(key)
    return absent

def tokenize(text):
    """Split raw text into words, dropping surrounding punctuation."""
    tokens = []
    for raw in text.split():
