import sys

ALNUM = set("abcdefghijklmnopqrstuvwxyz0123456789")
KNOWN_FLAGS = ("--quiet",)
LABELS = {True: "palindrome", False: "not a palindrome"}
DEFAULTS = [
    "Racecar",
    "A man, a plan, a canal: Panama",
    "hello world",
    "No 'x' in Nixon",
    "12321",
    "ab",
]

_CACHE = {}


def normalize(s):
    kept = []
    for ch in s.lower():
        if ch not in ALNUM:
            continue
        kept.append(ch)
    return "".join(kept)


def is_palindrome_string(s):
    if not isinstance(s, str):
        raise TypeError("expected a string, got %s" % type(s).__name__)
    cleaned = normalize(s)
    if cleaned not in _CACHE:
        _CACHE[cleaned] = cleaned == cleaned[::-1]
    return _CACHE[cleaned]


def unique_candidates(items):
    seen = set()
    out = []
    for item in items:
        cleaned = normalize(item)
        if cleaned not in seen:
            seen.add(cleaned)
            out.append(item)
    return out


def describe(s):
    cleaned = normalize(s)
    if not cleaned:
        return "%r -> nothing left after cleaning, counted as a palindrome" % s
    return "%r -> %s (cleaned: %r)" % (s, LABELS[is_palindrome_string(s)], cleaned)


def palindromes_only(items):
    return [item for item in items if is_palindrome_string(item)]


def parse_args(argv):
    flags = [arg for arg in argv if arg.startswith("--")]
    for flag in flags:
        if flag not in KNOWN_FLAGS:
            raise SystemExit("unknown option: %s" % flag)
    texts = [arg for arg in argv if arg not in flags]
    return texts, "--quiet" not in flags


def main(argv):
    texts, verbose = parse_args(argv)
    if not texts:
        texts = DEFAULTS
    candidates = unique_candidates(texts)
    if verbose:
        for item in candidates:
            print(describe(item))
    hits = palindromes_only(candidates)
    print("%d of %d input(s) are palindromes" % (len(hits), len(candidates)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

