def _validate_sequence(name, value):
    """Ensure an argument is a list or tuple before pairing its elements."""
    if type(value) not in (list, tuple):
        raise TypeError("{} must be a list or tuple, got {}".format(name, type(value).__name__))
    return list(value)


def cartesian_product(list1, list2):
    """Return every ordered pair (a, b) with a from list1 and b from list2."""
    left = _validate_sequence("list1", list1)
    right = _validate_sequence("list2", list2)
    pairs = []
    for a in left:
        for b in right:
            pairs.append((a, b))
    return pairs


def filtered_product(list1, list2, excluded):
    """Cartesian product built only from values outside `excluded`."""
    left = [a for a in list1 if a not in excluded]
    right = [b for b in list2 if b not in excluded]
    return cartesian_product(left, right)


def missing_pairs(pairs, reference):
    """Pairs from `pairs` that do not occur in the reference collection."""
    return [pair for pair in pairs if pair not in reference]


def unpaired_values(values, pairs, index):
    """Values that never appear at position `index` of any produced pair."""
    used = [pair[index] for pair in pairs]
    return [value for value in values if value not in used]


def format_pair_table(pairs):
    """Render pairs as aligned "left | right" rows."""
    if not pairs:
        return "(no pairs)"
    width = max(len(repr(a)) for a, _ in pairs)
    rows = []
    for a, b in pairs:
        rows.append("{} | {}".format(repr(a).ljust(width), repr(b)))
    return "\n".join(rows)


def report(list1, list2, excluded=()):
    """Build a short human-readable summary of one product computation."""
    full = cartesian_product(list1, list2)
    lines = ["{} x {} -> {} pair(s)".format(list1, list2, len(full)),
             format_pair_table(full)]
    idle_left = unpaired_values(list1, full, 0)
    if idle_left:
        lines.append("unpaired from list1: {}".format(idle_left))
    idle_right = unpaired_values(list2, full, 1)
    if idle_right:
        lines.append("unpaired from list2: {}".format(idle_right))
    if excluded:
        allowed = filtered_product(list1, list2, excluded)
        dropped = missing_pairs(full, allowed)
        lines.append("excluding {}: dropped {}".format(list(excluded), dropped))
    return "\n".join(lines)


def main():
    print(report([1, 2], ['a', 'b']))
    print()
    print(report([1], []))
    print()
    print(report([1, 2, 3], ['x', 'y'], excluded=(2, 'y')))


if __name__ == "__main__":
    main()

