    if unit == 'C':
        return value + 273.15
    if unit == 'F':
        return (value - 32.0) * 5.0 / 9.0 + 273.15
    return value


def from_kelvin(kelvin, unit):
    """Convert a kelvin temperature to `unit`."""
    if unit == 'C':
        return kelvin - 273.15
    if unit == 'F':
        return (kelvin - 273.15) * 9.0 / 5.0 + 32.0
    return kelvin


