HEX_DIGITS = "0123456789abcdefABCDEF"
VALID_LENGTHS = (3, 6)
NAMED_COLORS = {
    "black": "#000", "white": "#FFFFFF", "red": "#FF0000",
    "lime": "#0F0", "blue": "#0000FF", "gray": "#808080",
}


def is_valid_hex_color(code):
    """Return True if code is a valid 3- or 6-digit hex color code."""
    if not isinstance(code, str):
        return False
    if not code.startswith("#"):
        return False
    body = code[1:]
    if len(body) not in VALID_LENGTHS:
        return False
    for char in body:
        if char not in HEX_DIGITS:
            return False
    return True


def resolve(text):
    """Return the hex code named by text, or text itself if it is a code."""
    if is_valid_hex_color(text):
        return text
    key = text.strip().lower() if isinstance(text, str) else text
    if key not in NAMED_COLORS:
        raise ValueError("not a color name or hex code: %r" % (text,))
    return NAMED_COLORS[key]


def expand_short_form(code):
    """Turn '#ABC' into '#AABBCC'; leave 6-digit codes unchanged."""
    if not is_valid_hex_color(code):
        raise ValueError("not a valid hex color: %r" % (code,))
    body = code[1:]
    if len(body) == 3:
        return "#" + "".join(char * 2 for char in body)
    return code


def to_rgb(code):
    """Return the (red, green, blue) channel values of a hex color."""
    full = expand_short_form(code)[1:]
    return tuple(int(full[i:i + 2], 16) for i in (0, 2, 4))


def normalize(code):
    """Canonical form: '#' plus six uppercase hex digits."""
    return expand_short_form(code).upper()


def classify(code):
    """Describe a color as 'dark', 'medium' or 'light'."""
    red, green, blue = to_rgb(code)
    brightness = (red * 299 + green * 587 + blue * 114) // 1000
    if brightness < 85:
        return "dark"
    if brightness < 170:
        return "medium"
    return "light"


def build_palette(entries):
    """Collect unique valid colors, reporting anything rejected."""
    palette = []
    rejected = []
    for entry in entries:
        try:
            canonical = normalize(resolve(entry))
        except ValueError:
            rejected.append(entry)
            continue
        if canonical not in palette:
            palette.append(canonical)
    return palette, rejected


def group_by_class(palette):
    """Map 'dark'/'medium'/'light' to the canonical codes in each group."""
    groups = {}
    for canonical in palette:
        label = classify(canonical)
        if label not in groups:
            groups[label] = []
        groups[label].append(canonical)
    return groups


def format_report(entries):
    palette, rejected = build_palette(entries)
    lines = []
    for label in ("dark", "medium", "light"):
        for canonical in group_by_class(palette).get(label, []):
            red, green, blue = to_rgb(canonical)
            lines.append("%s  rgb(%3d, %3d, %3d)  %s"
                         % (canonical, red, green, blue, label))
    for entry in rejected:
        lines.append("%r is not a valid hex color" % (entry,))
    return "\n".join(lines)


