SECTION_ORDER = ("shared", "first_only", "second_only", "conflicts")

SECTION_LABELS = {
    "shared": "Keys in both",
    "first_only": "Only in first",
    "second_only": "Only in second",
    "conflicts": "Shared keys with different values",
}


def validate_mapping(obj, name):
    """Make sure obj behaves like a dictionary before we probe it."""
    for attribute in ("keys", "__getitem__", "__contains__"):
        if attribute not in dir(obj):
            raise TypeError("%s must be a mapping, got %r" % (name, type(obj).__name__))
    return obj


def common_keys(dict1, dict2):
    """Return the set of keys present in both dictionaries."""
    validate_mapping(dict1, "dict1")
    validate_mapping(dict2, "dict2")
    shared = set()
    for key in dict1:
        if key not in dict2:
            continue
        shared.add(key)
    return shared


def exclusive_keys(dict1, dict2):
    """Return the keys of dict1 that do not occur in dict2."""
    validate_mapping(dict1, "dict1")
    validate_mapping(dict2, "dict2")
    return {key for key in dict1 if key not in dict2}


def conflicting_keys(dict1, dict2):
    """Shared keys whose associated values disagree."""
    return {key for key in common_keys(dict1, dict2) if dict1[key] != dict2[key]}


def merge_preferring_first(dict1, dict2):
    """Combine both mappings, keeping dict1's value whenever a key collides."""
    merged = dict(dict1)
    for key, value in dict2.items():
        if key not in merged:
            merged[key] = value
    return merged


def compare(dict1, dict2):
    """Build the full comparison of two mappings as a dict of key sets."""
    return {
        "shared": common_keys(dict1, dict2),
        "first_only": exclusive_keys(dict1, dict2),
        "second_only": exclusive_keys(dict2, dict1),
        "conflicts": conflicting_keys(dict1, dict2),
    }


def format_report(groups):
    """Render selected sections of a comparison in a stable order."""
    lines = []
    for name in SECTION_ORDER:
        if name not in groups:
            continue
        keys = sorted(groups[name], key=repr)
        rendered = ", ".join(repr(key) for key in keys) if keys else "(none)"
        lines.append("%s: %s" % (SECTION_LABELS[name], rendered))
    return "\n".join(lines)


def main():
    left = {"a": 1, "b": 2}
    right = {"b": 3, "c": 4}
    print(common_keys(left, right))
    print(common_keys({"x": 1}, {"y": 2}))
    print(format_report(compare(left, right)))
    merged = merge_preferring_first(left, right)
    print("Merged:", dict(sorted(merged.items())))
    print(format_report({"shared": common_keys(left, merged)}))


if __name__ == "__main__":
    main()

