import sys

_PLAIN_CHARS = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
_LITERALS = {"none": None, "true": True, "false": False}


def format_element(value):
    """Render a single element, quoting strings that are not simple words."""
    if isinstance(value, str):
        for character in value:
            if character not in _PLAIN_CHARS:
                return repr(value)
        return value
    return repr(value)


def format_permutation(perm):
    """Render a sequence of elements as a parenthesised, comma separated list."""
    return "(" + ", ".join(format_element(value) for value in perm) + ")"


def parse_token(text):
    """Turn one text token into a Python value."""
    token = text.strip()
    if len(token) >= 2 and token[0] == token[-1] and token[0] in "'\"":
        return token[1:-1]
    lowered = token.lower()
    if lowered not in _LITERALS:
        try:
            return int(token)
        except ValueError:
            pass
        try:
            return float(token)
        except ValueError:
            return token
    return _LITERALS[lowered]


def parse_sample(text):
    """Read a comma separated description of a list."""
    body = text.strip()
    if body in ("", "[]"):
        return []
    return [parse_token(part) for part in body.split(",")]


def generate_permutations(lst):
    """Return every ordering of the elements of lst as a list of lists."""
    n = len(lst)
    result = []
    current = []
    used = set()

    def build():
        if len(current) == n:
            result.append(list(current))
            return
        for i in range(n):
            if i not in used:
                used.add(i)
                current.append(lst[i])
                build()
                current.pop()
                used.remove(i)

    build()
    return result


def _permutation_key(perm):
    """Build a hashable, type-aware key for a sequence of elements."""
    return tuple((type(value).__name__, repr(value)) for value in perm)


def unique_permutations(lst):
    """Like generate_permutations, but collapses orderings that look identical."""
    seen = set()
    distinct = []
    for perm in generate_permutations(lst):
        key = _permutation_key(perm)
        if key not in seen:
            seen.add(key)
            distinct.append(perm)
    return distinct


def group_by_first(perms):
    """Count the orderings by the element that appears first."""
    groups = {}
    for perm in perms:
        key = format_element(perm[0])
        if key not in groups:
            groups[key] = 0
        groups[key] += 1
    return groups


def describe(lst):
    """Produce report lines for the permutations of lst."""
    perms = generate_permutations(lst)
    distinct = unique_permutations(lst)
    lines = ["input %s -> %d permutation(s)" % (format_permutation(lst), len(perms))]
    if len(distinct) != len(perms):
        lines.append("  %d of them are distinct" % len(distinct))
    for perm in distinct:
        lines.append("  " + format_permutation(perm))
    if lst:
        for key, count in sorted(group_by_first(distinct).items()):
            lines.append("  %s first in %d ordering(s)" % (key, count))
    return lines


