NUMERIC_TYPES = (int, float)


def _validate_sequence(values, name):
    if type(values) not in (list, tuple):
        raise TypeError(f"{name} must be a list or tuple, got {type(values).__name__}")
    checked = list(values)
    for index, item in enumerate(checked):
        if type(item) not in NUMERIC_TYPES:
            raise TypeError(f"{name}[{index}] is not a number: {item!r}")
    for index in range(1, len(checked)):
        if checked[index] < checked[index - 1]:
            raise ValueError(f"{name} is not sorted at index {index}: {checked[index]}")
    return checked


def merge_sorted_lists(list1, list2):
    left = _validate_sequence(list1, "list1")
    right = _validate_sequence(list2, "list2")
    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged


def exclusive_values(values, other):
    other_values = set(other)
    return [value for value in values if value not in other_values]


def merge_unique(list1, list2):
    seen = set()
    unique = []
    for value in merge_sorted_lists(list1, list2):
        if value not in seen:
            seen.add(value)
            unique.append(value)
    return unique


def merge_all(lists):
    result = []
    for position, current in enumerate(lists):
        result = merge_sorted_lists(result, _validate_sequence(current, f"lists[{position}]"))
    return result


def describe(merged):
    counts = {}
    for value in merged:
        if value not in counts:
            counts[value] = 0
        counts[value] += 1
    duplicates = sorted(value for value, total in counts.items() if total > 1)
    return {"length": len(merged), "distinct": len(counts), "duplicates": duplicates}


def format_report(label, merged):
    info = describe(merged)
    parts = [f"{label}: {merged}", f"length={info['length']}", f"distinct={info['distinct']}"]
    if info["duplicates"]:
        parts.append("duplicates=" + ",".join(str(v) for v in info["duplicates"]))
    return " | ".join(parts)


def main():
    cases = [([1, 3, 5], [2, 4, 6]), ([10], []), ([], []), ([1, 2, 2], [2, 3])]
    for left, right in cases:
        merged = merge_sorted_lists(left, right)
        print(format_report(f"{left} + {right}", merged))
        print("   only in left:", exclusive_values(left, right),
              "only in right:", exclusive_values(right, left))
        if merged != merge_unique(left, right):
            print("   unique form:", merge_unique(left, right))
    print(format_report("merge_all", merge_all([[1, 4], [2, 2, 9], [], [0, 3]])))
    for bad in ([3, 1], "12", [1, None]):
        try:
            merge_sorted_lists(bad, [0])
        except (TypeError, ValueError) as exc:
            print("rejected:", exc)


