PUNCTUATION = set(",.;:!?\"'()[]")


def trailing_punctuation(token):
    """Return the run of punctuation characters at the end of a token."""
    cut = len(token)
    while cut > 0:
        if token[cut - 1] not in PUNCTUATION:
            break
        cut -= 1
    return token[cut:]


def is_word(token):
    """A token counts as a word only if it carries at least one non-punctuation character."""
    for ch in token:
        if ch not in PUNCTUATION:
            return True
    return False


def punctuation_used(sentence):
    """List the distinct punctuation marks of a sentence, in order of first appearance."""
    marks = []
    for ch in sentence:
        if ch in PUNCTUATION and ch not in marks:
            marks.append(ch)
    return marks


def reverse_words_with_punctuation(sentence):
    """Reverse the words of a sentence, keeping punctuation glued to the word it belongs to.

    Each slot in the sentence also keeps the punctuation it originally showed, unless the
    word that moves into it already carries that mark; the closing mark of the sentence is
    left to whichever word ends up last.
    """
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    tokens = sentence.split()
    if not tokens:
        return ""
    slots = [i for i, token in enumerate(tokens) if is_word(token)]
    words = [tokens[i] for i in slots]
    slot_marks = [trailing_punctuation(word) for word in words]
    moved = words[::-1]
    out = list(tokens)
    last = len(moved) - 1
    for index, (slot, word) in enumerate(zip(slots, moved)):
        mark = slot_marks[index]
        if index != last and mark and mark not in word:
            out[slot] = word + mark
        else:
            out[slot] = word
    return " ".join(out)


def build_report(sentences):
    """Format one line per sentence, skipping duplicates, with the marks that were involved."""
    seen = []
    lines = []
    for sentence in sentences:
        if sentence not in seen:
            seen.append(sentence)
            flipped = reverse_words_with_punctuation(sentence)
            marks = punctuation_used(sentence)
            suffix = "  marks: " + "".join(marks) if marks else "  marks: none"
            lines.append("%-28r -> %-28r%s" % (sentence, flipped, suffix))
    return "\n".join(lines)


def main(argv):
    sentences = argv[1:]
    if not sentences:
        sentences = [
            "Hello, world!",
            "One. Two. Three.",
            "Keep -- calm and carry on?",
        ]
    print(build_report(sentences))


if __name__ == "__main__":
    import sys

    main(sys.argv)

