import math
import sys

_NUMERIC_TYPES = (int, float)
_ALLOWED_CHARS = set("0123456789+-.eE")
_REPORT_FIELDS = ("mean", "std_dev", "range")
_DATA_LINES = [
    "example1: 1, 2, 3",
    "example2: 10, 20, 30, 40",
    "single: 42",
    "empty:",
    "mixed: 1.5, 2, 3e0, 4",
]


def parse_number(token):
    """Convert a text token into a float, rejecting anything non-numeric."""
    text = token.strip()
    if not text:
        raise ValueError("empty token")
    for char in text:
        if char not in _ALLOWED_CHARS:
            raise ValueError("invalid character %r in %r" % (char, token))
    if text[0] not in "+-.0123456789":
        raise ValueError("token %r does not start with a number" % token)
    return float(text)


def parse_dataset(line):
    """Split a 'name: v1, v2, ...' line into a name and a list of floats."""
    if ":" not in line:
        raise ValueError("expected 'name: values', got %r" % line)
    name, _, rest = line.partition(":")
    return name.strip(), [parse_number(part) for part in rest.split(",") if part.strip()]


def clean_values(raw_values):
    """Accept numbers or numeric strings, drop booleans, return a list of floats."""
    values = []
    for item in raw_values:
        if isinstance(item, bool):
            continue
        if isinstance(item, str):
            values.append(parse_number(item))
        elif type(item) not in _NUMERIC_TYPES:
            raise TypeError("unsupported value: %r" % (item,))
        else:
            values.append(float(item))
    return values


def calculate_sample_std_dev(numbers):
    """Sample standard deviation (n-1 denominator); 0.0 for fewer than 2 items."""
    values = clean_values(numbers)
    count = len(values)
    if count < 2:
        return 0.0
    mean = sum(values) / count
    variance = sum((value - mean) ** 2 for value in values) / (count - 1)
    return math.sqrt(variance)


def summarize(dataset):
    """Build a summary dictionary for one dataset."""
    values = clean_values(dataset)
    summary = {"count": len(values), "std_dev": calculate_sample_std_dev(values)}
    if values:
        summary["mean"] = sum(values) / len(values)
        summary["range"] = max(values) - min(values)
    return summary


def format_summary(name, summary):
    """Render a summary, tolerating the keys omitted for empty datasets."""
    parts = ["%s: n=%d" % (name, summary["count"])]
    for field in _REPORT_FIELDS:
        if field not in summary:
            parts.append("%s=n/a" % field)
        else:
            parts.append("%s=%.4f" % (field, summary[field]))
    return " ".join(parts)


def main(argv):
    datasets = dict(parse_dataset(line) for line in _DATA_LINES)
    requested = argv[1:] or sorted(datasets)
    for name in requested:
        if name not in datasets:
            print("%s: unknown dataset" % name)
            continue
        print(format_summary(name, summarize(datasets[name])))


if __name__ == "__main__":
    main(sys.argv)

