from datetime import date, timedelta

WORKDAYS = frozenset({0, 1, 2, 3, 4})
DIGITS = "0123456789"
DAY_NAMES = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")

HOLIDAY_CALENDAR = [
    "# date,name",
    "2023-12-25,Christmas Day",
    "2023-12-26,Boxing Day",
    "2024-01-01,New Year's Day",
]


def parse_date(text):
    """Parse an ISO 'YYYY-MM-DD' string into a datetime.date."""
    parts = text.strip().split("-")
    if len(parts) != 3:
        raise ValueError("expected YYYY-MM-DD, got %r" % text)
    for part in parts:
        for char in part:
            if char not in DIGITS:
                raise ValueError("non-numeric component in %r" % text)
    return date(int(parts[0]), int(parts[1]), int(parts[2]))


def parse_holiday_line(line):
    """Split a 'YYYY-MM-DD,name' calendar row into a date and its label."""
    if "," not in line:
        raise ValueError("expected 'YYYY-MM-DD,name', got %r" % line)
    iso, name = line.split(",", 1)
    return parse_date(iso), name.strip()


def load_holidays(lines):
    """Build a {date: name} mapping, ignoring blank and commented rows."""
    holidays = {}
    for line in lines:
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        day, name = parse_holiday_line(text)
        holidays[day] = name
    return holidays


def is_business_day(day, holidays=frozenset()):
    """True when `day` is a weekday and not listed as a holiday."""
    if day.weekday() not in WORKDAYS:
        return False
    return day not in holidays


def get_next_business_day(day, holidays=frozenset()):
    """Return the first business day strictly after `day`."""
    candidate = day + timedelta(days=1)
    while not is_business_day(candidate, holidays):
        candidate += timedelta(days=1)
    return candidate


def add_business_days(day, count, holidays=frozenset()):
    if count < 0:
        raise ValueError("count must be non-negative")
    result = day
    for _ in range(count):
        result = get_next_business_day(result, holidays)
    return result


def business_days_between(start, end, holidays=frozenset()):
    """Count business days in the half-open interval (start, end]."""
    if end < start:
        raise ValueError("end must not precede start")
    total = 0
    cursor = get_next_business_day(start, holidays)
    while cursor <= end:
        total += 1
        cursor = get_next_business_day(cursor, holidays)
    return total


def holidays_by_month(holidays):
    grouped = {}
    for day in sorted(holidays):
        month = day.strftime("%Y-%m")
        if month not in grouped:
            grouped[month] = []
        grouped[month].append(holidays[day])
    return grouped


def describe(day, holidays=frozenset()):
    label = DAY_NAMES[day.weekday()]
    if day in holidays:
        label += " (%s)" % holidays[day]
    nxt = get_next_business_day(day, holidays)
    return "%s %s -> %s %s" % (day.isoformat(), label, nxt.isoformat(), DAY_NAMES[nxt.weekday()])


def main():
    holidays = load_holidays(HOLIDAY_CALENDAR)
    for text in ["2023-10-26", "2023-10-27", "2023-10-28", "2023-12-22"]:
        print(describe(parse_date(text), holidays))
    start = parse_date("2023-12-22")
    print("five business days later:", add_business_days(start, 5, holidays).isoformat())
    print("business days until 2024-01-05:",
          business_days_between(start, parse_date("2024-01-05"), holidays))
    for month, names in sorted(holidays_by_month(holidays).items()):
        print(month, "holidays:", ", ".join(names))


if __name__ == "__main__":
    main()

