"""Closest pair of points on a 1D line, with parsing and reporting."""

NUMERIC_TYPES = (int, float)
ALLOWED_CHARS = "0123456789+-."


def validate_points(points):
    """Return the points as a plain list, rejecting anything non-numeric."""
    values = list(points)
    if len(values) < 2:
        raise ValueError("at least two points are required")
    for index, value in enumerate(values):
        if type(value) not in NUMERIC_TYPES:
            raise TypeError("point %d is not a number: %r" % (index, value))
    return values


def coincident_points(points):
    """Return the sorted coordinates that occur more than once."""
    seen = []
    duplicates = []
    for value in validate_points(points):
        if value not in seen:
            seen.append(value)
        elif value not in duplicates:
            duplicates.append(value)
    return sorted(duplicates)


def parse_number(token):
    """Convert one coordinate token, keeping whole numbers as integers."""
    for char in token:
        if char not in ALLOWED_CHARS:
            raise ValueError("invalid coordinate %r" % token)
    if "." not in token:
        return int(token)
    return float(token)


def parse_points(text):
    """Parse coordinates separated by commas, semicolons or whitespace."""
    tokens = text.replace(";", " ").replace(",", " ").split()
    return validate_points([parse_number(token) for token in tokens])


def find_closest_pair_1d(points):
    """Return the two points with the smallest distance between them."""
    values = sorted(validate_points(points))
    pairs = zip(values, values[1:])
    return min(pairs, key=lambda pair: pair[1] - pair[0])


def format_report(label, points):
    """Build a short human readable summary for one set of points."""
    values = validate_points(points)
    low, high = find_closest_pair_1d(values)
    duplicates = coincident_points(values)
    singles = [value for value in values if value not in duplicates]
    report = "%s: closest pair (%s, %s) at distance %g" % (label, low, high, high - low)
    report += "; %d of %d positions occur once" % (len(singles), len(values))
    if duplicates:
        report += "; coincident: %s" % ", ".join(str(value) for value in duplicates)
    return report


def main():
    datasets = {
        "example-1": "1.0, 5.0, 2.0, 8.0",
        "example-2": "10 15 12 20",
        "sensors": "3.5; 9.25; -4.0; 9.0; 3.5",
    }
    for name in sorted(datasets):
        print(format_report(name, parse_points(datasets[name])))


if __name__ == "__main__":
    main()

