VALID_DEPARTMENTS = ('HR', 'IT', 'Sales', 'Finance', 'Support')

REQUIRED_FIELDS = ('id', 'name', 'department')


def employee_ids(db):
    return [record['id'] for record in db if 'id' in record]


def is_valid_record(record):
    for field in REQUIRED_FIELDS:
        if field not in record:
            return False
    return record['department'] in VALID_DEPARTMENTS


def normalize_department(department):
    cleaned = department.strip().title()
    if cleaned not in VALID_DEPARTMENTS:
        for known in VALID_DEPARTMENTS:
            if known.upper() == cleaned.upper():
                return known
    return cleaned


def add_employee(db, employee_id, name, department):
    if not isinstance(employee_id, int) or isinstance(employee_id, bool):
        return False
    if not isinstance(name, str) or not name.strip():
        return False
    if not isinstance(department, str):
        return False
    dept = normalize_department(department)
    if dept not in VALID_DEPARTMENTS:
        return False
    if employee_id not in employee_ids(db):
        db.append({'id': employee_id, 'name': name.strip(), 'department': dept})
        return True
    return False


def find_employee(db, employee_id):
    for record in db:
        if record['id'] == employee_id:
            return record
    return None


def group_by_department(db):
    groups = {}
    for record in db:
        if not is_valid_record(record):
            continue
        dept = record['department']
        if dept not in groups:
            groups[dept] = []
        groups[dept].append(record['name'])
    return groups


def format_report(db):
    groups = group_by_department(db)
    lines = []
    for dept in VALID_DEPARTMENTS:
        if dept not in groups:
            continue
        lines.append('%s: %s' % (dept, ', '.join(sorted(groups[dept]))))
    return '\n'.join(lines)


def main():
    db = []
    candidates = [
        (1, 'Alice', 'HR'),
        (2, 'Bob', 'it'),
        (1, 'Charlie', 'Sales'),
        (3, 'Dana', 'Marketing'),
        (4, 'Eve', ' finance '),
    ]
    for emp_id, name, dept in candidates:
        added = add_employee(db, emp_id, name, dept)
        print('%-8s id=%d name=%s dept=%r' % (added, emp_id, name, dept))
    missing = find_employee(db, 3)
    if missing is None:
        print('employee 3 was rejected')
    print(format_report(db))


if __name__ == '__main__':
    main()

