QUADRANT_NAMES = {
    1: "upper right",
    2: "upper left",
    3: "lower left",
    4: "lower right",
    0: "on an axis",
}

_NUMERIC_TYPES = (int, float)


def get_quadrant(x, y):
    """Return the quadrant (1-4) containing (x, y), or 0 if it lies on an axis."""
    if type(x) not in _NUMERIC_TYPES:
        raise TypeError("x must be an int or a float, got %r" % (x,))
    if type(y) not in _NUMERIC_TYPES:
        raise TypeError("y must be an int or a float, got %r" % (y,))
    if x == 0 or y == 0:
        return 0
    if x > 0:
        return 1 if y > 0 else 4
    return 2 if y > 0 else 3


def parse_point(text):
    """Parse a point written as "3, 5" or "(-2 0)" into a pair of numbers."""
    cleaned = "".join(ch if ch not in "()[]," else " " for ch in text)
    fields = cleaned.split()
    if len(fields) != 2:
        raise ValueError("expected two coordinates in %r" % (text,))
    coords = []
    for field in fields:
        number = float(field)
        if "." not in field and number.is_integer():
            coords.append(int(number))
        else:
            coords.append(number)
    return coords[0], coords[1]


def describe(x, y):
    """Build a human readable sentence about where (x, y) sits."""
    quadrant = get_quadrant(x, y)
    name = QUADRANT_NAMES[quadrant]
    if quadrant == 0:
        axis = "the origin" if x == 0 and y == 0 else ("the y-axis" if x == 0 else "the x-axis")
        return "(%s, %s) lies %s: %s" % (x, y, name, axis)
    return "(%s, %s) lies in quadrant %d (%s)" % (x, y, quadrant, name)


def summarize(points):
    """Count how many of the given points fall in each quadrant."""
    tally = {}
    for x, y in points:
        quadrant = get_quadrant(x, y)
        if quadrant not in tally:
            tally[quadrant] = 0
        tally[quadrant] += 1
    return tally


def main():
    samples = ["3, 5", "(-2 0)", "-4,-1.5", "[7, -3]", "0,0", "2.5 9", "3,5"]
    points = []
    for sample in samples:
        point = parse_point(sample)
        if point not in points:
            points.append(point)
            print(describe(*point))
    tally = summarize(points)
    print("--- totals ---")
    for quadrant in sorted(tally):
        print("quadrant %d: %d point(s)" % (quadrant, tally[quadrant]))


if __name__ == "__main__":
    main()

