import sys

NUMERIC_TYPES = (int, float)
ALLOWED_CHARS = set("0123456789+-.eE")
REPORT_ORDER = ("count", "median", "minimum", "maximum")
SERIES = {
    "odd": "1, 3, 2",
    "even": "1 4 2 3",
    "empty": "",
    "noisy": "5, abc, 7.5, 2",
}


def parse_number(token):
    """Convert a text token into an int or float, or return None if impossible."""
    text = token.strip()
    if not text:
        return None
    for ch in text:
        if ch not in ALLOWED_CHARS:
            return None
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return None


def parse_series(line):
    """Split a comma/space separated line into numbers and rejected tokens."""
    numbers = []
    rejected = []
    for token in line.replace(",", " ").split():
        value = parse_number(token)
        if value is None:
            if token not in rejected:
                rejected.append(token)
            continue
        numbers.append(value)
    return numbers, rejected


def validate_numbers(numbers):
    """Raise TypeError for any entry that is not a plain int or float."""
    for index, value in enumerate(numbers):
        if type(value) not in NUMERIC_TYPES:
            raise TypeError("element %d is not numeric: %r" % (index, value))


def calculate_median(numbers):
    validate_numbers(numbers)
    if not numbers:
        return None
    ordered = sorted(numbers)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2


def describe(numbers, rejected):
    """Build a small dictionary of statistics for a parsed series."""
    stats = {"count": len(numbers), "median": calculate_median(numbers)}
    if numbers:
        stats["minimum"] = min(numbers)
        stats["maximum"] = max(numbers)
    if rejected:
        stats["ignored"] = ",".join(rejected)
    return stats


def format_report(label, stats):
    parts = []
    for key in REPORT_ORDER:
        if key not in stats:
            continue
        value = stats[key]
        parts.append("%s=%s" % (key, "n/a" if value is None else value))
    for key in sorted(stats):
        if key not in REPORT_ORDER:
            parts.append("%s=%s" % (key, stats[key]))
    return "%-12s %s" % (label + ":", " ".join(parts))


def main():
    requested = sys.argv[1:] or list(SERIES)
    for name in requested:
        if name not in SERIES:
            print("%-12s unknown series" % (name + ":"))
            continue
        numbers, rejected = parse_series(SERIES[name])
        print(format_report(name, describe(numbers, rejected)))


if __name__ == "__main__":
    main()

