EXPENSE_FIELDS = ('description', 'amount', 'date')


def parse_date(date_str):
    """Validate a 'YYYY-MM-DD' string and return (year, month, day)."""
    if not isinstance(date_str, str):
        raise TypeError('date must be a string in YYYY-MM-DD format')
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError('malformed date: %r' % (date_str,))
    for part in parts:
        for ch in part:
            if ch not in '0123456789':
                raise ValueError('malformed date: %r' % (date_str,))
    year, month, day = (int(p) for p in parts)
    if month not in range(1, 13):
        raise ValueError('month out of range in %r' % (date_str,))
    lengths = [31, 29 if year % 4 == 0 and (year % 100 or year % 400 == 0) else 28,
               31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if day not in range(1, lengths[month - 1] + 1):
        raise ValueError('day out of range in %r' % (date_str,))
    return year, month, day


def record_expense(expenses, description, amount, date_str):
    """Append a new expense dictionary to the expenses list."""
    parse_date(date_str)
    if not isinstance(description, str) or not description.strip():
        raise ValueError('description must be a non-empty string')
    value = float(amount)
    expenses.append({'description': description, 'amount': value, 'date': date_str})


def monthly_totals(expenses):
    """Map 'YYYY-MM' to the sum of amounts recorded in that month."""
    totals = {}
    for expense in expenses:
        missing = [field for field in EXPENSE_FIELDS if field not in expense]
        if missing:
            raise KeyError('expense missing fields: %s' % ', '.join(missing))
        year, month, _day = parse_date(expense['date'])
        key = '%04d-%02d' % (year, month)
        if key not in totals:
            totals[key] = 0.0
        totals[key] += expense['amount']
    return totals


def format_report(expenses):
    """Build a plain-text report of expenses grouped by month."""
    totals = monthly_totals(expenses)
    lines = []
    for key in sorted(totals):
        lines.append('%s  total %10.2f' % (key, totals[key]))
        for expense in expenses:
            if not expense['date'].startswith(key):
                continue
            lines.append('    %-20s %8.2f  %s'
                         % (expense['description'], expense['amount'], expense['date']))
    if not lines:
        lines.append('(no expenses recorded)')
    return '\n'.join(lines)


def main():
    expenses = []
    entries = [
        ('Rent', 1000.0, '2023-10-01'),
        ('Groceries', 50.0, '2023-10-25'),
        ('Dinner', 25.50, '2023-10-26'),
        ('Gym', 39.99, '2023-11-02'),
        ('Books', -5.0, '2023-11-05'),
    ]
    for description, amount, date_str in entries:
        if amount <= 0:
            print('skipping %r: amount must be positive' % description)
            continue
        record_expense(expenses, description, amount, date_str)
    print(format_report(expenses))
    if '2023-12' not in monthly_totals(expenses):
        print('nothing recorded yet for December 2023')


if __name__ == '__main__':
    main()

