import string

STRIPPED = set(string.punctuation) - {"'", "-"}


def clean_token(token):
    """Drop punctuation from a token, keeping apostrophes and hyphens."""
    return "".join(char for char in token if char not in STRIPPED)


def tokenize(sentence):
    """Split a sentence into lowercase, punctuation-free words."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    words = []
    for raw in sentence.split():
        word = clean_token(raw).lower().strip("-")
        if any(char not in "'-" for char in word):
            words.append(word)
    return words


def group_by_length(sentence):
    """Group the distinct words of a sentence by their length."""
    groups = {}
    for word in tokenize(sentence):
        if len(word) not in groups:
            groups[len(word)] = []
        if word not in groups[len(word)]:
            groups[len(word)].append(word)
    return groups


def shortest_words(sentence):
    """Return the distinct words tying for the shortest length, in order."""
    words = tokenize(sentence)
    if not words:
        return []
    size = min(len(word) for word in words)
    tied = []
    for word in words:
        if len(word) != size:
            continue
        if word not in tied:
            tied.append(word)
    return tied


def find_shortest_word(sentence):
    """Return the first shortest word of the sentence, or '' if there is none."""
    tied = shortest_words(sentence)
    return tied[0] if tied else ""


def format_report(sentence):
    """Build a human-readable summary of the sentence's words."""
    groups = group_by_length(sentence)
    lines = ["Sentence: %r" % sentence]
    if not groups:
        lines.append("  (no words found)")
        return "\n".join(lines)
    for size in sorted(groups):
        lines.append("  length %d: %s" % (size, ", ".join(groups[size])))
    lines.append("  shortest: %s" % find_shortest_word(sentence))
    tied = shortest_words(sentence)
    if len(tied) > 1:
        lines.append("  also shortest: %s" % ", ".join(tied[1:]))
    return "\n".join(lines)


def main():
    samples = [
        "Hello world, this is a test.",
        "Programming is fun.",
        "To be or not to be, that is the question.",
        "",
    ]
    for sample in samples:
        print(format_report(sample))
        print()


if __name__ == "__main__":
    main()

