"""Finite geometric series: a + a*r + a*r^2 + ... + a*r^(n-1)."""

NUMERIC_TYPES = (int, float)
FIELD_NAMES = ("a", "r", "n")
OUTPUT_MODES = ("plain", "verbose")

def _check_number(name, value):
    if type(value) not in NUMERIC_TYPES:
        raise TypeError("%s must be an int or a float, got %r" % (name, value))

def _check_count(n):
    if type(n) is not int:
        raise TypeError("n must be an int, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)

def _parse_number(text):
    """An int when the field has no fractional part, a float otherwise."""
    if "." not in text:
        return int(text)
    return float(text)

def parse_case(text):
    """Parse an "a=1, r=2, n=3" specification into an (a, r, n) tuple."""
    fields = {}
    for chunk in text.split(","):
        chunk = chunk.strip()
        if "=" not in chunk:
            raise ValueError("field %r must look like name=value" % chunk)
        name, value = chunk.split("=", 1)
        name = name.strip()
        if name not in FIELD_NAMES:
            raise ValueError("unknown field %r in case %r" % (name, text))
        fields[name] = value.strip()
    for name in FIELD_NAMES:
        if name not in fields:
            raise ValueError("case %r is missing field %r" % (text, name))
    return _parse_number(fields["a"]), _parse_number(fields["r"]), int(fields["n"])

def geometric_series_sum(a, r, n):
    """Return the sum of the first n terms of a, a*r, a*r^2, ..."""
    _check_number("a", a)
    _check_number("r", r)
    _check_count(n)
    if n == 0:
        return 0
    if r == 1:
        return a * n
    numerator = a * (1 - r ** n)
    return numerator / (1 - r) if isinstance(numerator, float) else numerator // (1 - r)

def series_terms(a, r, n):
    """Return the individual terms of the series as a list."""
    _check_number("a", a)
    _check_number("r", r)
    _check_count(n)
    terms = []
    term = a
    for _ in range(n):
        terms.append(term)
        term = term * r
    return terms

def format_series(a, r, n, mode="plain"):
    """Render the series and its sum as a human readable string."""
    if mode not in OUTPUT_MODES:
        raise ValueError("unknown mode %r, expected one of %s" % (mode, OUTPUT_MODES))
    total = geometric_series_sum(a, r, n)
    if mode == "plain":
        return "sum = %s" % (total,)
    terms = series_terms(a, r, n)
    if not terms:
        return "empty series, sum = 0"
    note = "  (constant series)" if r == 1 else ""
    return "%s = %s%s" % (" + ".join(str(t) for t in terms), total, note)

def main():
    cases = ["a=1, r=2, n=3", "a=5, r=1, n=4", "a=2, r=0.5, n=5",
             "a=3, r=-2, n=4", "a=7, r=3, n=0"]
    for text in cases:
        a, r, n = parse_case(text)
        mode = "plain" if n > 4 else "verbose"
        print("a=%s r=%s n=%d -> %s" % (a, r, n, format_series(a, r, n, mode)))

if __name__ == "__main__":
    main()

