import math

NUMERIC_TYPES = (int, float)
POSITIONS = ("inside", "boundary", "outside")


def _check_number(name, value):
    if type(value) not in NUMERIC_TYPES:
        raise TypeError(f"{name} must be an int or float, got {type(value).__name__}")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError(f"{name} must be a finite number")
    return float(value)


def parse_point(text):
    if "," not in text:
        raise ValueError(f"point {text!r} must be written as 'x,y'")
    xs, ys = text.split(",", 1)
    return _check_number("x", float(xs)), _check_number("y", float(ys))


def is_point_in_circle(px, py, cx, cy, radius):
    px = _check_number("px", px)
    py = _check_number("py", py)
    cx = _check_number("cx", cx)
    cy = _check_number("cy", cy)
    radius = _check_number("radius", radius)
    if radius < 0:
        raise ValueError("radius must be non-negative")
    dx, dy = px - cx, py - cy
    return dx * dx + dy * dy <= radius * radius


def classify_point(px, py, cx, cy, radius, tolerance=1e-9):
    if not is_point_in_circle(px, py, cx, cy, radius):
        return "outside"
    if abs(math.hypot(px - cx, py - cy) - radius) <= tolerance:
        return "boundary"
    return "inside"


def summarize(points, cx, cy, radius):
    counts = {}
    for px, py in points:
        position = classify_point(px, py, cx, cy, radius)
        if position not in counts:
            counts[position] = 0
        counts[position] += 1
    return counts


def filter_points(points, cx, cy, radius, keep="inside"):
    if keep not in POSITIONS:
        raise ValueError(f"keep must be one of {POSITIONS}")
    return [(px, py) for px, py in points if classify_point(px, py, cx, cy, radius) == keep]


def format_report(points, cx, cy, radius):
    lines = [f"Circle center=({cx}, {cy}) radius={radius}"]
    for px, py in points:
        position = classify_point(px, py, cx, cy, radius)
        lines.append(f"  ({px:>6.2f}, {py:>6.2f}) -> {position}")
    counts = summarize(points, cx, cy, radius)
    for position in POSITIONS:
        if position not in counts:
            continue
        lines.append(f"  total {position}: {counts[position]}")
    return "\n".join(lines)


