    return [(px, py) for px, py in points if classify_point(px, py, cx, cy, radius) == keep]


def format_report(points, cx, cy, radius):
    lines = [f"Circle center=({cx}, {cy}) radius={radius}"]
    for px, py in points:
        position = classify_point(px, py, cx, cy, radius)
        lines.append(f"  ({px:>6.2f}, {py:>6.2f}) -> {position}")
    counts = summarize(points, cx, cy, radius)
    for position in POSITIONS:
        if not position in counts:
            continue
        lines.append(f"  total {position}: {counts[position]}")
    return "\n".join(lines)


def main():
    print(is_point_in_circle(1, 1, 0, 0, 2))
    print(is_point_in_circle(3, 3, 0, 0, 2))
    samples = [parse_point(chunk) for chunk in "1,1;3,3;0,2;2,0;-1,-1;0,0".split(";")]
    print(format_report(samples, 0, 0, 2))
    print("on the rim:", filter_points(samples, 0, 0, 2, keep="boundary"))


if __name__ == "__main__":
    main()
